#[derive(Deserialize)]
#[serde(tag = "type", content = "payload")]
enum ServerMessage {
    Job {
        #[serde(rename = "id")]
        _id: String,
    },
    Cancel {
        id: String,
    },
}

pub async fn run_worker(
    hive_url: String,
    node_id: String,
    secret: Option<String>,
    signing_key: ed25519_dalek::SigningKey,
    data_root: PathBuf,
    mut shutdown: broadcast::Receiver<()>,
) {
    crate::nice::configure_global_thread_pool(false);
    crate::nice::set_background_priority();

    let client = network::build_client(&hive_url, secret.clone());
    info!(node_id = %node_id, "agent initializing");
    let _ = crate::agent::maintenance::prune_stale_data(data_root.clone()).await;

    let topo = hw_detect::detect_topology().await;
    let ops_per_sec: f64 =
        tokio::task::spawn_blocking(crate::agent::calibration::measure_performance)
            .await
            .unwrap_or(5_000_000.0);

    let public_key = ed25519_dalek::VerifyingKey::from(&signing_key);

    let req = NodeRequest {
        version: PROTOCOL_VERSION,
        node_id: node_id.clone(),
        cpu_model: topo.model.clone(),
        cores: (topo.cores as i32).max(1),
        l2_cache_kb: topo.l2_kb.map(|x| (x as i32).max(0)),
        ops_per_sec: ops_per_sec as f32,
        public_key: Some(hex::encode(public_key.to_bytes())),
    };

    let _ = network::register_node(&client, &req, 4).await;

    if let Err(e) = initialize_workspace(&data_root, keyforge_infra::InitMode::Validate) {
        error!(error = %e, "workspace initialization failed");
    }

    let outbox = Arc::new(network::ResultOutbox::new(
        client.clone(),
        data_root.clone(),
        100,
    ));

    let compute_limiter = Arc::new(Semaphore::new(topo.cores.max(1)));

    let ws_url = match Url::parse(&hive_url) {
        Ok(mut u) => {
            let scheme = if u.scheme() == "https" { "wss" } else { "ws" };
            let _ = u.set_scheme(scheme);
            if let Ok(mut segments) = u.path_segments_mut() {
                segments.push("ws");
            }
            u.to_string()
        }
        Err(_) => {
            error!(url = %hive_url, "invalid hive url");
            return;
        }
    };

    // Health Check Server
    let health_port = std::env::var("HEALTH_CHECK_PORT").unwrap_or_else(|_| "9090".to_string());
    let health_handle = tokio::spawn(async move {
        let addr = format!("0.0.0.0:{}", health_port);
        if let Ok(listener) = tokio::net::TcpListener::bind(&addr).await {
            info!(port = %health_port, "health check listening");
            loop {
                if let Ok((mut socket, _)) = listener.accept().await {
                    tokio::spawn(async move {
                        let _ = tokio::time::timeout(Duration::from_secs(5), async move {
                            use tokio::io::AsyncWriteExt;
                            let _ = socket
                                .write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n")
                                .await;
                            let _ = socket.shutdown().await;
                        })
                        .await;
                    });
                }
            }
        }
    });

    let mut retry_delay = 1;
    let max_retry = 30;

    loop {
        if shutdown.try_recv().is_ok() {
            info!("agent shutting down");
            break;
        }

        match connect_async(&ws_url).await {
            Ok((ws_stream, _)) => {
                info!("connected, waiting for work");
                retry_delay = 1;

                process_connection(
                    ws_stream,
                    &client,
                    &outbox,
                    &node_id,
                    &data_root,
                    &signing_key,
                    &compute_limiter,
                    &mut shutdown,
                )
                .await;
            }
            Err(e) => {
                warn!(error = %e, delay = %retry_delay, "connection failed, retrying");
                tokio::select! {
                    _ = shutdown.recv() => return,
                    _ = tokio::time::sleep(Duration::from_secs(retry_delay)) => {
                        retry_delay = (retry_delay * 2).min(max_retry);
                    }
                }
            }
        }
    }

    health_handle.abort();
}

#[allow(clippy::too_many_arguments)]
async fn process_connection(
    mut ws_stream: tokio_tungstenite::WebSocketStream<
        tokio_tungstenite::MaybeTlsStream<tokio::net::TcpStream>,
    >,
    client: &HiveClient,
    outbox: &Arc<network::ResultOutbox>,
    node_id: &str,
    data_root: &std::path::Path,
    signing_key: &ed25519_dalek::SigningKey,
    compute_limiter: &Arc<Semaphore>,
    shutdown: &mut broadcast::Receiver<()>,
) {
    let mut active_job_handle: Option<tokio::task::JoinHandle<()>> = None;
    let mut active_stop_flag: Option<Arc<AtomicBool>> = None;
    let mut active_job_id: Option<String> = None;
    let mut check_queue = true;

    loop {
        if active_job_handle.is_none() && check_queue {
            check_queue = false;
            if let Some((job_id, config)) = network::fetch_job_queue(client).await {
                info!(job_id = %job_id, "processing job");

                let outbox_clone = outbox.clone();
                let node_id_clone = node_id.to_string();
                let data_root_clone = data_root.to_path_buf();
                let client_clone = client.clone();
                let signing_key = Arc::new(signing_key.clone());
                let limiter_clone = compute_limiter.clone();

                let stop_flag = Arc::new(AtomicBool::new(false));
                active_stop_flag = Some(stop_flag.clone());
                active_job_id = Some(job_id.clone());

                let job_id_task = job_id.clone();

                let spawn_res = tokio::spawn(async move {
                    let compute_res = async {
                        let loader =
                            Box::new(keyforge_infra::FsProvider::new(data_root_clone.clone()));

                        let asset_manager = keyforge_infra::AssetManager::new(
                            client_clone.clone(),
                            data_root_clone.clone(),
                        );

                        let (cost_path, corpus_root) =
                            compute::prepare_assets(&asset_manager, &config).await?;

                        let prepared = compute::create_engine_request(
                            loader,
                            data_root_clone,
                            &config,
                            &cost_path,
                            &corpus_root,
                        )?;

                        let registry = prepared.registry.clone();

                        let result = compute::run_optimization(
                            prepared.req,
                            job_id_task.clone(),
                            stop_flag,
                            limiter_clone,
                        )
                        .await?;

                        info!(
                            job_id = %job_id_task,
                            fast_score = result.score,
                            "optimization complete"
                        );

                        // --- DETERMINISTIC RECALCULATION ---
                        // We ignore the score from the optimizer (approximate float math)
                        // and recalculate using the Sidecar (exact integer math).
                        let deterministic_score = DeterministicScorer::score(
                            &prepared.keyboard,
                            &prepared.corpus,
                            &prepared.rubric,
                            &result.layout,
                        );

                        // Silence Protocol: Discard if no improvement over baseline
                        if let Some(baseline) = config.baseline_score {
                            if deterministic_score >= baseline {
                                info!(
                                    job_id = %job_id_task,
                                    score = deterministic_score,
                                    baseline = baseline,
                                    "result discarded (no improvement)"
                                );
                                return Ok(());
                            }
                        }

                        let layout_str = result
                            .layout
                            .keys
                            .iter()
                            .map(|&c| registry.get_label(c))
                            .collect::<Vec<String>>()
                            .join(" ");

                        let timestamp = SystemTime::now()
                            .duration_since(UNIX_EPOCH)
                            .unwrap_or(Duration::from_secs(0))
                            .as_secs();

                        let nonce = OsRng.gen::<u64>();

                        // Sign the DETERMINISTIC score
                        let signature = crypto::sign_result_direct(
                            &signing_key,
                            &job_id_task,
                            &layout_str,
                            deterministic_score,
                            timestamp,
                            nonce,
                        )
                        .map_err(|e| anyhow::anyhow!("signing failed: {:?}", e))?;

                        let _ = outbox_clone.try_send(ResultSubmission {
                            version: PROTOCOL_VERSION,
                            job_id: job_id_task,
                            layout: layout_str,
                            score: deterministic_score,
                            node_id: node_id_clone,
                            timestamp,
                            nonce,
                            signature: Some(signature),
                        });
                        Ok::<(), anyhow::Error>(())
                    }
                    .await;

                    if let Err(e) = compute_res {
                        error!(error = %e, "compute error");
                    }
                });

                active_job_handle = Some(spawn_res);
            }
        }

        tokio::select! {
            biased;

            _ = shutdown.recv() => {
                info!("agent shutting down (signal received)");
                if let Some(flag) = active_stop_flag {
                    flag.store(true, Ordering::SeqCst);
                }
                if let Some(handle) = active_job_handle {
                    let _ = handle.await;
                }
                return;
            }

            msg = ws_stream.next() => {
                match msg {
                    Some(Ok(Message::Text(txt))) => {
                        if let Ok(server_msg) = serde_json::from_str::<ServerMessage>(&txt) {
                            match server_msg {
                                ServerMessage::Job { .. } => {
                                    info!("job signal received");
                                    check_queue = true;
                                }
                                ServerMessage::Cancel { id } => {
                                    if let Some(current_id) = &active_job_id {
                                        if current_id == &id {
                                            info!(job_id = %id, "cancellation received");
                                            if let Some(flag) = &active_stop_flag {
                                                flag.store(true, Ordering::SeqCst);
                                            }
                                        }
                                    }
                                }
                            }
                        } else if txt.contains("\"type\":\"Job\"") {
                            check_queue = true;
                        }
                    }
                    Some(Ok(Message::Ping(d))) => {
                        if let Err(e) = ws_stream.send(Message::Pong(d)).await {
                            warn!(error = %e, "failed to send pong");
                            break;
                        }
                    }
                    Some(Err(e)) => {
                        warn!(error = %e, "websocket error");
                        break;
                    }
                    None => break,
                    _ => {}
                }
            }

            _ = async {
                if let Some(h) = active_job_handle.as_mut() {
                    h.await.ok();
                    true
                } else {
                    std::future::pending().await
                }
            }, if active_job_handle.is_some() => {
                active_job_handle = None;
                active_stop_flag = None;
                active_job_id = None;
                check_queue = true;
            }

            _ = tokio::time::sleep(Duration::from_secs(30)), if active_job_handle.is_none() => {
                check_queue = true;
            }
        }
    }
}

// ===== keyforge/crates/keyforge-agent/src/agent/network.rs =====
use ed25519_dalek::{Signature, Verifier, VerifyingKey};
use keyforge_infra::HiveClient;
use keyforge_protocol::{
    JobConfig, JobQueueResponse, NodeRequest, NodeResponse, PopulationResponse, ResultSubmission,
    TuningProfile,
};
use rand::Rng;
use std::path::PathBuf;
use std::time::{Duration, Instant};
use tokio::fs;
use tokio::sync::mpsc;
use tracing::{error, info, warn};
use uuid::Uuid;

/// Constructs a HiveClient with optional authentication secret.
#[must_use]
pub fn build_client(base_url: &str, secret: Option<String>) -> HiveClient {
    match HiveClient::new(base_url.to_string(), secret) {
        Ok(c) => c,
        Err(e) => {
            warn!(
                error = %e,
                "failed to build HiveClient, retrying with defaults"
            );
            HiveClient::new(base_url.to_string(), None).unwrap()
        }
    }
}

/// Registers the node with the Hive server and retrieves a tuning profile.
#[must_use]
pub async fn register_node(
    client: &HiveClient,
    req: &NodeRequest,
    default_threads: usize,
) -> TuningProfile {
    match client
        .post("nodes/register")
        .header("Content-Type", "application/json")
        .json(req)
        .send()
        .await
    {
        Ok(res) => {
            if res.status() == 401 {
                error!(node_id = %req.node_id, "auth failure: Hive rejected connection, check HIVE_SECRET");
                std::process::exit(1);
            }
            match res.json::<NodeResponse>().await {
                Ok(r) => r.tuning,
                Err(_) => TuningProfile {
                    strategy: "fly".into(),
                    batch_size: 10000,
                    thread_count: default_threads,
                },
            }
        }
        Err(e) => {
            warn!(error = %e, "failed to register node, defaulting");
            TuningProfile {
                strategy: "fly".into(),
                batch_size: 10000,
                thread_count: default_threads,
            }
        }
    }
}

/// Fetches the next available job from the Hive queue.
#[must_use]
pub async fn fetch_job_queue(client: &HiveClient) -> Option<(String, JobConfig)> {
    match client.get("jobs/queue").send().await {
        Ok(r) => {
            let resp = r
                .json::<JobQueueResponse>()
                .await
                .unwrap_or(JobQueueResponse {
                    job_id: None,
                    config: None,
                });
            match (resp.job_id, resp.config) {
                (Some(id), Some(cfg)) => Some((id, cfg)),
                _ => None,
            }
        }
        Err(e) => {
            warn!(error = %e, "failed to fetch job queue");
            None
        }
    }
}

/// Retrieves the current population of layouts for a given job.
#[must_use]
pub async fn fetch_population(client: &HiveClient, job_id: &str) -> Vec<String> {
    match client
        .get(&format!("jobs/{}/population", job_id))
        .send()
        .await
    {
        Ok(r) => {
            let resp = r.json::<PopulationResponse>().await.ok();
            resp.map(|r| r.layouts).unwrap_or_default()
        }
        Err(_) => vec![],
    }
}

// --- CIRCUIT BREAKER ---

#[derive(Debug)]
pub struct CircuitBreaker {
    failures: u32,
    threshold: u32,
    last_failure: Option<Instant>,
    cooldown: Duration,
}

impl CircuitBreaker {
    #[must_use]
    pub fn new(threshold: u32, cooldown_secs: u64) -> Self {
        Self {
            failures: 0,
            threshold,
            last_failure: None,
            cooldown: Duration::from_secs(cooldown_secs),
        }
    }

    pub fn can_attempt(&self) -> bool {
        if self.failures < self.threshold {
            return true;
        }
        if let Some(last) = self.last_failure {
            if last.elapsed() >= self.cooldown {
                return true;
            }
        }
        false
    }

    pub fn record_success(&mut self) {
        if self.failures > 0 {
            info!("circuit breaker recovered");
        }
        self.failures = 0;
        self.last_failure = None;
    }

    pub fn record_failure(&mut self) {
        self.failures += 1;
        self.last_failure = Some(Instant::now());
        if self.failures == self.threshold {
            warn!(
                failures = self.failures,
                cooldown_secs = self.cooldown.as_secs(),
                "circuit breaker tripped"
            );
        }
    }
}

// --- ASYNC OUTBOX WITH PERSISTENCE ---

pub struct ResultOutbox {
    sender: mpsc::Sender<ResultSubmission>,
}

impl ResultOutbox {
    #[must_use]
    pub fn new(client: HiveClient, data_root: PathBuf, buffer_size: usize) -> Self {
        let (tx, mut rx) = mpsc::channel::<ResultSubmission>(buffer_size);
        // CHANGED: Use user/agent_wal
        let wal_dir = data_root.join("user/agent_wal");

        tokio::spawn(async move {
            info!("result outbox started");
            let mut cb = CircuitBreaker::new(5, 30);

            if let Err(e) = fs::create_dir_all(&wal_dir).await {
                error!(directory = %wal_dir.display(), error = %e, "failed to create WAL directory");
            }

            if let Ok(mut entries) = fs::read_dir(&wal_dir).await {
                while let Ok(Some(entry)) = entries.next_entry().await {
                    let path = entry.path();
                    if path.extension().and_then(|s| s.to_str()) == Some("json") {
                        if let Ok(content) = fs::read_to_string(&path).await {
                            if let Ok(sub) = serde_json::from_str::<ResultSubmission>(&content) {
                                info!(job_id = %sub.job_id, "recovered unsent result");
                                if send_with_retry(&client, &sub, &mut cb).await {
                                    let _ = fs::remove_file(path).await;
                                }
                            }
                        }
                    }
                }
            }

            while let Some(submission) = rx.recv().await {
                let wal_id = Uuid::new_v4();
                let wal_path = wal_dir.join(format!("{}.json", wal_id));

                if let Ok(json) = serde_json::to_string(&submission) {
                    if let Err(e) = fs::write(&wal_path, json).await {
                        error!(path = %wal_path.display(), error = %e, "failed to write WAL");
                    }
                }

                if !cb.can_attempt() {
                    warn!(
                        job_id = %submission.job_id,
                        "circuit breaker open, result queued in WAL"
                    );
                    continue;
                }

                if send_with_retry(&client, &submission, &mut cb).await {
                    let _ = fs::remove_file(&wal_path).await;
                } else {
                    error!(job_id = %submission.job_id, "failed to submit result, persisted to WAL");
                }
            }
            info!("result outbox stopped");
        });

        Self { sender: tx }
    }

    pub fn try_send(&self, result: ResultSubmission) -> Result<(), anyhow::Error> {
        match self.sender.try_send(result) {
            Ok(_) => Ok(()),
            Err(mpsc::error::TrySendError::Full(_)) => {
                warn!("outbox full, back-pressure triggered");
                Err(anyhow::anyhow!("outbox full"))
            }
            Err(e) => Err(anyhow::anyhow!("send error: {}", e)),
        }
    }
}

async fn send_with_retry(
    client: &HiveClient,
    submission: &ResultSubmission,
    cb: &mut CircuitBreaker,
) -> bool {
    let mut attempts = 0;
    let max_attempts = 3;

    while attempts < max_attempts {
        match client
            .post("results")
            .header("Content-Type", "application/json")
            .json(submission)
            .send()
            .await
        {
            Ok(resp) => {
                if resp.status().is_success() {
                    cb.record_success();
                    return true;
                } else {
                    warn!(
                        status = %resp.status(),
                        job_id = %submission.job_id,
                        "submission rejected"
                    );
                    if resp.status().as_u16() >= 400 && resp.status().as_u16() < 500 {
                        return true;
                    }
                }
            }
            Err(e) => {
                warn!(error = %e, "network error sending result");
            }
        }

        attempts += 1;
        if attempts < max_attempts {
            let base_backoff = 500 * (1 << attempts);
            let jitter = rand::thread_rng().gen_range(0..500);
            let backoff = Duration::from_millis(base_backoff + jitter);
            tokio::time::sleep(backoff).await;
        }
    }

    cb.record_failure();
    false
}

/// Verifies the identity of the Hive server using a pinned public key.
pub fn verify_server_identity(
    server_public_key: &str,
    challenge: &str,
    signature: &str,
) -> Result<bool, String> {
    if server_public_key.is_empty() {
        return Ok(true); // Dev mode / No pinning
    }

    let public_bytes =
        hex::decode(server_public_key).map_err(|_| "Invalid public key hex".to_string())?;

    let public_key = VerifyingKey::from_bytes(
        public_bytes
            .as_slice()
            .try_into()
            .map_err(|_| "Invalid key length")?,
    )
    .map_err(|e| e.to_string())?;

    let sig_bytes = hex::decode(signature).map_err(|_| "Invalid signature hex".to_string())?;

    let sig = Signature::from_bytes(
        sig_bytes
            .as_slice()
            .try_into()
            .map_err(|_| "Invalid signature length")?,
    );

    public_key
        .verify(challenge.as_bytes(), &sig)
        .map(|_| true)
        .map_err(|e| e.to_string())
}

use keyforge_core::ProgressCallback;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use tracing::info;

/// A logger that tracks optimization progress and reports it back to the system.
///
/// It also monitors a `stop_flag` to allow for early termination of the optimization process.
pub struct WorkerLogger {
    pub stop_flag: Arc<AtomicBool>,
    pub job_id: String,
}

impl ProgressCallback for WorkerLogger {
    /// Called by the optimizer to report current progress.
    ///
    /// # Parameters
    /// - `step`: The current iteration step.
    /// - `score`: The current best score.
    /// - `_layout`: The current layout (unused by this logger).
    /// - `ips`: Iterations per second.
    ///
    /// Returns `false` if the optimization should stop immediately.
    fn on_progress(&self, step: usize, score: f32, _layout: &[u16], ips: f32) -> bool {
        // Task 12: Use SeqCst for AtomicBool memory ordering
        if self.stop_flag.load(Ordering::SeqCst) {
            return false;
        }

        // Deterministic Sampling:
        // We want to log ~1% of steps, but consistently for the same job/step combo.
        let mut hasher = DefaultHasher::new();
        self.job_id.hash(&mut hasher);
        step.hash(&mut hasher);
        let hash = hasher.finish();

        // 1% sample rate (approx)
        if hash.is_multiple_of(100) {
            // Task 27: Structured logging
            info!(
                job_id = %self.job_id,
                step = step,
                score = score,
                ips = ips,
                "optimization progress"
            );
        }
        true
    }
}

use serde::{Deserialize, Serialize};
use sysinfo::{CpuRefreshKind, RefreshKind, System};
use tokio;
use tracing::{info, warn};

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct CpuCacheTopology {
    pub model: String,
    pub architecture: String,
    pub cores: usize,
    pub l1_data_kb: Option<usize>,
    pub l2_kb: Option<usize>,
    pub l3_kb: Option<usize>,
}

impl Default for CpuCacheTopology {
    fn default() -> Self {
        Self {
            model: "Unknown".to_string(),
            architecture: std::env::consts::ARCH.to_string(),
            cores: 1,
            l1_data_kb: None,
            l2_kb: None,
            l3_kb: None,
        }
    }
}

/// Detects the CPU topology and cache sizes of the host machine.
///
/// This information is used to tune the optimization process (e.g., fitting data structures in L2).
#[must_use]
pub async fn detect_topology() -> CpuCacheTopology {
    let mut topo = CpuCacheTopology::default();

    let mut sys =
        System::new_with_specifics(RefreshKind::nothing().with_cpu(CpuRefreshKind::everything()));
    tokio::time::sleep(sysinfo::MINIMUM_CPU_UPDATE_INTERVAL).await;
    sys.refresh_all();

    if let Some(cpu) = sys.cpus().first() {
        topo.model = cpu.brand().trim().to_string();
    }
    topo.cores = sys.cpus().len();

    #[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
    {
        detect_x86_caches(&mut topo);
    }

    #[cfg(target_os = "macos")]
    {
        detect_macos_caches(&mut topo);
    }

    #[cfg(all(target_os = "windows", target_arch = "aarch64"))]
    {
        detect_windows_arm_caches(&mut topo);
    }

    // Task 27: Structured logging
    info!(
        model = %topo.model,
        cores = topo.cores,
        "hardware detected"
    );
    if let Some(l2) = topo.l2_kb {
        info!(l2_kb = l2, "L2 cache detected, tuning for trigram table");
    } else {
        warn!("L2 cache size unknown, using safe defaults for sizing");
    }

    topo
}

/// Returns a list of SIMD features the binary was compiled for.
#[must_use]
pub fn get_compile_features() -> &'static [&'static str] {
    if cfg!(target_feature = "avx512f") {
        &["AVX512"]
    } else if cfg!(target_feature = "avx2") {
        &["AVX2"]
    } else if cfg!(target_feature = "avx") {
        &["AVX"]
    } else if cfg!(target_feature = "sse4.2") {
        &["SSE4.2"]
    } else if cfg!(target_feature = "sse2") {
        &["SSE2"]
    } else if cfg!(target_feature = "neon") {
        &["NEON"]
    } else {
        &["SCALAR (No SIMD)"]
    }
}

#[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
fn detect_x86_caches(topo: &mut CpuCacheTopology) {
    use raw_cpuid::{CacheType, CpuId};
    let cpuid = CpuId::new();
    if let Some(caches) = cpuid.get_cache_parameters() {
        for cache in caches {
            let size_kb_u64 = (cache.sets() as u64
                * cache.associativity() as u64
                * cache.coherency_line_size() as u64)
                / 1024;
            let size_kb = u64_to_usize_saturating(size_kb_u64);

            match cache.level() {
                1 => {
                    if cache.cache_type() == CacheType::Data {
                        topo.l1_data_kb = Some(size_kb);
                    }
                }
                2 => topo.l2_kb = Some(size_kb),
                3 => topo.l3_kb = Some(size_kb),
                _ => {}
            }
        }
    }
}

#[cfg(target_os = "macos")]
fn detect_macos_caches(topo: &mut CpuCacheTopology) {
    // Task 52: Avoid sysctl binary spawn, use libc
    use libc::{size_t, sysctlbyname};
    use std::ptr;

    fn get_sysctl_u64(name: &str) -> Option<u64> {
        let mut value: u64 = 0;
        let mut size = std::mem::size_of::<u64>() as size_t;
        let c_name = std::ffi::CString::new(name).ok()?;
        // SAFETY: sysctlbyname is a safe call with valid pointers
        unsafe {
            if sysctlbyname(
                c_name.as_ptr(),
                &mut value as *mut _ as *mut _,
                &mut size,
                ptr::null_mut(),
                0,
            ) == 0
            {
                Some(value)
            } else {
                None
            }
        }
    }

    if let Some(bytes) = get_sysctl_u64("hw.l1dcachesize") {
        topo.l1_data_kb = Some(u64_to_usize_saturating(bytes / 1024));
    }
    if let Some(bytes) = get_sysctl_u64("hw.l2cachesize") {
        topo.l2_kb = Some(u64_to_usize_saturating(bytes / 1024));
    }
    if let Some(bytes) = get_sysctl_u64("hw.l3cachesize") {
        topo.l3_kb = Some(u64_to_usize_saturating(bytes / 1024));
    }
}

#[cfg(all(target_os = "windows", target_arch = "aarch64"))]
fn detect_windows_arm_caches(topo: &mut CpuCacheTopology) {
    // Task 51: ARM-Windows cache detection
    use std::alloc::{alloc, Layout};
    use windows_sys::Win32::System::SystemInformation::{
        GetLogicalProcessorInformationEx, RelationCache, SYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX,
    };

    let mut len: u32 = 0;
    // SAFETY: First call to get required buffer size
    unsafe {
        GetLogicalProcessorInformationEx(RelationCache, ptr::null_mut(), &mut len);
    }
    if len == 0 {
        return;
    }

    let layout = Layout::from_size_align(
        len as usize,
        std::mem::align_of::<SYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX>(),
    )
    .unwrap();
    let ptr = unsafe { alloc(layout) };
    if ptr.is_null() {
        return;
    }

    // SAFETY: Buffer allocated with correct size and alignment
    unsafe {
        if GetLogicalProcessorInformationEx(RelationCache, ptr as *mut _, &mut len) != 0 {
            let mut offset = 0;
            while offset < len {
                let info =
                    &*(ptr.add(offset as usize) as *const SYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX);
                // RELATION_CACHE_INFORMATION is at the end of the union
                let cache = &info.u.Cache;
                let size_kb_u64 = (cache.Size as u64 / 1024);
                let size_kb = u64_to_usize_saturating(size_kb_u64);

                match cache.Level {
                    1 => topo.l1_data_kb = Some(size_kb),
                    2 => topo.l2_kb = Some(size_kb),
                    3 => topo.l3_kb = Some(size_kb),
                    _ => {}
                }
                offset += info.Size;
            }
        }
        std::alloc::dealloc(ptr, layout);
    }
}

/// Safely casts a u64 to usize, saturating at usize::MAX and warning if truncation occurs.
/// This prevents integer overflow issues on 32-bit systems when handling large cache sizes.
fn u64_to_usize_saturating(value: u64) -> usize {
    if value > usize::MAX as u64 {
        warn!(
            "Value {} exceeds platform usize limit {}, saturating to limit.",
            value,
            usize::MAX
        );
        usize::MAX
    } else {
        value as usize
    }
}

