    writeln!(
        f,
        r#"[{{ "code": 97, "id": "KC_A", "label": "a", "aliases": [] }}]"#
    )
    .unwrap();

    let geometry = KeyboardGeometry {
        keys: vec![KeyNode {
            id: "KC_A".into(),
            ..KeyNode::default()
