use keyforge_protocol::config::CorpusSource;
use keyforge_protocol::KeyConstraint;
use std::path::{Path, PathBuf};
use std::str::FromStr;

pub fn parse_key_constraint(s: &str) -> Result<KeyConstraint, String> {
    KeyConstraint::from_str(s)
}

pub fn resolve_path(input: &str, subdir: Option<&str>, root: &Path) -> Result<PathBuf, String> {
    let input_path = Path::new(input);

    // 1. Absolute paths: Always allowed for CLI users.
    if input_path.is_absolute() {
        if input_path.exists() {
            return Ok(input_path.to_path_buf());
        } else {
            return Err(format!("Absolute path does not exist: {}", input));
        }
    }

    // 2. Explicit CWD-relative paths (./ or ../)
    if input.starts_with("./") || input.starts_with("../") {
        if let Ok(cwd) = std::env::current_dir() {
            let p = cwd.join(input);
            if p.exists() {
                return Ok(p);
            }
        }
    }

    // 3. Workspace Resolution (Overlay: user -> system -> root)
    let sub = subdir.unwrap_or("");

    // Check user/{subdir}/{input}
    let user_path = root.join("user").join(sub).join(input);
    if user_path.exists() {
        return Ok(user_path);
    }
    // Try with .json
    if !input.ends_with(".json") {
        let user_json = user_path.with_extension("json");
        if user_json.exists() {
            return Ok(user_json);
        }
    }

    // Check system/{subdir}/{input}
    let system_path = root.join("system").join(sub).join(input);
    if system_path.exists() {
        return Ok(system_path);
    }
    // Try with .json
    if !input.ends_with(".json") {
        let system_json = system_path.with_extension("json");
        if system_json.exists() {
            return Ok(system_json);
        }
    }

    // Check root/{subdir}/{input} (Legacy/Fallback)
    let root_sub_path = root.join(sub).join(input);
    if root_sub_path.exists() {
        return Ok(root_sub_path);
    }
    if !input.ends_with(".json") {
        let root_json = root_sub_path.with_extension("json");
        if root_json.exists() {
            return Ok(root_json);
        }
    }

    // 4. Root-relative fallback (Directly in data root)
    let root_direct = root.join(input);
    if root_direct.exists() {
        return Ok(root_direct);
    }
    if !input.ends_with(".json") {
        let root_direct_json = root_direct.with_extension("json");
        if root_direct_json.exists() {
            return Ok(root_direct_json);
        }
    }

    Err(format!(
        "Could not resolve path '{}'. Checked absolute, CWD, and workspace '{:?}' overlays.",
        input, subdir
    ))
}

pub fn parse_keyboard(s: &str) -> Result<String, String> {
    if s.len() > 100 {
        return Err("keyboard name must be <= 100 chars".into());
    }
    let s = s.trim();
    if s.is_empty() {
        return Err("keyboard name cannot be empty".into());
    }
    Ok(s.into())
}

pub fn parse_cost(s: &str) -> Result<String, String> {
    if s.len() > 255 {
        return Err("cost matrix filename must be <= 255 chars".into());
    }
    let s = s.trim();
    if s.is_empty() {
        return Err("cost matrix filename cannot be empty".into());
    }
    Ok(s.into())
}

pub fn parse_corpora(args: &[String]) -> Result<Vec<CorpusSource>, String> {
    if args.len() > 50 {
        return Err("Too many corpora sources (limit 50)".into());
    }
    args.iter().map(|s| CorpusSource::from_str(s)).collect()
}

use crate::error::{CliError, Result};
use clap::{Args, Subcommand};
use serde::{Deserialize, Serialize};
use std::path::PathBuf;

#[derive(Args, Debug, Clone)]
pub struct AuthArgs {
    #[command(subcommand)]
    pub command: AuthCommands,

    #[arg(long, default_value = "http://localhost:3000")]
    pub hive: String,
}

#[derive(Subcommand, Debug, Clone)]
pub enum AuthCommands {
    /// Register a new user account
    Register {
        #[arg(short, long)]
        username: String,
    },
    /// Manually save an existing API Key
    Login {
        #[arg(short, long)]
        key: String,
    },
    /// Show current authentication status
    Whoami,
}

#[derive(Serialize, Deserialize)]
struct CliConfig {
    api_key: Option<String>,
}

fn get_config_path() -> Result<PathBuf> {
    let mut path =
        dirs::config_dir().ok_or_else(|| CliError::Other("Could not find config dir".into()))?;
    path.push("keyforge");
    std::fs::create_dir_all(&path).map_err(CliError::Io)?;
    path.push("cli.json");
    Ok(path)
}

fn save_key(key: &str) -> Result<()> {
    let path = get_config_path()?;
    let config = CliConfig {
        api_key: Some(key.to_string()),
    };
    let json = serde_json::to_string_pretty(&config)?;
    std::fs::write(path, json).map_err(CliError::Io)?;
    Ok(())
}

pub fn load_key() -> Option<String> {
    let path = get_config_path().ok()?;
    if !path.exists() {
        return None;
    }
    let content = std::fs::read_to_string(path).ok()?;
    let config: CliConfig = serde_json::from_str(&content).ok()?;
    config.api_key
}

pub async fn run(args: AuthArgs) -> Result<()> {
    match args.command {
        AuthCommands::Register { username } => {
            let client = reqwest::Client::new();
            let url = format!("{}/auth/register", args.hive);

            eprintln!("🌐 Registering '{}' at {}...", username, args.hive);

            let res = client
                .post(&url)
                .json(&serde_json::json!({ "username": username }))
                .send()
                .await
                .map_err(CliError::Network)?;

            if res.status().is_success() {
                let body: serde_json::Value = res.json().await.map_err(CliError::Network)?;
                if let Some(key) = body.get("api_key").and_then(|s| s.as_str()) {
                    save_key(key)?;
                    println!("✅ Registration successful!");
                    println!("🔑 API Key: {}", key);
                    println!(
                        "   (Saved to config. You can now run searches as '{}')",
                        username
                    );
                } else {
                    return Err(CliError::Other("Invalid server response".into()));
                }
            } else if res.status() == 409 {
                return Err(CliError::Other(format!(
                    "Username '{}' is already taken.",
                    username
                )));
            } else {
                return Err(CliError::Other(format!(
                    "Registration failed: {}",
                    res.status()
                )));
            }
        }
        AuthCommands::Login { key } => {
            save_key(&key)?;
            println!("✅ API Key saved.");
        }
        AuthCommands::Whoami => {
            if let Some(key) = load_key() {
                let masked = format!("{}...{}", &key[0..6], &key[key.len() - 4..]);
                println!("👤 Authenticated");
                println!("🔑 Key: {}", masked);
            } else {
                println!("👤 Not logged in.");
            }
        }
    }
    Ok(())
}

use clap::Args;
use keyforge_compute::Runtime;
use std::time::Instant;

#[derive(Args, Debug, Clone)]
pub struct BenchmarkArgs {
    #[command(flatten)]
    pub config: crate::cli_args::config::ConfigArgs,
    #[arg(long, default_value_t = 100_000)]
    pub iterations: usize,
    #[command(flatten)]
    pub shared: crate::cmd::shared::SharedArgs,
}

pub fn run(args: BenchmarkArgs, runtime: Runtime) -> Result<(), Box<dyn std::error::Error>> {
    eprintln!("📊 Benchmarking Engine ({} iterations)...", args.iterations);

    // Create a dummy layout for benchmarking
    // We need a layout that matches the key count of the engine
    let key_count = runtime.engine.key_count();
    let layout = keyforge_model::Layout::new((0..key_count).map(|i| i as u16).collect());

    let start = Instant::now();
    let mut score = 0.0;

    for _ in 0..args.iterations {
        score += runtime.score(&layout);
    }

    let duration = start.elapsed();
    let kops = (args.iterations as f64 / duration.as_secs_f64()) / 1000.0;

    eprintln!("Finished in {:.2?}", duration);
    eprintln!("Throughput: {:.2} kOPS", kops);
    eprintln!("CheckSum: {:.2}", score); // Prevent optimization

    Ok(())
}

