use clap::Args;
use std::path::Path;
use sysinfo::System;

#[derive(Args, Debug, Clone)]
pub struct DoctorArgs {}

pub fn run(_args: DoctorArgs, root: &Path) -> Result<(), Box<dyn std::error::Error>> {
    eprintln!("🩺 KeyForge Doctor");
    eprintln!("========================================");

    // 1. System Check
    let mut sys = System::new_all();
    sys.refresh_all();

    let os = System::name().unwrap_or("Unknown".into());
    let os_ver = System::os_version().unwrap_or("?".into());
    let mem_total = sys.total_memory() / 1024 / 1024;
    let mem_used = sys.used_memory() / 1024 / 1024;

    eprintln!("🖥️  System");
    eprintln!("   OS:       {} {}", os, os_ver);
    eprintln!("   Memory:   {} / {} MB", mem_used, mem_total);

    // 2. CPU Capabilities
    eprintln!("\n⚡ Processor");
    let cpu_count = num_cpus::get();
    eprintln!("   Cores:    {}", cpu_count);

    #[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
    {
        if is_x86_feature_detected!("avx2") {
            eprintln!("   AVX2:     ✅ Supported (High Performance Mode)");
        } else {
            eprintln!("   AVX2:     ❌ Not Detected (Scalar Fallback Mode)");
        }
    }
    #[cfg(not(any(target_arch = "x86", target_arch = "x86_64")))]
    {
        eprintln!("   Arch:     Non-x86 (Standard Mode)");
    }

    // 3. Workspace Integrity
    eprintln!("\n📂 Workspace");
    eprintln!("   Root:     {:?}", root);

    let required = [
        ("system/keyboards", true),
        ("system/corpora", true),
        ("system/weights", true),
        ("system/weights/default_costmatrix.mpk.zst", false),
        ("system/config/keycodes.mpk.zst", false),
    ];

    let mut all_good = true;
    for (item, is_dir) in required {
        let p = root.join(item);
        if p.exists() {
            let matches_type = if is_dir { p.is_dir() } else { p.is_file() };
            if matches_type {
                eprintln!("   ✅ Found: {}", item);
            } else {
                eprintln!(
                    "   ❌ Wrong type (target is {}): {}",
                    if is_dir { "dir" } else { "file" },
                    item
                );
                all_good = false;
            }
        } else {
            eprintln!("   ❌ Missing: {}", item);
            all_good = false;
        }
    }

    // 4. Write Permissions
    let test_file = root.join(".write_test");
    if test_file.exists() {
        eprintln!("   ⚠️  Warning: .write_test already exists, skipping write check.");
    } else {
        match std::fs::write(&test_file, "test") {
            Ok(_) => {
                eprintln!("   ✅ Write Access: OK");
                let _ = std::fs::remove_file(test_file);
            }
            Err(e) => {
                eprintln!("   ❌ Write Access: FAILED ({})", e);
                all_good = false;
            }
        }
    }

    eprintln!("\n========================================");
    if all_good {
        eprintln!("✨ System Healthy. Ready to Forge.");
        Ok(())
    } else {
        Err("Issues detected. Run 'keyforge init' to repair workspace.".into())
    }
}

use crate::cli_parsers::resolve_path;
use clap::{Args, Subcommand, ValueEnum};
use keyforge_export::{qmk::QmkExporter, via::ViaExporter, zmk::ZmkExporter, Exporter};
use keyforge_infra::fs::io::read_to_string_limited;
use keyforge_protocol::constants::MAX_INPUT_FILE_SIZE;
use keyforge_protocol::geometry::kle::to_kle_json;
use keyforge_protocol::geometry::KeyboardDefinition;
use std::error::Error;
use std::fs;
use std::path::{Path, PathBuf};

#[derive(Args, Debug, Clone)]
pub struct ExportArgs {
    #[command(subcommand)]
    pub command: ExportCommands,
}

#[derive(Subcommand, Debug, Clone)]
pub enum ExportCommands {
    Firmware {
        #[arg(short, long)]
        keyboard: String,
        #[arg(short, long)]
        layout: String,
        #[arg(short, long, value_enum)]
        format: FirmwareFormat,
        #[arg(short, long)]
        output: Option<PathBuf>,
    },
}

#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord, ValueEnum, Debug)]
pub enum FirmwareFormat {
    Qmk,
    Zmk,
    Via,
    Kle,
}

pub fn run(args: ExportArgs, root: &Path) -> Result<(), Box<dyn Error>> {
    match args.command {
        ExportCommands::Firmware {
            keyboard,
            layout,
            format,
            output,
        } => {
            eprintln!("💾 Exporting '{}' to {:?}...", layout, format);

            let path = resolve_path(&keyboard, Some("keyboards"), root)?;

            let content = read_to_string_limited(&path, MAX_INPUT_FILE_SIZE)
                .map_err(|e| format!("Failed to read keyboard file {:?}: {}", path, e))?;

            let def: KeyboardDefinition = serde_json::from_str(&content)
                .map_err(|e| format!("Failed to parse keyboard JSON: {}", e))?;

            let layout_str = match def.layouts.get(&layout) {
                Some(s) => s,
                None => {
                    return Err(
                        format!("Layout '{}' not found in keyboard definition.", layout).into(),
                    )
                }
            };

            let keys: Vec<String> = layout_str
                .split_whitespace()
                .map(|s| s.to_string())
                .collect();

            let code = if let FirmwareFormat::Kle = format {
                // Special handling for KLE: Merge layout legends into geometry
                let mut geom = def.geometry.clone();
                for (i, key) in geom.keys.iter_mut().enumerate() {
                    if let Some(legend) = keys.get(i) {
                        key.id = legend.clone();
                    }
                }
                to_kle_json(&geom)?
            } else {
                let exporter: Box<dyn Exporter> = match format {
                    FirmwareFormat::Qmk => Box::new(QmkExporter),
                    FirmwareFormat::Zmk => Box::new(ZmkExporter),
                    FirmwareFormat::Via => Box::new(ViaExporter),
                    FirmwareFormat::Kle => unreachable!(),
                };
                exporter.generate(&layout, &keys)?
            };

            if let Some(out_path) = output {
                if out_path.exists() {
                    eprintln!(
                        "⚠️  Warning: Output file {:?} already exists. Overwriting...",
                        out_path
                    );
                }
                fs::write(&out_path, code)
                    .map_err(|e| format!("Failed to write export to {:?}: {}", out_path, e))?;
                eprintln!("✅ Exported to {:?}", out_path);
            } else {
                println!("{}", code);
            }
            Ok(())
        }
    }
}

