        }
    };

    let manager = keyforge_infra::AssetManager::new(client, root.clone());

    let assets = [
        ("keyboard", "ansi_104"),
        ("keyboard", "corne"),
        ("corpus", "default"),
        ("cost", "cost_matrix.json"),
