use clap::Args;
use keyforge_protocol::BiometricSample;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::PathBuf;

#[derive(Args, Debug, Clone)]
pub struct ProfileArgs {
    /// Path to the user statistics file (JSON or JSONL)
    #[arg(short, long, default_value = "data/user_stats.jsonl")]
    pub input: PathBuf,

    /// Path to write the generated cost matrix CSV
    #[arg(short, long, default_value = "data/personal_cost.json")]
    pub output: PathBuf,
}

pub fn run(args: ProfileArgs) -> Result<(), Box<dyn std::error::Error>> {
    eprintln!("🧬 Generating Biometric Profile...");
    eprintln!("   Input:  {:?}", args.input);
    eprintln!("   Output: {:?}", args.output);

    if !args.input.exists() {
        return Err(format!("Input file not found: {:?}", args.input).into());
    }

    let file = File::open(&args.input).map_err(|e| format!("Failed to open input file: {}", e))?;

    let reader = BufReader::new(file);
    let mut samples = Vec::new();
    let mut error_count = 0;

    for l in reader.lines().map_while(Result::ok) {
        if l.trim().is_empty() {
            continue;
        }
        match serde_json::from_str::<BiometricSample>(&l) {
            Ok(s) => samples.push(s),
            Err(_) => {
                if l.trim().starts_with('[') {
                    eprintln!(
                        "⚠️  Legacy JSON array format detected. Loading entire file into memory."
                    );
                    let content = std::fs::read_to_string(&args.input).unwrap_or_default();
                    if let Ok(legacy_store) =
                        serde_json::from_str::<keyforge_protocol::UserStatsStore>(&content)
                    {
                        samples = legacy_store.biometrics;
                        break;
                    }
                }
                error_count += 1;
            }
        }
    }

    if samples.is_empty() {
        eprintln!("⚠️  Warning: No valid biometric samples found.");
    } else {
        eprintln!(
            "   Loaded {} samples. (Skipped {} errors)",
            samples.len(),
            error_count
        );
    }

    let store = keyforge_protocol::UserStatsStore {
        sessions: 1,
        total_keystrokes: samples.len() as u64,
        biometrics: samples,
    };

    let csv_content = keyforge_infra::util::common::generate_cost_matrix_from_stats(&store);

    std::fs::write(&args.output, csv_content)
        .map_err(|e| format!("Failed to write output file: {}", e))?;

    eprintln!("✅ Profile generated successfully.");
    Ok(())
}

use crate::cli_parsers::resolve_path;
use clap::Args;
use keyforge_infra::fs::io::read_to_string_limited;
use keyforge_protocol::constants::MAX_INPUT_FILE_SIZE;
use keyforge_protocol::geometry::KeyboardDefinition;
use keyforge_protocol::job::JobIdentifier;
use keyforge_protocol::CostMatrixSource;
use std::path::Path;

#[derive(Args, Debug, Clone)]
pub struct QueryArgs {
    #[command(flatten)]
    pub config: crate::cli_args::config::ConfigArgs,

    #[arg(long, default_value = "http://localhost:3000")]
    pub hive: String,
    #[command(flatten)]
    pub shared: crate::cmd::shared::SharedArgs,
}

use keyforge_protocol::Validator;

pub async fn run(args: QueryArgs, root: &Path) -> Result<(), Box<dyn std::error::Error>> {
    eprintln!("🔍 Calculating Job Hash for criteria…");

    let kb_path = resolve_path(&args.shared.keyboard, Some("keyboards"), root)?;

    let kb_content = read_to_string_limited(&kb_path, MAX_INPUT_FILE_SIZE)
        .map_err(|e| format!("Failed to read keyboard file: {}", e))?;

    let kb_def = KeyboardDefinition::parse(&kb_content, None)
        .map_err(|e| format!("Failed to parse keyboard definition: {}", e))?;

    let corpora_fingerprint = "default".to_string();
    let constraints = args.shared.pinned_keys;

    use std::convert::TryFrom;
    let config = keyforge_protocol::config::Config::try_from(args.config)?;
    config.search.validate()?;
    config.weights.validate()?;

    let cost_source = CostMatrixSource::Predefined(args.shared.cost.clone());

    let job_id = JobIdentifier::try_from_parts(
        &kb_def.geometry,
        &config.weights,
        &config.search,
        &constraints,
        &corpora_fingerprint,
        &cost_source,
    )
    .map_err(|e| format!("Failed to compute job id: {}", e))?
    .hash;

    eprintln!("   Job ID: {}", job_id);
    eprintln!("   Hive:   {}", args.hive);

    let url = format!("{}/jobs/{}/population", args.hive, job_id);

    match reqwest::get(&url).await {
        Ok(resp) => {
            if resp.status().is_success() {
                let pop = resp
                    .json::<keyforge_protocol::PopulationResponse>()
                    .await
                    .map_err(|e| format!("Failed to parse Hive response: {}", e))?;

                eprintln!("\n✅ Job Found!");
                if let Some(best) = pop.layouts.first() {
                    println!("{}", best);
                } else {
                    eprintln!("   Job exists but has no results yet.");
                }
            } else {
                return Err(format!("Hive Error: {}", resp.status()).into());
            }
        }
        Err(e) => return Err(format!("Connection Failed: {}", e).into()),
    }
    Ok(())
}

use clap::Args;
use indicatif::{ProgressBar, ProgressStyle};
use keyforge_compute::Runtime;
use keyforge_core::ProgressCallback;

#[derive(Args, Debug, Clone)]
pub struct SearchArgs {
    #[command(flatten)]
    pub config: crate::cli_args::config::ConfigArgs,

    #[arg(short = 'T', long)]
    pub time: Option<u64>,

    #[arg(short = 'a', long)]
    pub attempts: Option<usize>,

    #[arg(short = 'S', long)]
    pub seed: Option<u64>,

    #[arg(long, default_value_t = 0)]
    pub threads: usize,

    #[command(flatten)]
    pub shared: crate::cmd::shared::SharedArgs,
}

struct CliProgress {
    bar: ProgressBar,
}

impl ProgressCallback for CliProgress {
    fn on_progress(&self, step: usize, score: f32, _layout: &[u16], ips: f32) -> bool {
        self.bar.set_position(step as u64);
        self.bar
            .set_message(format!("Score: {:.0} | {:.2} M/s", score, ips));

        // Check global interrupt
        if crate::is_interrupted() {
            return false;
        }
        true
    }
}

pub fn run(args: SearchArgs, mut runtime: Runtime) -> Result<(), Box<dyn std::error::Error>> {
    // Initialize global thread pool if requested
    if args.threads > 0 {
        let _ = rayon::ThreadPoolBuilder::new()
            .num_threads(args.threads)
            .build_global();
    }

    eprintln!("🔎 Starting optimisation…");

    // Apply overrides to the runtime's local config copy
    if let Some(s) = args.seed {
        // FIX: Irrefutable pattern - used direct destructuring
        let keyforge_model::SearchConfig::Annealing { ref mut seed, .. } = runtime.search_config;
        *seed = s;
    }

    // FIX: Irrefutable pattern - used direct destructuring
    let keyforge_model::SearchConfig::Annealing { steps, .. } = runtime.search_config;

    let pb = ProgressBar::new(steps as u64);
    pb.set_style(ProgressStyle::default_bar()
        .template("{spinner:.green} [{elapsed_precise}] [{bar:40.cyan/blue}] {pos}/{len} ({eta}) {msg}")
        .unwrap()
        .progress_chars("#>-"));

    let callback = CliProgress { bar: pb.clone() };

    let result = runtime.optimize(callback);

    pb.finish_with_message("Done");

    eprintln!("\n=== �� FINAL RESULT ===");
    eprintln!("Score: {:.3}", result.score);

    let layout_str = result
        .layout
        .keys
        .iter()
        .map(|&c| runtime.registry.get_label(c))
        .collect::<Vec<String>>()
        .join(" ");

    println!("{}", layout_str);
    Ok(())
}

