pub async fn backup_db(State(state): State<Arc<AppState>>) -> AppResult<Json<FullBackup>> {
    // 1. Keyboards
    let keyboards = sqlx::query!("SELECT * FROM keyboards")
        .fetch_all(&state.jobs.pool)
        .await
        .map_err(AppError::Database)?
        .iter()
        .map(|r| {
