use axum::{extract::State, Json};
use keyforge_protocol::{NodeRequest, NodeResponse, TuningProfile, PROTOCOL_VERSION};
use std::sync::Arc;
use tracing::info;

use crate::error::{AppError, AppResult};
use crate::state::AppState;

#[utoipa::path(
    post,
    path = "/nodes/register",
    request_body = NodeRequest,
    responses(
        (status = 200, description = "Node registered", body = NodeResponse)
    ),
    tag = "nodes"
)]
pub async fn register_node(
    State(state): State<Arc<AppState>>,
    Json(payload): Json<NodeRequest>,
) -> AppResult<Json<NodeResponse>> {
    // Flexible Version Check
    if let Err(e) =
        keyforge_protocol::check_version_compatibility(payload.version, PROTOCOL_VERSION)
    {
        // Allow public key check even on version mismatch to report specific error?
        // No, fail fast on protocol mismatch.
        return Err(AppError::Validation(e));
    }

    if let Some(pk) = &payload.public_key {
        if pk.len() < 64
            || (!pk.starts_with("-----BEGIN PUBLIC KEY")
                && !pk.chars().all(|c| c.is_ascii_hexdigit()))
        {
            return Err(AppError::Validation(
                "Invalid Public Key Format (PEM or Hex required)".into(),
            ));
        }
    }

    state
        .nodes
        .register_heartbeat(
            &payload.node_id,
            &payload.cpu_model,
            payload.cores,
            payload.l2_cache_kb,
            payload.ops_per_sec,
            payload.public_key.as_deref(),
        )
        .await
        .map_err(|e| {
            if e.to_string().contains("Node Identity Mismatch") {
                AppError::Validation("Node Identity Mismatch".into())
            } else {
                AppError::Database(e)
            }
        })?;

    info!(
        "🖥️ Node Registered: {} | {} | {:.1} M/s",
        payload.node_id,
        payload.cpu_model,
        payload.ops_per_sec / 1_000_000.0
    );

    let strategy = if let Some(l2) = payload.l2_cache_kb {
        if l2 >= 1024 {
            "table"
        } else {
            "fly"
        }
    } else {
        "fly"
    };

    let batch_size = if payload.ops_per_sec > 10_000_000.0 {
        50_000
    } else {
        10_000
    };
    let thread_count = (payload.cores - 1).max(1) as usize;

    Ok(Json(NodeResponse {
        status: "registered".to_string(),
        tuning: TuningProfile {
            strategy: strategy.to_string(),
            batch_size,
            thread_count,
        },
    }))
}

use crate::error::{AppError, AppResult};
use crate::infra::queue::DbEvent;
use crate::state::AppState;
use axum::{extract::State, Json};
use keyforge_protocol::{ResultSubmission, PROTOCOL_VERSION};
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};
use tokio::sync::oneshot;

#[utoipa::path(
    post,
    path = "/results",
    request_body = ResultSubmission,
    responses(
        (status = 200, description = "Result accepted"),
        (status = 400, description = "Invalid submission")
    ),
    tag = "results"
)]
pub async fn submit_result(
    State(state): State<Arc<AppState>>,
    Json(payload): Json<ResultSubmission>,
) -> AppResult<String> {
    if payload.version != PROTOCOL_VERSION {
        return Err(AppError::Validation("Protocol Mismatch".into()));
    }

    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    if now.abs_diff(payload.timestamp) > 900 {
        return Err(AppError::Validation("Submission expired".into()));
    }

    let nonce_key = format!("{}:{}", payload.node_id, payload.nonce);
    if state.nonce_cache.contains_key(&nonce_key) {
        return Err(AppError::Validation("Replay detected".into()));
    }
    state.nonce_cache.insert(nonce_key, true);

    // Delegate to Service
    state.verification.verify_submission(&payload).await?;

    let (tx, rx) = oneshot::channel();
    state
        .queue
        .push(DbEvent::Result {
            job_id: payload.job_id.clone(),
            layout: payload.layout.clone(),
            score: payload.score,
            node_id: payload.node_id.clone(),
            ack: Some(tx),
        })
        .await;

    if rx.await.is_err() {
        return Err(AppError::Any(anyhow::anyhow!("Persistence failed")));
    }

    Ok("Accepted".to_string())
}

