}

#[utoipa::path(
    post,
    path = "/user/nuke",
    request_body = NukeRequest,
    responses(
        (status = 200, description = "User data erased"),
        (status = 400, description = "Invalid confirmation")
    ),
    tag = "user"
)]
pub async fn nuke_user_data(
    State(state): State<Arc<AppState>>,
    Json(payload): Json<NukeRequest>,
) -> AppResult<String> {
    if payload.confirmation != "DELETE_EVERYTHING" {
        return Err(AppError::Validation("Invalid confirmation string".into()));
    }

    let user_id: Option<uuid::Uuid> =
        sqlx::query_scalar("SELECT id FROM users WHERE username = $1")
            .bind(&payload.username)
            .fetch_optional(&state.users.pool)
            .await
            .map_err(AppError::Database)?;

    if let Some(uid) = user_id {
        // Audit Log
        state
            .audit
            .log(AuditLog {
                action: "USER_NUKE",
                actor_id: Some(uid),
                target: Some("ALL_DATA"),
                details: Some(serde_json::json!({"username": payload.username})),
                ip: None,
                status_code: None,
                request_id: None,
                user_agent: None,
            })
            .await
            .ok();

        // FIX: Parameterized Query
        sqlx::query("DELETE FROM users WHERE id = $1")
            .bind(uid)
            .execute(&state.users.pool)
            .await
            .map_err(AppError::Database)?;

        warn!(
            "☢️ NUKE: User {} ({}) deleted all data.",
            payload.username, uid
        );
        Ok("User data erased successfully.".to_string())
    } else {
        Err(AppError::NotFound)
    }
}

use crate::error::{AppError, AppResult};

/// Shared helper for validating characters
fn is_valid_char(c: char, allow_dot: bool) -> bool {
    c.is_alphanumeric() || c == '-' || c == '_' || (allow_dot && c == '.')
}

/// Checks if a name is a Windows reserved filename (CON, PRN, etc.)
fn is_reserved_name(name: &str) -> bool {
    let stem = name.split('.').next().unwrap_or("").to_uppercase();
    let reserved = [
        "CON", "PRN", "AUX", "NUL", "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8",
        "COM9", "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
    ];
    reserved.contains(&stem.as_str())
}

/// Validates that a string is a safe filename.
pub fn validate_filename(name: &str) -> AppResult<()> {
    if name.is_empty() || name.len() > 255 {
        return Err(AppError::Validation("Invalid filename length".into()));
    }
    if name == "." || name == ".." || is_reserved_name(name) {
        return Err(AppError::Validation("Reserved or invalid filename".into()));
    }

    for c in name.chars() {
        if !is_valid_char(c, true) {
            return Err(AppError::Validation(format!(
                "Invalid char in filename: {}",
                c
            )));
        }
    }
    Ok(())
}

/// Validates that a string is a safe identifier (e.g. Corpus ID).
pub fn validate_id(id: &str) -> AppResult<()> {
    if id.is_empty() || id.len() > 64 {
        return Err(AppError::Validation("Invalid ID length".into()));
    }
    if is_reserved_name(id) {
        return Err(AppError::Validation("ID cannot be a reserved name".into()));
    }

    for c in id.chars() {
        if !is_valid_char(c, false) {
            return Err(AppError::Validation(format!("Invalid char in ID: {}", c)));
        }
    }
    Ok(())
}

pub fn validate_path_component(path: &str) -> AppResult<()> {
    validate_id(path)
}

use crate::state::AppState;
use axum::{
    extract::{ws::Message, ws::WebSocket, State, WebSocketUpgrade},
    response::IntoResponse,
};
use futures::{sink::SinkExt, stream::StreamExt};
use keyforge_protocol::constants::{WS_MSG_CANCEL, WS_MSG_JOB};
use serde::Serialize;
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::broadcast::error::RecvError;
use tokio::time::interval;
use tracing::{debug, info, warn};

#[derive(Serialize)]
#[serde(tag = "type", content = "payload")]
enum ServerMessage {
    Job { id: String },
    Cancel { id: String },
}

pub async fn handler(
    ws: WebSocketUpgrade,
    State(state): State<Arc<AppState>>,
) -> impl IntoResponse {
    ws.on_upgrade(move |socket| handle_socket(socket, state))
}

async fn handle_socket(socket: WebSocket, state: Arc<AppState>) {
    let (mut sender, mut receiver) = socket.split();
    let rx = state.tx.subscribe();

    info!("🔌 Worker connected via WebSocket");

    // Task 1: Send Broadcasts & Heartbeats
    let send_task = tokio::spawn(async move {
        let mut rx = rx;
        // HIVE-050: Heartbeat Interval (30s)
        let mut heartbeat = interval(Duration::from_secs(30));

        loop {
            tokio::select! {
                // Broadcast Messages
                msg_res = rx.recv() => {
                    match msg_res {
                        Ok(msg_str) => {
                            let msg = if let Some(id) = msg_str.strip_prefix(WS_MSG_JOB) {
                                ServerMessage::Job { id: id.to_string() }
                            } else if let Some(id) = msg_str.strip_prefix(WS_MSG_CANCEL) {
                                ServerMessage::Cancel { id: id.to_string() }
                            } else {
                                continue;
                            };

                            if let Ok(json) = serde_json::to_string(&msg) {
                                if sender.send(Message::Text(json)).await.is_err() {
                                    break;
                                }
                            }
                        }
                        Err(RecvError::Lagged(skipped)) => {
                            warn!("⚠️ WebSocket client lagged, skipped {} messages", skipped);
                        }
                        Err(RecvError::Closed) => break,
                    }
                }
                // Heartbeat Ping
                _ = heartbeat.tick() => {
                    if sender.send(Message::Ping(vec![])).await.is_err() {
                        break;
                    }
                    debug!("💓 Sent Ping");
                }
            }
        }
    });

    // Task 2: Receive Messages (Pong/Close) with Liveness Timeout
    // MINOR #58: Prevent memory leaks from hung connections
    loop {
        match tokio::time::timeout(Duration::from_secs(60), receiver.next()).await {
            Ok(Some(Ok(Message::Pong(_)))) => {
                debug!("💓 Received Pong");
            }
            Ok(Some(Ok(Message::Close(_)))) => break,
            Ok(None) => break, // Stream closed
            Err(_) => {
                warn!("🕒 WebSocket liveness timeout (no Pong for 60s)");
                break;
            }
            _ => {} // Ignore other messages
        }
    }

    send_task.abort();
    info!("�� Worker disconnected");
}

