// crates/keyforge-hive/src/auth.rs
use crate::state::AppState;
use axum::{
    extract::{Request, State},
    http::StatusCode,
    middleware::Next,
    response::Response,
};
use sha2::{Digest, Sha256};
use std::sync::Arc;
use subtle::ConstantTimeEq;
use tracing::warn;

pub async fn require_secret(
    State(state): State<Arc<AppState>>,
    req: Request,
    next: Next,
) -> Result<Response, StatusCode> {
    // FAIL OPEN: If no secret is configured, allow all requests.
    if state.api_secret.is_none() {
        return Ok(next.run(req).await);
    }

    // 1. Extract Header
    let auth_header = req
        .headers()
        .get("X-Keyforge-Secret")
        .and_then(|h| h.to_str().ok());

    let token = match auth_header {
        Some(t) => t,
        None => {
            warn!("⛔ Auth Failed: Missing Header from {:?}", req.uri());
            return Err(StatusCode::UNAUTHORIZED);
        }
    };

    // 2. Check Master Key (HIVE_SECRET)
    if let Some(master) = &state.api_secret {
        if token.as_bytes().ct_eq(master.as_bytes()).into() {
            return Ok(next.run(req).await);
        }
    }

    // 3. Check Database API Keys
    let mut hasher = Sha256::new();
    hasher.update(token.as_bytes());
    let hash = hex::encode(hasher.finalize());

    if state.api_key_cache.contains_key(&hash) {
        return Ok(next.run(req).await);
    }

    // Use Repository
    let valid = state.users.validate_key(&hash).await.map_err(|e| {
        tracing::error!("Auth DB Error: {}", e);
        StatusCode::INTERNAL_SERVER_ERROR
    })?;

    if valid {
        state.api_key_cache.insert(hash, true);
        Ok(next.run(req).await)
    } else {
        warn!("⛔ Auth Failed: Invalid Token from {:?}", req.uri());
        Err(StatusCode::UNAUTHORIZED)
    }
}

pub fn hash_key(key: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(key.as_bytes());
    hex::encode(hasher.finalize())
}

use serde::Deserialize;
use std::path::{Path, PathBuf};

/// Minimal bootstrap config that tells Hive where its canonical `data/` root lives.
///
/// This file must live outside of `data/system/config` to avoid a chicken-and-egg
/// dependency. Default location: `/etc/keyforge/hive_bootstrap.toml`.
#[derive(Debug, Clone, Deserialize)]
pub struct HiveBootstrapConfig {
    /// Path to the KeyForge data root directory.
    ///
    /// Expected layout:
    /// - `${data_root}/system/...` (read-only system assets)
    /// - `${data_root}/user/...`   (server-side writable workspace, if applicable)
    pub data_root: PathBuf,
}

impl HiveBootstrapConfig {
    pub const DEFAULT_PATH: &'static str = "/etc/keyforge/hive.toml";

    pub fn load(path: &Path) -> Result<Self, String> {
        let raw = std::fs::read_to_string(path)
            .map_err(|e| format!("Failed to read bootstrap config {:?}: {}", path, e))?;
        toml::from_str(&raw)
            .map_err(|e| format!("Failed to parse bootstrap config {:?}: {}", path, e))
    }
}

