use crate::infra::repositories::{JobRepository, NodeRepository, ResultRepository};
use std::sync::Arc;
use tokio::time::{interval, Duration};
use tracing::{error, info};

pub async fn start_cron_jobs(
    job_repo: Arc<JobRepository>,
    node_repo: Arc<NodeRepository>,
    result_repo: Arc<ResultRepository>,
) {
    // CHANGE: Run every minute to catch dead jobs quickly
    let mut interval = interval(Duration::from_secs(60));
    let mut hour_ticker = 0;

    info!("⏰ Starting background maintenance (Interval: 60s)...");

    loop {
        interval.tick().await;
        hour_ticker += 1;

        // --- 1. THE REAPER (Runs every minute) ---
        // Timeout: 10 minutes, Max Retries: 3
        match job_repo.prune_stale_jobs(10, 3).await {
            Ok(count) if count > 0 => {
                tracing::warn!("💀 Zombie Reaper: Reset {} stuck jobs.", count);
            }
            Err(e) => tracing::error!("Failed to prune stale jobs: {}", e),
            _ => {} // No zombies found, silence is golden
        }

        // --- 2. HOURLY TASKS (Run every 60 ticks) ---
        if hour_ticker >= 60 {
            hour_ticker = 0;
            info!("🧹 Running hourly maintenance...");

            // Cleanup old jobs (cancelled/stale > 30 days)
            if let Err(e) = job_repo.prune_old_jobs(30).await {
                error!("Failed to prune old jobs: {}", e);
            }

            // Cleanup inactive nodes (> 15 mins)
            if let Err(e) = node_repo.prune_inactive_nodes(15).await {
                error!("Failed to prune inactive nodes: {}", e);
            }

            // Prune Results (Keep top 1000 per job, delete others older than 7 days)
            match result_repo.prune_old_results(7, 1000).await {
                Ok(count) => {
                    if count > 0 {
                        info!("🧹 Pruned {} old results.", count);
                    }
                }
                Err(e) => error!("Failed to prune results: {}", e),
            }
        }
    }
}

use axum::{
    http::StatusCode,
    response::{IntoResponse, Response},
    Json,
};
use keyforge_model::error::KeyForgeError;
use keyforge_protocol::error::{ErrorCode, ErrorResponse};
use thiserror::Error;

#[derive(Error, Debug)]
pub enum AppError {
    #[error("Database error: {0}")]
    Database(#[from] sqlx::Error),

    #[error("Serialization error: {0}")]
    Serde(#[from] serde_json::Error),

    #[error("Loader Error: {0}")]
    Loader(#[from] KeyForgeError),

    #[error("Validation error: {0}")]
    Validation(String),

    #[error("Not Found")]
    NotFound,

    #[error("Internal Server Error: {0}")]
    Any(#[from] anyhow::Error),

    #[error("Service Unavailable: {0}")]
    ServiceUnavailable(String),
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, code, msg) = match self {
            AppError::Database(e) => {
                tracing::error!("Database Error: {}", e);
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    ErrorCode::DatabaseError,
                    "A database error occurred".to_string(),
                )
            }
            AppError::Serde(e) => (
                StatusCode::BAD_REQUEST,
                ErrorCode::BadRequest,
                format!("Serialization error: {}", e),
            ),
            AppError::Loader(e) => {
                let status = match &e {
                    KeyForgeError::NotFound(_) => StatusCode::NOT_FOUND,
                    _ => StatusCode::INTERNAL_SERVER_ERROR,
                };
                (status, ErrorCode::InternalError, e.to_string())
            }
            AppError::Validation(s) => (StatusCode::BAD_REQUEST, ErrorCode::JobValidationFailed, s),
            AppError::NotFound => (
                StatusCode::NOT_FOUND,
                ErrorCode::NotFound,
                "Resource not found".to_string(),
            ),
            AppError::Any(e) => {
                tracing::error!("Internal Error: {}", e);
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    ErrorCode::InternalError,
                    "An internal server error occurred".to_string(),
                )
            }
            AppError::ServiceUnavailable(s) => {
                (StatusCode::SERVICE_UNAVAILABLE, ErrorCode::InternalError, s)
            }
        };

        let body = ErrorResponse::new(code, msg);
        (status, Json(body)).into_response()
    }
}

pub type AppResult<T> = Result<T, AppError>;

use sqlx::postgres::{PgConnectOptions, PgPool, PgPoolOptions};
use sqlx::ConnectOptions;
use std::env;
use std::str::FromStr;
use std::time::Duration;
use tokio::time::sleep;
use tracing::{info, warn};

#[derive(Debug, thiserror::Error)]
pub enum DbInitError {
    #[error("Invalid database URL: {0}")]
    InvalidDatabaseUrl(String),

    #[error("Could not connect to Postgres after {attempts} attempts: {db_url}")]
    ConnectTimeout { attempts: u32, db_url: String },

    #[error("Database migration failed after {attempts} attempts: {error}")]
    MigrationFailed { attempts: u32, error: String },
}

pub async fn try_init_db(db_url: &str) -> Result<PgPool, DbInitError> {
    info!("🔌 Connecting to PostgreSQL...");

    let pool = connect_with_retry(db_url).await?;

    // RETRY LOGIC for Schema Migration
    let mut attempts = 0;
    loop {
        attempts += 1;

        match sqlx::migrate!().run(&pool).await {
            Ok(_) => break,
            Err(e) => {
                if attempts >= 10 {
                    return Err(DbInitError::MigrationFailed {
                        attempts,
                        error: e.to_string(),
                    });
                }

                let is_retryable = match &e {
                    sqlx::migrate::MigrateError::Execute(inner_err) => {
                        if let Some(db_err) = inner_err.as_database_error() {
                            if let Some(code) = db_err.code() {
                                // 40P01: deadlock_detected, 23505: unique_violation
                                code == "40P01" || code == "23505"
                            } else {
                                false
                            }
                        } else {
                            false
                        }
                    }
                    _ => false,
                };

                if is_retryable {
                    let wait = fastrand::u64(100..500);
                    warn!(
                        "⚠️  Schema lock contention (attempt {}). Retrying in {}ms...",
                        attempts, wait
                    );
                    sleep(Duration::from_millis(wait)).await;
                } else {
                    return Err(DbInitError::MigrationFailed {
                        attempts,
                        error: e.to_string(),
                    });
                }
            }
        }
    }

    info!("✅ Database connected and migrations applied.");
    Ok(pool)
}

/// Convenience wrapper used by tests and simple entrypoints.
///
/// Prefer [`try_init_db`] in production code.
pub async fn init_db(db_url: &str) -> PgPool {
    match try_init_db(db_url).await {
        Ok(p) => p,
        Err(e) => panic!("DB init failed: {}", e),
    }
}

async fn connect_with_retry(db_url: &str) -> Result<PgPool, DbInitError> {
    let max_retries = 30;
    let delay = Duration::from_secs(1);

    let max_connections = std::env::var("DATABASE_MAX_CONNECTIONS")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(100);

    let timeout_secs = env::var("DATABASE_TIMEOUT_SECONDS")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(10);

    info!(
        "   Pool Config: Max Conns={}, Timeout={}s",
        max_connections, timeout_secs
    );

    for i in 1..=max_retries {
        let options_res = PgConnectOptions::from_str(db_url);

        match options_res {
            Ok(mut options) => {
                options = options.log_statements(tracing::log::LevelFilter::Debug);

                match PgPoolOptions::new()
                    .max_connections(max_connections)
                    .acquire_timeout(Duration::from_secs(timeout_secs))
                    .idle_timeout(Duration::from_secs(600))
                    .max_lifetime(Duration::from_secs(1800))
                    .after_connect(|conn, _meta| Box::pin(async move {
                        use sqlx::Executor;
                        // P1 FIX: Use REPEATABLE READ to ensure FOR UPDATE SKIP LOCKED works correctly
                        conn.execute("SET SESSION CHARACTERISTICS AS TRANSACTION ISOLATION LEVEL REPEATABLE READ").await?;
                        conn.execute("SET statement_timeout = '30s'").await?;
                        Ok(())
                    }))
                    .connect_with(options)
                    .await
                {
                    Ok(p) => return Ok(p),
                    Err(e) => {
                        warn!(
                            "⚠️  DB Connection attempt {}/{} failed: {}. URL: {}",
                            i, max_retries, e, db_url
                        );
                        sleep(delay).await;
                    }
                }
            }
            Err(e) => {
                return Err(DbInitError::InvalidDatabaseUrl(e.to_string()));
            }
        }
    }
    Err(DbInitError::ConnectTimeout {
        attempts: max_retries,
        db_url: db_url.to_string(),
    })
}

