pub struct NodeRepository {
    pool: Pool<Postgres>,
}

impl NodeRepository {
    pub fn new(pool: Pool<Postgres>) -> Self {
        Self { pool }
    }

    pub async fn register_heartbeat(
        &self,
        node_id: &str,
        cpu_model: &str,
        cores: i32,
        l2_cache_kb: Option<i32>,
        ops_per_sec: f32,
        public_key: Option<&str>,
    ) -> Result<(), sqlx::Error> {
        // App-Side TOFU (Trust On First Use)
        // If the node exists and has a key, ensure the new key matches.
        if let Some(new_key) = public_key {
            if let Ok(Some(existing_key)) = self.get_public_key(node_id).await {
                // Normalize keys (strip whitespace) for comparison
                let existing_clean = existing_key.trim();
                let new_clean = new_key.trim();

                if !existing_clean.is_empty() && existing_clean != new_clean {
                    tracing::warn!("🚨 Security Alert: Node Identity Mismatch for {}", node_id);
                    return Err(sqlx::Error::Protocol(
                        "Node Identity Mismatch: Public Key changed".into(),
                    ));
                }
            }
        }

        sqlx::query("SELECT register_node_heartbeat($1, $2, $3, $4, $5, $6, $7)")
            .bind(node_id)
            .bind(cpu_model)
            .bind(std::env::consts::ARCH)
            .bind(cores)
            .bind(l2_cache_kb)
            .bind(ops_per_sec)
            .bind(public_key)
            .execute(&self.pool)
            .await?;
        Ok(())
    }

    pub async fn get_public_key(&self, node_id: &str) -> Result<Option<String>, sqlx::Error> {
        // Fix: Explicitly decode as Option<String> to handle NULLs in the DB
        let row: Option<Option<String>> =
            sqlx::query_scalar("SELECT public_key FROM nodes WHERE id = $1")
                .bind(node_id)
                .fetch_optional(&self.pool)
                .await?;
        Ok(row.flatten())
    }

    pub async fn count_recent(&self) -> Result<i64, sqlx::Error> {
        let count: i64 = sqlx::query_scalar(
            "SELECT count(*) FROM nodes WHERE last_seen > NOW() - INTERVAL '1 minute'",
        )
        .fetch_one(&self.pool)
        .await?;
        Ok(count)
    }

    pub async fn sum_ops(&self) -> Result<f32, sqlx::Error> {
        let ops: f32 = sqlx::query_scalar(
            "SELECT COALESCE(SUM(performance_rating), 0) FROM nodes WHERE last_seen > NOW() - INTERVAL '1 minute'",
        )
        .fetch_one(&self.pool)
        .await?;
        Ok(ops)
    }

    pub async fn prune_inactive_nodes(&self, minutes: i32) -> Result<u64, sqlx::Error> {
        let result =
            sqlx::query("DELETE FROM nodes WHERE last_seen < NOW() - make_interval(mins => $1)")
                .bind(minutes)
                .execute(&self.pool)
                .await?;
        Ok(result.rows_affected())
    }
}

use sqlx::{Pool, Postgres, QueryBuilder, Row};

#[derive(Clone)]
pub struct ResultRepository {
    pool: Pool<Postgres>,
}

impl ResultRepository {
    pub fn new(pool: Pool<Postgres>) -> Self {
        Self { pool }
    }

    pub async fn get_population(&self, job_id: &str) -> Result<Vec<String>, sqlx::Error> {
        let rows = sqlx::query(
            r#"
            SELECT layout 
            FROM results 
            WHERE job_id = $1 
            ORDER BY score ASC 
            LIMIT 50
            "#,
        )
        .bind(job_id)
        .fetch_all(&self.pool)
        .await?;

        Ok(rows
            .iter()
            .map(|r| r.try_get("layout").unwrap_or_default())
            .collect())
    }

    pub async fn get_best_score(&self, job_id: &str) -> Result<Option<f32>, sqlx::Error> {
        let row = sqlx::query("SELECT min(score) as min_score FROM results WHERE job_id = $1")
            .bind(job_id)
            .fetch_optional(&self.pool)
            .await?;

        if let Some(r) = row {
            let val: Option<f64> = r.try_get("min_score")?;
            Ok(val.map(|v| v as f32))
        } else {
            Ok(None)
        }
    }

    pub async fn insert_batch(&self, items: &[(&str, &str, f32, &str)]) -> Result<(), sqlx::Error> {
        if items.is_empty() {
            return Ok(());
        }

        let mut query_builder: QueryBuilder<Postgres> =
            QueryBuilder::new("INSERT INTO results (job_id, layout, score, node_id) ");

        query_builder.push_values(items, |mut b, (job, layout, score, node)| {
            b.push_bind(job)
                .push_bind(layout)
                .push_bind(*score as f64)
                .push_bind(node);
        });

        let query = query_builder.build();
        let mut tx = self.pool.begin().await?;
        query.execute(&mut *tx).await?;
        tx.commit().await?;
        Ok(())
    }

    pub async fn count_total(&self) -> Result<i64, sqlx::Error> {
        let count: i64 = sqlx::query_scalar("SELECT count(*) FROM results")
            .fetch_one(&self.pool)
            .await?;
        Ok(count)
    }

    pub async fn get_stats(
        &self,
        job_id: &str,
    ) -> Result<(usize, usize, Option<f32>, Option<String>), sqlx::Error> {
        let stats = sqlx::query!(
            r#"SELECT count(DISTINCT node_id) as nodes, count(*) as samples, min(score) as best_score FROM results WHERE job_id = $1"#,
            job_id
        ).fetch_one(&self.pool).await?;

        let best_layout = if let Some(score) = stats.best_score {
            sqlx::query_scalar(
                "SELECT layout FROM results WHERE job_id = $1 AND score = $2 LIMIT 1",
            )
            .bind(job_id)
            .bind(score)
            .fetch_optional(&self.pool)
            .await?
        } else {
            None
        };

        Ok((
            stats.nodes.unwrap_or(0) as usize,
            stats.samples.unwrap_or(0) as usize,
            stats.best_score.map(|s| s as f32),
            best_layout,
        ))
    }

    pub async fn prune_old_results(&self, days: i32, keep_top: i32) -> Result<u64, sqlx::Error> {
        let query = r#"
            DELETE FROM results
            WHERE id IN (
                SELECT id FROM (
                    SELECT id,
                           ROW_NUMBER() OVER (PARTITION BY job_id ORDER BY score ASC) as rank
                    FROM results
                    WHERE created_at < NOW() - make_interval(days => $1)
                ) ranked
                WHERE rank > $2
            )
        "#;

        let result = sqlx::query(query)
            .bind(days)
            .bind(keep_top)
            .execute(&self.pool)
            .await?;

        Ok(result.rows_affected())
    }
}

