use crate::api::submission::SubmissionEntry;
use sqlx::{Pool, Postgres, Row};

#[derive(Clone)]
pub struct SubmissionRepository {
    pool: Pool<Postgres>,
}

impl SubmissionRepository {
    pub fn new(pool: Pool<Postgres>) -> Self {
        Self { pool }
    }

    pub async fn save(&self, name: &str, layout: &str, author: &str) -> Result<i64, sqlx::Error> {
        let rec = sqlx::query(
            "INSERT INTO submissions (name, layout_str, author) VALUES ($1, $2, $3) RETURNING id",
        )
        .bind(name)
        .bind(layout)
        .bind(author)
        .fetch_one(&self.pool)
        .await?;

        let id: i32 = rec.try_get("id")?;
        Ok(id as i64)
    }

    pub async fn get_recent(&self, limit: i64) -> Result<Vec<SubmissionEntry>, sqlx::Error> {
        let rows = sqlx::query(
            r#"
            SELECT id, name, layout_str, author, submitted_at 
            FROM submissions 
            ORDER BY submitted_at DESC 
            LIMIT $1
            "#,
        )
        .bind(limit)
        .fetch_all(&self.pool)
        .await?;

        Ok(rows
            .into_iter()
            .map(|r| SubmissionEntry {
                id: r.try_get::<i32, _>("id").unwrap_or(0) as i64,
                name: r.try_get("name").unwrap_or_default(),
                layout: r.try_get("layout_str").unwrap_or_default(),
                author: r.try_get("author").unwrap_or_default(),
                date: r
                    .try_get::<chrono::DateTime<chrono::Utc>, _>("submitted_at")
                    .map(|d| d.to_rfc3339())
                    .unwrap_or_default(),
            })
            .collect())
    }
}

use sqlx::{Pool, Postgres, Row};
use uuid::Uuid;

#[derive(Clone)]
pub struct UserRepository {
    pub(crate) pool: Pool<Postgres>,
}

impl UserRepository {
    pub fn new(pool: Pool<Postgres>) -> Self {
        Self { pool }
    }

    /// Creates a new user. Returns None if username already exists.
    pub async fn create_user(&self, username: &str) -> Result<Option<Uuid>, sqlx::Error> {
        // SECURITY FIX: ON CONFLICT DO NOTHING prevents account takeover
        let row = sqlx::query(
            "INSERT INTO users (username) VALUES ($1) ON CONFLICT (username) DO NOTHING RETURNING id"
        )
        .bind(username)
        .fetch_optional(&self.pool)
        .await?;

        if let Some(r) = row {
            Ok(Some(r.try_get("id")?))
        } else {
            Ok(None) // Username taken
        }
    }

    pub async fn create_api_key(
        &self,
        user_id: Uuid,
        key_hash: &str,
        label: &str,
    ) -> Result<(), sqlx::Error> {
        sqlx::query("INSERT INTO api_keys (user_id, key_hash, label) VALUES ($1, $2, $3)")
            .bind(user_id)
            .bind(key_hash)
            .bind(label)
            .execute(&self.pool)
            .await?;
        Ok(())
    }

    pub async fn validate_key(&self, key_hash: &str) -> Result<bool, sqlx::Error> {
        let exists = sqlx::query("SELECT 1 FROM api_keys WHERE key_hash = $1")
            .bind(key_hash)
            .fetch_optional(&self.pool)
            .await?;

        if exists.is_some() {
            let pool = self.pool.clone();
            let hash = key_hash.to_string();
            // Async touch to update last_used
            tokio::spawn(async move {
                let _ = sqlx::query(
                    "UPDATE api_keys SET last_used_at = CURRENT_TIMESTAMP WHERE key_hash = $1",
                )
                .bind(hash)
                .execute(&pool)
                .await;
            });
            Ok(true)
        } else {
            Ok(false)
        }
    }

    /// Retrieves the User ID associated with a specific API key hash.
    pub async fn get_user_by_key_hash(&self, key_hash: &str) -> Result<Option<Uuid>, sqlx::Error> {
        let row = sqlx::query("SELECT user_id FROM api_keys WHERE key_hash = $1")
            .bind(key_hash)
            .fetch_optional(&self.pool)
            .await?;

        if let Some(r) = row {
            Ok(Some(r.try_get("user_id")?))
        } else {
            Ok(None)
        }
    }

    pub async fn check_job_quota(&self, user_id: Uuid) -> Result<bool, sqlx::Error> {
        let row = sqlx::query("SELECT max_active_jobs, max_daily_jobs FROM users WHERE id = $1")
            .bind(user_id)
            .fetch_optional(&self.pool)
            .await?;

        if let Some(r) = row {
            let max_active: Option<i32> = r.try_get("max_active_jobs").unwrap_or(Some(5));
            let max_daily: Option<i32> = r.try_get("max_daily_jobs").unwrap_or(Some(50));

            let active_count: i64 = sqlx::query_scalar(
                "SELECT count(*) FROM jobs WHERE owner_id = $1 AND status = 'active'",
            )
            .bind(user_id)
            .fetch_one(&self.pool)
            .await?;

            if active_count >= max_active.unwrap_or(5) as i64 {
                return Ok(false);
            }

            let daily_count: i64 = sqlx::query_scalar(
                "SELECT count(*) FROM jobs WHERE owner_id = $1 AND created_at > NOW() - INTERVAL '24 hours'"
            )
            .bind(user_id)
            .fetch_one(&self.pool)
            .await?;

            if daily_count >= max_daily.unwrap_or(50) as i64 {
                return Ok(false);
            }
        }
        Ok(true)
    }
}

use crossterm::{
    event::{self, KeyCode, KeyEventKind},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use keyforge_infra::HiveClient;
use keyforge_protocol::SystemMetrics;
use ratatui::{
    prelude::*,
    widgets::{Block, Borders, Cell, Paragraph, Row, Table},
};
use serde::Deserialize;
use std::io;
use std::process::Command;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

#[derive(Deserialize, Default, Clone)]
pub struct LogEntry {
    pub timestamp: String,
    pub level: String,
    pub message: String,
}

#[derive(Deserialize, Default, Clone)]
pub struct SystemStatusResponse {
    pub metrics: SystemMetrics,
    pub logs: Vec<LogEntry>,
}

#[derive(Clone, Default)]
struct ContainerMetrics {
    name: String,
    status: String,
    ram: String,
    cpu: String,
    is_online: bool,
}

struct DockerMonitor {
    state: Arc<Mutex<Vec<ContainerMetrics>>>,
}

impl DockerMonitor {
    fn new() -> Self {
        let state = Arc::new(Mutex::new(Vec::new()));
        let state_clone = state.clone();

        thread::spawn(move || loop {
            let metrics = Self::fetch();
            if let Ok(mut guard) = state_clone.lock() {
                *guard = metrics;
            }
            thread::sleep(Duration::from_secs(2));
        });

        Self { state }
    }

    fn get(&self) -> Vec<ContainerMetrics> {
        self.state.lock().map(|g| g.clone()).unwrap_or_default()
    }

    fn fetch() -> Vec<ContainerMetrics> {
        let mut containers = Vec::new();

        // 1. Get Status (Uptime) via `docker ps`
        // Format: Names \t Status
        let ps_output = Command::new("docker")
            .args(["ps", "--format", "{{.Names}}\t{{.Status}}"])
            .output()
            .ok();

        let mut status_map = std::collections::HashMap::new();
        if let Some(out) = ps_output {
            let s = String::from_utf8_lossy(&out.stdout);
            for line in s.lines() {
                if let Some((name, status)) = line.split_once('\t') {
                    status_map.insert(name.to_string(), status.to_string());
                }
            }
        }

        // 2. Get Stats (RAM/CPU) via `docker stats`
        // Format: Name \t MemUsage \t CPUPerc
        let stats_output = Command::new("docker")
            .args([
                "stats",
                "--no-stream",
                "--format",
                "{{.Name}}\t{{.MemUsage}}\t{{.CPUPerc}}",
            ])
            .output()
            .ok();

        if let Some(out) = stats_output {
            let s = String::from_utf8_lossy(&out.stdout);
            for line in s.lines() {
                let parts: Vec<&str> = line.split('\t').collect();
                if parts.len() >= 3 {
                    let name = parts[0].to_string();
                    // Filter for relevant containers
                    if name.contains("hive")
                        || name.contains("db")
                        || name.contains("postgres")
                        || name.contains("web")
                        || name.contains("apache")
                    {
                        let status = status_map
                            .get(&name)
                            .cloned()
                            .unwrap_or_else(|| "Unknown".to_string());
                        containers.push(ContainerMetrics {
                            name,
                            status,
                            ram: parts[1].to_string(),
                            cpu: parts[2].to_string(),
                            is_online: true,
                        });
                    }
                }
            }
        }

        // Sort for consistency
        containers.sort_by(|a, b| a.name.cmp(&b.name));
        containers
    }
}

pub async fn run_monitor(
    url: String,
    secret: Option<String>,
) -> Result<(), Box<dyn std::error::Error>> {
    // Setup Terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let client = HiveClient::new(url, secret).map_err(io::Error::other)?;
    let docker = DockerMonitor::new();

    let mut status = SystemStatusResponse::default();
    let mut error_msg = String::new();

    loop {
        // 1. Fetch API Data
        match client.get("sys/status").send().await {
            Ok(resp) => {
                if resp.status().is_success() {
                    if let Ok(s) = resp.json::<SystemStatusResponse>().await {
                        status = s;
                        error_msg.clear();
                    } else {
                        error_msg = "Failed to parse status JSON".to_string();
                    }
                } else {
                    error_msg = format!("API Error: {}", resp.status());
                }
            }
            Err(e) => error_msg = format!("Connection Failed: {}", e),
        }

        // 2. Fetch Docker Data (Non-blocking via thread)
        let containers = docker.get();

        // 3. Draw
        terminal.draw(|f| ui(f, &status, &containers, &error_msg))?;

        // 4. Input Handling
        if event::poll(Duration::from_millis(1000))? {
            if let event::Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press && key.code == KeyCode::Char('q') {
                    break;
                }
            }
        }
    }

    // Restore Terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}

fn ui(f: &mut Frame, status: &SystemStatusResponse, containers: &[ContainerMetrics], err: &str) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),      // Header
            Constraint::Length(3),      // Status Bar
            Constraint::Percentage(40), // Main Stats
            Constraint::Percentage(50), // Logs
            Constraint::Length(3),      // Footer
        ])
        .split(f.size());

    // Header
    let title = Paragraph::new("KEYFORGE HIVE COMMAND CENTER")
        .style(
            Style::default()
                .fg(Color::Cyan)
                .add_modifier(Modifier::BOLD),
        )
        .block(Block::default().borders(Borders::ALL));
    f.render_widget(title, chunks[0]);

    // Error Bar
    if !err.is_empty() {
        let err_widget = Paragraph::new(err)
            .style(Style::default().fg(Color::Red))
            .block(Block::default().borders(Borders::ALL).title("Status"));
        f.render_widget(err_widget, chunks[1]);
    } else {
        let uptime = status.metrics.uptime_secs;
        let status_text = format!("Host Uptime: {}s | Online", uptime);
        let status_widget = Paragraph::new(status_text)
            .style(Style::default().fg(Color::Green))
            .block(Block::default().borders(Borders::ALL).title("Status"));
        f.render_widget(status_widget, chunks[1]);
    }

    // Main Grid
    let main_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(chunks[2]);

    // Left: Cluster Stats
    let m = &status.metrics;
    let cluster_rows = vec![
        Row::new(vec![
            Cell::from("Active Jobs"),
            Cell::from(m.active_jobs.to_string()),
        ]),
        Row::new(vec![
            Cell::from("Total Results"),
            Cell::from(m.total_results.to_string()),
        ]),
        Row::new(vec![
            Cell::from("Nodes Online"),
            Cell::from(m.nodes_online.to_string()),
        ]),
        Row::new(vec![
            Cell::from("Cluster Ops/Sec"),
            Cell::from(format!("{:.2} M", m.total_ops_per_sec / 1_000_000.0)),
        ]),
    ];

    let cluster_table = Table::new(
        cluster_rows,
        [Constraint::Percentage(50), Constraint::Percentage(50)],
    )
    .block(
        Block::default()
            .title("Cluster State")
            .borders(Borders::ALL),
    )
    .header(Row::new(vec!["Metric", "Value"]).style(Style::default().fg(Color::Yellow)));

    f.render_widget(cluster_table, main_chunks[0]);

    // Right: Container Stats (Replaces Server RAM Gauge)
    let container_rows: Vec<Row> = containers
        .iter()
        .map(|c| {
            let style = if c.is_online {
                Style::default().fg(Color::Green)
            } else {
                Style::default().fg(Color::Red)
            };
            Row::new(vec![
                Cell::from(c.name.clone()),
                Cell::from(c.status.clone()),
                Cell::from(c.ram.clone()),
                Cell::from(c.cpu.clone()),
            ])
            .style(style)
        })
        .collect();

    let container_table = Table::new(
        container_rows,
        [
            Constraint::Percentage(25), // Name
            Constraint::Percentage(45), // Status
            Constraint::Percentage(15), // RAM
            Constraint::Percentage(15), // CPU
        ],
    )
    .block(
        Block::default()
            .title("Docker Containers")
            .borders(Borders::ALL),
    )
    .header(
        Row::new(vec!["Name", "Status", "RAM", "CPU"]).style(Style::default().fg(Color::Magenta)),
    );

    f.render_widget(container_table, main_chunks[1]);

    // Logs Panel
    let log_rows: Vec<Row> = status
        .logs
        .iter()
        .rev()
        .map(|l| {
            let color = match l.level.as_str() {
                "ERROR" => Color::Red,
                "WARN" => Color::Yellow,
                _ => Color::White,
            };
            Row::new(vec![
                Cell::from(l.timestamp.clone()),
                Cell::from(l.level.clone()),
                Cell::from(l.message.clone()),
            ])
            .style(Style::default().fg(color))
        })
        .collect();

    let log_table = Table::new(
        log_rows,
        [
            Constraint::Length(25),
            Constraint::Length(8),
            Constraint::Min(10),
        ],
    )
    .block(
        Block::default()
            .title("System Events (WARN/ERROR)")
            .borders(Borders::ALL),
    )
    .header(Row::new(vec!["Time", "Level", "Message"]).style(Style::default().fg(Color::Blue)));

    f.render_widget(log_table, chunks[3]);

    // Footer
    let footer = Paragraph::new("Press 'q' to exit")
        .style(Style::default().fg(Color::DarkGray))
        .block(Block::default().borders(Borders::TOP));
    f.render_widget(footer, chunks[4]);
}

