    let _ = tracing_subscriber::fmt::try_init();
    let (app, _, _, _temp) = setup_test_app().await;

    let response = app
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/user/nuke")
                .header("Content-Type", "application/json")
                .extension(ConnectInfo(test_addr()))
                .body(Body::from(
