pub trait ProgressCallback: Send + Sync {
    fn on_progress(&self, epoch: usize, score: f32, layout: &[u16], ips: f32) -> bool;
}

pub struct NoOpCallback;
impl ProgressCallback for NoOpCallback {
    fn on_progress(&self, _epoch: usize, _score: f32, _layout: &[u16], _ips: f32) -> bool {
        true
    }
}

/// Legacy Entry Point: Compiles the engine from scratch (Keep for backward compat).
pub fn optimize(req: &EngineRequest) -> OptimizationResult {
    optimize_with_callback(req, NoOpCallback)
}

/// Legacy Entry Point with Callback.
pub fn optimize_with_callback<CB: ProgressCallback>(
    req: &EngineRequest,
    callback: CB,
) -> OptimizationResult {
    let engine = ScoringEngine::new(&req.keyboard, &req.corpus, &req.rubric, &req.cost_overrides);
    let engine_arc = Arc::new(engine);

    // Determine pinned keys for legacy request
    let unlocked_indices: Vec<usize> = (0..engine_arc.key_count())
        .filter(|&i| i >= req.pinned_keys.len() || req.pinned_keys[i].is_none())
        .collect();

    evolve_internal(engine_arc, &req.config, unlocked_indices, req.initial_layout.clone(), callback, Some(&req.pinned_keys))
}

/// New Entry Point: Uses a pre-compiled, shared Physics Engine.
/// This is used by the Workspace Runtime.
pub fn evolve<CB: ProgressCallback>(
    engine: Arc<ScoringEngine>,
    config: &SearchConfig,
    callback: CB,
) -> OptimizationResult {
    // Default: All keys unlocked, default initial layout
    let unlocked_indices = (0..engine.key_count()).collect();
    evolve_internal(engine, config, unlocked_indices, None, callback, None)
}

/// Internal helper to share logic between legacy and new entry points.
fn evolve_internal<CB: ProgressCallback>(
    engine: Arc<ScoringEngine>,
    config: &SearchConfig,
    unlocked_indices: Vec<usize>,
    initial_layout: Option<Layout>,
    callback: CB,
    pinned_keys: Option<&[Option<u16>]>,
) -> OptimizationResult {
    let mut layout = initial_layout.unwrap_or_else(|| {
        let keys: Vec<u16> = (0..engine.key_count()).map(|i| i as u16).collect();
        Layout::new(keys)
    });

    // Apply pinned keys to the initial layout if provided
    if let Some(pinned) = pinned_keys {
        for (i, &p) in pinned.iter().enumerate() {
            if let Some(code) = p {
                if i < layout.keys.len() {
                    // Swap this key with wherever it currently is to maintain layout integrity
                    // (though evolve_internal doesn't strictly require integrity, it's good practice)
                    if let Some(pos) = layout.keys.iter().position(|&k| k == code) {
                        layout.keys.swap(i, pos);
                    } else {
                        layout.keys[i] = code;
                    }
                }
            }
        }
    }

    match config {
        SearchConfig::Annealing {
            steps,
            start_temp,
            end_temp,
            seed,
            patience,
            reheats,
            reheat_factor,
        } => {
            let mutation = GroupMutation { unlocked_indices };
            let acceptance = CoolingAnnealing;

            // We pass &*engine to dereference the Arc to a reference
            let mut optimizer = Optimizer::new(
                &engine,
                *steps,
                *start_temp,
                *end_temp,
                *seed,
                mutation,
                acceptance,
                *patience,
                *reheats,
                *reheat_factor,
            );

            let best_layout = optimizer.run(Some(layout), callback);

            OptimizationResult {
                score: engine.score(&best_layout),
                layout: best_layout,
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use keyforge_model::{Corpus, KeyNode, Keyboard, Rubric, SearchConfig};
    use std::sync::Arc;

    struct MockCallback {
        called: std::sync::atomic::AtomicBool,
    }

    impl ProgressCallback for MockCallback {
        fn on_progress(&self, _epoch: usize, _score: f32, _layout: &[u16], _ips: f32) -> bool {
            self.called.store(true, std::sync::atomic::Ordering::SeqCst);
            true
        }
    }

    fn setup_test_context() -> (Arc<ScoringEngine>, EngineRequest) {
        let keys = (0..30)
            .map(|i| KeyNode {
                id: i,
                label: format!("k{}", i),
                hand: if i < 15 { 0 } else { 1 },
                finger: (i % 5) as u8,
                row: (i / 10) as i8,
                col: (i % 10) as i8,
                x: (i % 10) as f32,
                y: (i / 10) as f32,
                is_home: false,
            })
            .collect();

        let keyboard = Arc::new(Keyboard::new(keys, 1));
        let mut corpus = Corpus::default();
        corpus.char_freqs[0] = 1000;
        corpus.char_freqs[1] = 500;
        corpus.bigrams.push((0, 1, 200));
        let corpus = Arc::new(corpus);

        let mut rubric = Rubric::default();
        rubric.sfb_base = 1.0;
        let rubric = Arc::new(rubric);

        let engine = ScoringEngine::new(&keyboard, &corpus, &rubric, &[]);

        let req = EngineRequest {
            keyboard: keyboard.clone(),
            corpus: corpus.clone(),
            rubric: rubric.clone(),
            config: SearchConfig::Annealing {
                steps: 10,
                start_temp: 1.0,
                end_temp: 0.1,
                seed: 42,
                patience: 5,
                reheats: 1,
                reheat_factor: 0.5,
            },
            initial_layout: None,
            pinned_keys: vec![],
            cost_overrides: vec![],
        };

        (Arc::new(engine), req)
    }

    #[test]
    fn test_optimize_legacy() {
        let (_, req) = setup_test_context();
        let result = optimize(&req);
        assert!(result.score > 0.0);
    }

    #[test]
    fn test_evolve_new_api() {
        let (engine, req) = setup_test_context();
        let result = evolve(engine, &req.config, NoOpCallback);
        assert!(result.score > 0.0);
    }

    #[test]
    fn test_noop_callback() {
        let callback = NoOpCallback;
        assert!(callback.on_progress(0, 0.0, &[], 0.0));
    }

    #[test]
    fn test_pinning_logic() {
        let mut req = setup_test_context().1;
        // Pin keys that are already in the layout to force a swap.
        // The default initial layout in evolve_internal is (0..30).
        // Let's pin key 5 at index 0.
        req.pinned_keys = vec![Some(5)];
        let result = optimize_with_callback(&req, NoOpCallback);
        assert_eq!(result.layout.keys[0], 5);

        // Pin something that doesn't exist? (Not possible since u16 0..30 is default)
        // Let's pin 29 at index 0 and 0 at index 29.
        req.pinned_keys = vec![None; 30];
        req.pinned_keys[0] = Some(29);
        req.pinned_keys[29] = Some(0);
        let result2 = optimize_with_callback(&req, NoOpCallback);
        assert_eq!(result2.layout.keys[0], 29);
        assert_eq!(result2.layout.keys[29], 0);

        // Pin a key NOT in the default layout (0..30)
        req.pinned_keys = vec![Some(100)];
        let result3 = optimize_with_callback(&req, NoOpCallback);
        assert_eq!(result3.layout.keys[0], 100);
    }
}

use super::state::SearchState;
use super::traits::{AcceptanceCriteria, MutationOperator};
use crate::ProgressCallback;
use keyforge_model::Layout;
use keyforge_physics::ScoringEngine;
use keyforge_protocol::constants::SCORE_SCALE;
use rand::SeedableRng;
use rand_xoshiro::Xoshiro256PlusPlus;
use std::time::Instant;

pub struct Optimizer<'a, M: MutationOperator, A: AcceptanceCriteria> {
    engine: &'a ScoringEngine,
    total_steps: usize,
    start_temp: f32,
    end_temp: f32,
    rng: Xoshiro256PlusPlus,
    mutation: M,
    acceptance: A,
    patience: usize,
    reheats: usize,
    reheat_factor: f32,
}

impl<'a, M: MutationOperator, A: AcceptanceCriteria> Optimizer<'a, M, A> {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        engine: &'a ScoringEngine,
        steps: usize,
        start_temp: f32,
        end_temp: f32,
        seed: u64,
        mutation: M,
        acceptance: A,
        patience: usize,
        reheats: usize,
        reheat_factor: f32,
    ) -> Self {
        let rng = if seed == 0 {
            Xoshiro256PlusPlus::from_entropy()
        } else {
            Xoshiro256PlusPlus::seed_from_u64(seed)
        };

        Self {
            engine,
            total_steps: steps,
            start_temp,
            end_temp,
            rng,
            mutation,
            acceptance,
            patience,
            reheats,
            reheat_factor,
        }
    }

    pub fn run<CB: ProgressCallback>(
        &mut self,
        initial_layout: Option<Layout>,
        callback: CB,
    ) -> Layout {
        let layout = initial_layout.unwrap_or_else(|| {
            let keys: Vec<u16> = (0..self.engine.key_count()).map(|i| i as u16).collect();
            Layout::new(keys)
        });

        let initial_score = self.engine.score_raw(&layout.keys);
        let mut state = SearchState::new(layout, initial_score, self.start_temp);

        let cooling_rate = if self.total_steps > 0 {
            (self.end_temp / self.start_temp).powf(1.0 / self.total_steps as f32)
        } else {
            0.0
        };

        let report_interval = (self.total_steps / 100).max(1000);
        let start_time = Instant::now();
        let mut last_report_time = start_time;
        let mut last_report_step = 0;

        let mut steps_since_improvement = 0;
        let mut reheats_left = self.reheats;

        for step in 0..self.total_steps {
            if let Some(proposal) = self.mutation.propose(
                self.engine,
                &state.current_layout,
                &state.pos_map,
                &mut self.rng,
            ) {
                if self
                    .acceptance
                    .should_accept(proposal.delta, state.temperature, &mut self.rng)
                {
                    proposal
                        .action
                        .apply(&mut state.current_layout, &mut state.pos_map);

                    state.current_score = state
                        .current_score
                        .checked_add(proposal.delta)
                        .unwrap_or(if proposal.delta > 0 {
                            i64::MAX
                        } else {
                            i64::MIN
                        });

                    if state.current_score < state.best_score {
                        state.best_score = state.current_score;
                        state.best_layout = state.current_layout.clone();
                        steps_since_improvement = 0;
                    } else {
                        steps_since_improvement += 1;
                    }
                } else {
                    steps_since_improvement += 1;
                }
            }

            // Reheating Logic
            if steps_since_improvement > self.patience && reheats_left > 0 {
                state.temperature = self.start_temp * self.reheat_factor; // Boost temp
                state.current_layout = state.best_layout.clone(); // Reset to best
                state.current_score = state.best_score;
                // Rebuild pos_map for best layout
                state.pos_map.fill(255);
                for (i, &code) in state.current_layout.keys.iter().enumerate() {
                    if (code as usize) < state.pos_map.len() {
                        state.pos_map[code as usize] = i as u16;
                    }
                }

                reheats_left -= 1;
                steps_since_improvement = 0;
            }

            state.temperature *= cooling_rate;
            if state.temperature < 1e-10 {
                state.temperature = 0.0;
            }

            if step > 0 && step % report_interval == 0 {
                let now = Instant::now();
                let elapsed = now.duration_since(last_report_time).as_secs_f32();
                let steps_done = step - last_report_step;

                let ips = if elapsed > 0.0 {
                    (steps_done as f32 / elapsed) / 1_000_000.0
                } else {
                    0.0
                };

                let score_f32 = state.best_score as f32 / SCORE_SCALE;
                if !callback.on_progress(step, score_f32, &state.best_layout.keys, ips) {
                    break;
                }

                last_report_time = now;
                last_report_step = step;
            }
        }

        state.best_layout
    }
}

