use super::traits::{AcceptanceCriteria, MutationAction, MutationOperator, MutationProposal};
use keyforge_model::Layout;
use keyforge_physics::ScoringEngine;
use rand::Rng;

#[allow(dead_code)]
pub struct SwapMutation {
    pub unlocked_indices: Vec<usize>,
}

impl MutationOperator for SwapMutation {
    fn propose(
        &self,
        engine: &ScoringEngine,
        layout: &Layout,
        pos_map: &[u16],
        rng: &mut impl Rng,
    ) -> Option<MutationProposal> {
        let len = self.unlocked_indices.len();
        if len < 2 {
            return None;
        }

        let i = rng.gen_range(0..len);
        let mut j = rng.gen_range(0..len);

        if i == j {
            j = (j + 1) % len;
        }

        let idx_a = self.unlocked_indices[i];
        let idx_b = self.unlocked_indices[j];

        let delta = engine.calculate_swap_delta(&layout.keys, pos_map, idx_a, idx_b);

        Some(MutationProposal {
            delta,
            action: MutationAction::Swap(idx_a, idx_b),
        })
    }
}

pub struct GroupMutation {
    pub unlocked_indices: Vec<usize>,
}

impl MutationOperator for GroupMutation {
    fn propose(
        &self,
        engine: &ScoringEngine,
        layout: &Layout,
        pos_map: &[u16],
        rng: &mut impl Rng,
    ) -> Option<MutationProposal> {
        let len = self.unlocked_indices.len();
        if len < 2 {
            return None;
        }

        // Adaptive Strategy:
        // If < 3 keys, must use 2-way swap.
        // If >= 3 keys, 50% chance of 2-way, 50% chance of 3-way.
        let use_swap = len < 3 || rng.gen_bool(0.5);

        if use_swap {
            let i = rng.gen_range(0..len);
            let mut j = rng.gen_range(0..len);
            while i == j {
                j = rng.gen_range(0..len);
            }

            let idx_a = self.unlocked_indices[i];
            let idx_b = self.unlocked_indices[j];

            let delta = engine.calculate_swap_delta(&layout.keys, pos_map, idx_a, idx_b);

            return Some(MutationProposal {
                delta,
                action: MutationAction::Swap(idx_a, idx_b),
            });
        }

        // 3-Way Swap
        let i = rng.gen_range(0..len);
        let mut j = rng.gen_range(0..len);
        while j == i {
            j = rng.gen_range(0..len);
        }
        let mut k = rng.gen_range(0..len);
        while k == i || k == j {
            k = rng.gen_range(0..len);
        }

        let idx_a = self.unlocked_indices[i];
        let idx_b = self.unlocked_indices[j];
        let idx_c = self.unlocked_indices[k];

        // Calculate delta via full score difference (simpler for 3-way)
        let old_score = engine.score_raw(&layout.keys);

        let mut temp_layout = layout.clone();
        let temp = temp_layout.keys[idx_c];
        temp_layout.keys[idx_c] = temp_layout.keys[idx_b];
        temp_layout.keys[idx_b] = temp_layout.keys[idx_a];
        temp_layout.keys[idx_a] = temp;

        let new_score = engine.score_raw(&temp_layout.keys);
        let delta = new_score - old_score;

        Some(MutationProposal {
            delta,
            action: MutationAction::GroupSwap(idx_a, idx_b, idx_c),
        })
    }
}

pub struct CoolingAnnealing;

impl AcceptanceCriteria for CoolingAnnealing {
    fn should_accept(&mut self, delta: i64, temperature: f32, rng: &mut impl Rng) -> bool {
        if delta <= 0 {
            return true;
        }

        if temperature < 1e-6 {
            return false;
        }

        // P2 FIX: Updated scaling factor to 1,000,000
        let delta_f = delta as f32 / 1_000_000.0;
        let probability = (-delta_f / temperature).exp();
        rng.gen::<f32>() < probability
    }
}

use keyforge_model::Layout;
use keyforge_physics::ScoringEngine;
use rand::Rng;

#[derive(Debug, Clone, Copy)]
pub enum MutationAction {
    Swap(usize, usize),
    GroupSwap(usize, usize, usize),
}

impl MutationAction {
    #[inline(always)]
    pub fn apply(self, layout: &mut Layout, pos_map: &mut [u16]) {
        match self {
            MutationAction::Swap(a, b) => {
                layout.keys.swap(a, b);
                let code_a = layout.keys[a] as usize;
                let code_b = layout.keys[b] as usize;
                // Update pos_map if within range
                if code_a < pos_map.len() {
                    pos_map[code_a] = a as u16;
                }
                if code_b < pos_map.len() {
                    pos_map[code_b] = b as u16;
                }
            }
            MutationAction::GroupSwap(a, b, c) => {
                // A -> B, B -> C, C -> A
                let temp = layout.keys[c];
                layout.keys[c] = layout.keys[b];
                layout.keys[b] = layout.keys[a];
                layout.keys[a] = temp;

                let code_a = layout.keys[a] as usize;
                let code_b = layout.keys[b] as usize;
                let code_c = layout.keys[c] as usize;

                if code_a < pos_map.len() {
                    pos_map[code_a] = a as u16;
                }
                if code_b < pos_map.len() {
                    pos_map[code_b] = b as u16;
                }
                if code_c < pos_map.len() {
                    pos_map[code_c] = c as u16;
                }
            }
        }
    }
}

/// A proposed change to a layout.
pub struct MutationProposal {
    pub delta: i64,
    /// Enum describing the mutation to apply.
    /// Replaces Box<dyn FnOnce> to avoid heap allocation.
    pub action: MutationAction,
}

/// Defines how to generate a potential layout change.
pub trait MutationOperator {
    fn propose(
        &self,
        engine: &ScoringEngine,
        layout: &Layout,
        pos_map: &[u16],
        rng: &mut impl Rng,
    ) -> Option<MutationProposal>;
}

/// Defines the criteria for accepting a proposed mutation.
pub trait AcceptanceCriteria {
    fn should_accept(&mut self, delta: i64, temperature: f32, rng: &mut impl Rng) -> bool;
}

use keyforge_model::Layout;
use keyforge_evolution::supervisor::traits::MutationAction;
use proptest::prelude::*;

// Helper to generate a random layout of 30 unique keys [0..29]
fn arb_layout() -> impl Strategy<Value = Layout> {
    Just((0..30).collect::<Vec<u16>>()).prop_shuffle().prop_map(Layout::new)
}

proptest! {
    #[test]
    fn test_swap_conservation(
        mut layout in arb_layout(),
        a in 0usize..30,
        b in 0usize..30
    ) {
        let original_sum: u32 = layout.keys.iter().map(|&x| x as u32).sum();
        let mut pos_map = vec![65535u16; 256];

        // Initialize pos_map
        for (i, &code) in layout.keys.iter().enumerate() {
            if (code as usize) < pos_map.len() {
                pos_map[code as usize] = i as u16;
            }
        }

        let action = MutationAction::Swap(a, b);
        action.apply(&mut layout, &mut pos_map);

        let new_sum: u32 = layout.keys.iter().map(|&x| x as u32).sum();

        // Invariant 1: Conservation of keys
        assert_eq!(original_sum, new_sum, "Swap must not create or destroy keys");

        // Invariant 2: PosMap coherence
        for (i, &code) in layout.keys.iter().enumerate() {
            if (code as usize) < pos_map.len() {
                assert_eq!(pos_map[code as usize], i as u16, "PosMap must be coherent after swap");
            }
        }
    }

    #[test]
    fn test_group_swap_conservation(
        mut layout in arb_layout(),
        a in 0usize..30,
        b in 0usize..30,
        c in 0usize..30
    ) {
        let original_sum: u32 = layout.keys.iter().map(|&x| x as u32).sum();
        let mut pos_map = vec![65535u16; 256];

        for (i, &code) in layout.keys.iter().enumerate() {
            if (code as usize) < pos_map.len() {
                pos_map[code as usize] = i as u16;
            }
        }

        let action = MutationAction::GroupSwap(a, b, c);
        action.apply(&mut layout, &mut pos_map);

        let new_sum: u32 = layout.keys.iter().map(|&x| x as u32).sum();

        assert_eq!(original_sum, new_sum, "GroupSwap must not create or destroy keys");

        for (i, &code) in layout.keys.iter().enumerate() {
            if (code as usize) < pos_map.len() {
                assert_eq!(pos_map[code as usize], i as u16, "PosMap must be coherent after group swap");
            }
        }
    }
}

#[test]
fn test_swap_indices_same() {
    let mut layout = Layout::new(vec![1, 2, 3]);
    let mut pos_map = vec![65535u16; 10];
    pos_map[1] = 0;
    pos_map[2] = 1;
    pos_map[3] = 2;

    let action = MutationAction::Swap(1, 1);
    action.apply(&mut layout, &mut pos_map);

    assert_eq!(layout.keys.as_slice(), &[1, 2, 3]);
    assert_eq!(pos_map[2], 1);
}

