use crate::Exporter;
use anyhow::Result;
use keyforge_adapter::parsing::{parse_key, KeyAction};

pub struct QmkExporter;

fn sanitize(s: &str) -> String {
    // Strict allowlist for C identifiers and macros.
    s.chars()
        .filter(|c| c.is_ascii_alphanumeric() || *c == '_' || *c == '(' || *c == ')' || *c == ',')
        .collect()
}

const MAX_OUTPUT_SIZE: usize = 1024 * 1024; // 1MB Limit
const MAX_KEYS: usize = 200; // Physical limit for standard boards

impl Exporter for QmkExporter {
    fn generate(&self, layout_name: &str, keys: &[String]) -> Result<String> {
        if keys.len() > MAX_KEYS {
            return Err(anyhow::anyhow!(
                "Too many keys for QMK export (Limit: {})",
                MAX_KEYS
            ));
        }

        let mut out = String::with_capacity(4096);
        // Sanitize layout name for C identifier
        let safe_name = layout_name.replace(" ", "_").to_uppercase();
        let safe_name = sanitize(&safe_name);

        out.push_str(&format!("// KeyForge QMK Export: {}\n", layout_name));
        out.push_str(&format!(
            "// Generated at: {}\n\n",
            chrono::Local::now().to_rfc3339()
        ));

        out.push_str("#include QMK_KEYBOARD_H\n\n");
        out.push_str("const uint16_t PROGMEM keymaps[][MATRIX_ROWS][MATRIX_COLS] = {\n");
        out.push_str(&format!("  [{}] = LAYOUT(\n", safe_name));
        out.push_str("    ");

        let mut line_len = 0;
        for (i, key_str) in keys.iter().enumerate() {
            // Safety Check
            if out.len() > MAX_OUTPUT_SIZE {
                return Err(anyhow::anyhow!("Output size limit exceeded"));
            }

            let action = parse_key(key_str);
            let code = match action {
                KeyAction::Simple(s) => sanitize(&s),
                KeyAction::Transparent => "_______".to_string(),
                KeyAction::NoOp => "XXXXXXX".to_string(),
                KeyAction::LayerMomentary(l) => format!("MO({})", l),
                KeyAction::LayerToggle(l) => format!("TG({})", l),
                KeyAction::LayerOn(l) => format!("TO({})", l),
                KeyAction::ModTap { mod_name, key } => {
                    format!("{}_T({})", sanitize(&mod_name), sanitize(&key))
                }
                KeyAction::LayerTap { layer, key } => format!("LT({}, {})", layer, sanitize(&key)),
                KeyAction::StickyMod(m) => {
                    let mod_str = sanitize(&m);
                    let qmk_mod = match mod_str.as_str() {
                        "LSFT" | "SFT" | "LSHIFT" => "MOD_LSFT",
                        "RSFT" | "RSHIFT" => "MOD_RSFT",
                        "LCTL" | "CTL" | "LCTRL" => "MOD_LCTL",
                        "RCTL" | "RCTRL" => "MOD_RCTL",
                        "LALT" | "ALT" => "MOD_LALT",
                        "RALT" | "ALGR" => "MOD_RALT",
                        "LGUI" | "GUI" | "WIN" | "CMD" => "MOD_LGUI",
                        "RGUI" => "MOD_RGUI",
                        _ => &mod_str,
                    };
                    format!("OSM({})", qmk_mod)
                }
                KeyAction::CapsWord => "CAPS_WORD".to_string(),
                KeyAction::Raw(s) => sanitize(&s),
            };

            out.push_str(&code);

            if i < keys.len() - 1 {
                out.push_str(", ");
            }

            line_len += 1;
            if line_len >= 12 {
                out.push_str("\n    ");
                line_len = 0;
            }
        }

        out.push_str("\n  ),\n");
        out.push_str("};\n");
        Ok(out)
    }
}

use crate::Exporter;
use anyhow::Result;
use serde_json::json;

pub struct ViaExporter;

impl Exporter for ViaExporter {
    fn generate(&self, layout_name: &str, keys: &[String]) -> Result<String> {
        if keys.is_empty() {
            return Err(anyhow::anyhow!("Layout cannot be empty"));
        }

        // VIA "Import Keymap" expects a JSON object with a "layers" array.
        let mapped_keys: Vec<String> = keys
            .iter()
            .map(|k| {
                let upper = k.to_uppercase();
                match upper.as_str() {
                    "TRNS" | "_______" => "KC_TRNS".to_string(),
                    "NO" | "XXXXXXX" => "KC_NO".to_string(),
                    _ => {
                        if !upper.starts_with("KC_")
                            && !upper.contains('(')
                            && upper.chars().all(|c| c.is_alphanumeric() || c == '_')
                        {
                            format!("KC_{}", upper)
                        } else {
                            upper
                        }
                    }
                }
            })
            .collect();

        let json_output = json!({
            "name": layout_name,
            "layers": [
                mapped_keys
            ]
        });

        Ok(serde_json::to_string_pretty(&json_output)?)
    }
}

use crate::Exporter;
use anyhow::Result;
use keyforge_adapter::parsing::{parse_key, KeyAction};

pub struct ZmkExporter;

fn sanitize(s: &str) -> String {
    s.replace(|c: char| !c.is_alphanumeric() && c != '_', "")
}

impl Exporter for ZmkExporter {
    fn generate(&self, layout_name: &str, keys: &[String]) -> Result<String> {
        let mut out = String::new();

        out.push_str(&format!("// KeyForge ZMK Export: {}\n", layout_name));
        out.push_str(&format!(
            "// Generated at: {}\n\n",
            chrono::Local::now().to_rfc3339()
        ));

        out.push_str("/ {\n");
        out.push_str("    keymap {\n");
        out.push_str("        compatible = \"zmk,keymap\";\n\n");
        out.push_str("        default_layer {\n");
        out.push_str("            bindings = <\n");
        out.push_str("                ");

        let mut line_len = 0;
        for (i, key_str) in keys.iter().enumerate() {
            let action = parse_key(key_str);
            let code = match action {
                KeyAction::Simple(s) => {
                    let clean = s.strip_prefix("KC_").unwrap_or(&s);
                    format!("&kp {}", sanitize(clean))
                }
                KeyAction::Transparent => "&trans".to_string(),
                KeyAction::NoOp => "&none".to_string(),
                KeyAction::LayerMomentary(l) => format!("&mo {}", l),
                KeyAction::LayerToggle(l) => format!("&tog {}", l),
                KeyAction::LayerOn(l) => format!("&to {}", l),
                KeyAction::ModTap { mod_name, key } => {
                    let zmk_mod = match mod_name.as_str() {
                        "LSFT" | "SFT" => "LSHIFT",
                        "RSFT" => "RSHIFT",
                        "LCTL" | "CTL" => "LCTRL",
                        "RCTL" => "RCTRL",
                        "LALT" | "ALT" => "LALT",
                        "RALT" | "ALGR" => "RALT",
                        "LGUI" | "GUI" | "WIN" | "CMD" => "LGUI",
                        "RGUI" => "RGUI",
                        _ => &mod_name,
                    };
                    let clean_key = key.strip_prefix("KC_").unwrap_or(&key);
                    format!("&mt {} {}", sanitize(zmk_mod), sanitize(clean_key))
                }
                KeyAction::LayerTap { layer, key } => {
                    let clean_key = key.strip_prefix("KC_").unwrap_or(&key);
                    format!("&lt {} {}", layer, sanitize(clean_key))
                }
                KeyAction::StickyMod(m) => {
                    let zmk_mod = match m.as_str() {
                        "LSFT" | "SFT" => "LSHIFT",
                        "RSFT" => "RSHIFT",
                        "LCTL" | "CTL" => "LCTRL",
                        "RCTL" => "RCTRL",
                        "LALT" | "ALT" => "LALT",
                        "RALT" | "ALGR" => "RALT",
                        "LGUI" | "GUI" | "WIN" | "CMD" => "LGUI",
                        "RGUI" => "RGUI",
                        _ => &m,
                    };
                    format!("&sk {}", sanitize(zmk_mod))
                }
                KeyAction::CapsWord => "&caps_word".to_string(),
                KeyAction::Raw(s) => sanitize(&s),
            };

            out.push_str(&code);

            if i < keys.len() - 1 {
                out.push(' ');
            }

            line_len += 1;
            if line_len >= 12 {
                out.push_str("\n                ");
                line_len = 0;
            }
        }

        out.push_str("\n            >;\n");
        out.push_str("        };\n");
        out.push_str("    };\n");
        out.push_str("};\n");

        Ok(out)
    }
}

use keyforge_model::error::KeyForgeError;
use keyforge_model::loader::{AssetLoader, LoaderResult, RawCostData};
use keyforge_model::Corpus;
use keyforge_protocol::config::CorpusSource;
use keyforge_protocol::constants::MAX_INPUT_FILE_SIZE;
use keyforge_protocol::geometry::KeyboardDefinition;
use keyforge_protocol::keycodes::KeycodeRegistry;
use sha2::Digest;
use std::fs::File;
use std::io::BufReader;
use std::path::{Path, PathBuf};

#[derive(Clone)]
pub struct FsProvider {
    pub root: PathBuf,
}

impl FsProvider {
    pub fn new(root: PathBuf) -> Self {
        Self { root }
    }

    fn check_size(&self, path: &Path) -> LoaderResult<()> {
        let meta = std::fs::metadata(path)?;
        if meta.len() > MAX_INPUT_FILE_SIZE {
            return Err(KeyForgeError::InvalidData(format!(
                "File {:?} exceeds size limit of {} bytes",
                path, MAX_INPUT_FILE_SIZE
            )));
        }
        Ok(())
    }

    fn load_binary<T: serde::de::DeserializeOwned>(&self, path: &Path) -> LoaderResult<T> {
        self.check_size(path)?;
        let file = File::open(path)?;
        let decoder =
            zstd::Decoder::new(file).map_err(|e| KeyForgeError::Compression(e.to_string()))?;
        rmp_serde::from_read(decoder).map_err(|e| KeyForgeError::MsgPack(e.to_string()))
    }

    fn load_json<T: serde::de::DeserializeOwned>(&self, path: &Path) -> LoaderResult<T> {
        self.check_size(path)?;
        let file = File::open(path)?;
        let reader = BufReader::new(file);
        serde_json::from_reader(reader).map_err(KeyForgeError::Serde)
    }

    fn resolve_system_path(&self, category: &str, stem: &str) -> Option<PathBuf> {
        // Map categories to new structure
        let sub = match category {
            "keyboards" => "keyboards/models",
            "weights" => "weights",
            "config" => "config",
            "keymap_extras" => "keymap_extras",
            _ => category,
        };

        let p = self
            .root
            .join("system")
            .join(sub)
            .join(format!("{}.mpk.zst", stem));

        if p.exists() {
            return Some(p);
        }

        // Fallback for direct mapping if needed (e.g. if we passed "keyboards/models" as category)
        let p_direct = self
            .root
            .join("system")
            .join(category)
            .join(format!("{}.mpk.zst", stem));
        if p_direct.exists() {
            return Some(p_direct);
        }

        None
    }

    fn resolve_user_path(&self, category: &str, stem: &str) -> Option<PathBuf> {
        let p = self
            .root
            .join("user")
            .join(category)
            .join(format!("{}.json", stem));
        p.exists().then_some(p)
    }

    pub fn get_corpus_hash(&self, id: &str) -> LoaderResult<String> {
        let mut hasher = sha2::Sha256::new();
        let files = ["1grams", "2grams", "3grams", "words"];
        let is_system = self.root.join("system/corpora").join(id).exists();
        let base = if is_system {
            self.root.join("system/corpora").join(id)
        } else {
            self.root.join("user/corpora").join(id)
        };
        let ext = if is_system { "mpk.zst" } else { "json" };
        for f in files {
            let path = base.join(format!("{}.{}", f, ext));
            if path.exists() {
                hasher.update(&std::fs::read(&path)?);
            }
        }
        Ok(hex::encode(hasher.finalize()))
    }
}

impl AssetLoader for FsProvider {
    fn load_keyboard(&self, name: &str) -> LoaderResult<KeyboardDefinition> {
        let stem = name.strip_suffix(".json").unwrap_or(name);
        if let Some(p) = self.resolve_system_path("keyboards", stem) {
            return self.load_binary(&p);
        }
        if let Some(p) = self.resolve_user_path("keyboards", stem) {
            return self.load_json(&p);
        }
        Err(KeyForgeError::NotFound(name.to_string()))
    }

    fn load_corpus(&self, sources: &[CorpusSource]) -> LoaderResult<Corpus> {
        let mut corpus = Corpus::default();
        for src in sources {
            let is_system = self.root.join("system/corpora").join(&src.id).exists();
            let base = if is_system {
                self.root.join("system/corpora").join(&src.id)
            } else {
                self.root.join("user/corpora").join(&src.id)
            };
            let ext = if is_system { "mpk.zst" } else { "json" };

            let load_part = |stem: &str| -> LoaderResult<Vec<serde_json::Value>> {
                let p = base.join(format!("{}.{}", stem, ext));
                if !p.exists() {
                    return Ok(vec![]);
                }
                if is_system {
                    self.load_binary(&p)
                } else {
                    self.load_json(&p)
                }
            };

            for e in load_part("1grams")? {
                if let Some(c) = e["char"].as_str().and_then(|s| s.chars().next()) {
                    if (c as usize) < 256 {
                        corpus.char_freqs[c as usize] +=
                            (e["freq"].as_u64().unwrap_or(0) as f32 * src.weight).round() as u32;
                    }
                }
            }
            for e in load_part("2grams")? {
                let c1 = e["char1"]
                    .as_str()
                    .and_then(|s| s.chars().next())
                    .unwrap_or('\0') as u16;
                let c2 = e["char2"]
                    .as_str()
                    .and_then(|s| s.chars().next())
                    .unwrap_or('\0') as u16;
                corpus.bigrams.push((
                    c1,
                    c2,
                    (e["freq"].as_u64().unwrap_or(0) as f32 * src.weight).round() as u32,
                ));
            }
            for e in load_part("3grams")? {
                let c1 = e["char1"]
                    .as_str()
                    .and_then(|s| s.chars().next())
                    .unwrap_or('\0') as u16;
                let c2 = e["char2"]
                    .as_str()
                    .and_then(|s| s.chars().next())
                    .unwrap_or('\0') as u16;
                let c3 = e["char3"]
                    .as_str()
                    .and_then(|s| s.chars().next())
                    .unwrap_or('\0') as u16;
                corpus.trigrams.push((
                    c1,
                    c2,
                    c3,
                    (e["freq"].as_u64().unwrap_or(0) as f32 * src.weight).round() as u32,
                ));
            }
            for e in load_part("words")? {
                if let Some(w) = e["word"].as_str() {
                    corpus.words.push((
                        w.to_string(),
                        (e["freq"].as_u64().unwrap_or(0) as f32 * src.weight).round() as u32,
                    ));
                }
            }
        }
        Ok(corpus)
    }

    fn load_cost_matrix(&self, filename: &str) -> LoaderResult<RawCostData> {
        let stem = filename.strip_suffix(".json").unwrap_or(filename);
        if let Some(p) = self.resolve_system_path("weights", stem) {
            return self.load_binary(&p);
        }
        if let Some(p) = self.resolve_user_path("weights", stem) {
            #[derive(serde::Deserialize)]
            struct CostEntry {
                from_key: String,
                to_key: String,
                cost_ms: f32,
            }
            #[derive(serde::Deserialize)]
            #[serde(untagged)]
            enum Format {
                Wrapped { entries: Vec<CostEntry> },
                Direct(Vec<CostEntry>),
            }
            let format: Format = self.load_json(&p)?;
            let entries = match format {
                Format::Wrapped { entries } => entries,
                Format::Direct(v) => v,
            };
            return Ok(RawCostData {
                entries: entries
                    .into_iter()
                    .map(|e| (e.from_key, e.to_key, e.cost_ms))
                    .collect(),
            });
        }
        Err(KeyForgeError::NotFound(filename.to_string()))
    }

    fn load_keycodes(&self, filename: &str) -> LoaderResult<KeycodeRegistry> {
        let stem = filename.strip_suffix(".json").unwrap_or(filename);
        if let Some(p) = self.resolve_system_path("config", stem) {
            let defs = self.load_binary(&p)?;
            return Ok(KeycodeRegistry::new(defs));
        }
        let p = self
            .resolve_user_path("config", stem)
            .ok_or(KeyForgeError::NotFound(filename.to_string()))?;
        let defs = self.load_json(&p)?;
        Ok(KeycodeRegistry::new(defs))
    }
}

use crate::error::InfraResult;
use crate::net::client::HiveClient;
use crate::net::network::ensure_file;
use keyforge_protocol::{CostMatrixSource, JobConfig};
use sha2::{Digest, Sha256};
use std::path::PathBuf;
use tracing::info;

pub struct AssetManager {
    client: HiveClient,
    root: PathBuf,
}

impl AssetManager {
    pub fn new(client: HiveClient, root: PathBuf) -> Self {
        Self { client, root }
    }

    pub async fn ensure_keyboard(&self, name: &str) -> InfraResult<PathBuf> {
        let safe_name = crate::util::common::sanitize_filename(name);
        let filename = format!("{}.json", safe_name);
        let local_path = self.root.join("keyboards").join(&filename);
        let remote_path = format!("data/keyboards/{}", filename);
        let url = self.client.url(&remote_path);

        ensure_file(&self.client, &url, &local_path, None).await?;
        Ok(local_path)
    }

    pub async fn ensure_cost_matrix(&self, filename: &str) -> InfraResult<PathBuf> {
        let local_path = self.root.join(filename);
        let remote_path = format!("data/{}", filename);
        let url = self.client.url(&remote_path);

        ensure_file(&self.client, &url, &local_path, None).await?;
        Ok(local_path)
    }

    pub async fn ensure_corpus(
        &self,
        corpus_id: &str,
        expected_hash: Option<&str>,
    ) -> InfraResult<PathBuf> {
        let bundle_name = if corpus_id.is_empty() || corpus_id == "default" {
            "text/en_std"
        } else {
            corpus_id
        };

        let bundle_dir = self.root.join("corpora").join(bundle_name);
        let files = ["1grams.json", "2grams.json", "3grams.json", "words.json"];

        // 1. Verify existing
        if let Some(hash) = expected_hash {
            let root = self.root.clone();
            let bundle_name_owned = bundle_name.to_string();
            let hash_owned = hash.to_string();

            let match_found = tokio::task::spawn_blocking(move || {
                let provider = crate::FsProvider::new(root);
                match provider.get_corpus_hash(&bundle_name_owned) {
                    Ok(h) => h == hash_owned,
                    Err(_) => false,
                }
            })
            .await
            .unwrap_or(false);

            if match_found {
                return Ok(bundle_dir);
            }

            // Mismatch: Clean up to force download
            info!(
                "Corpus hash mismatch for '{}'. Re-downloading.",
                bundle_name
            );
            for f in files {
                let p = bundle_dir.join(f);
                if p.exists() {
                    let _ = tokio::fs::remove_file(p).await;
                }
            }
        }

        for f in files {
            let local_path = bundle_dir.join(f);
            let remote_path = format!("data/corpora/{}/{}", bundle_name, f);
            let url = self.client.url(&remote_path);

            ensure_file(&self.client, &url, &local_path, None).await?;
        }

        // 3. Verify after download (if hash provided)
        if let Some(hash) = expected_hash {
            let root = self.root.clone();
            let bundle_name_owned = bundle_name.to_string();
            let hash_owned = hash.to_string();

            let match_found = tokio::task::spawn_blocking(move || {
                let provider = crate::FsProvider::new(root);
                match provider.get_corpus_hash(&bundle_name_owned) {
                    Ok(h) => h == hash_owned,
                    Err(_) => false,
                }
            })
            .await
            .unwrap_or(false);

            if !match_found {
                return Err(crate::error::InfraError::HashMismatch {
                    expected: hash.to_string(),
                    actual: "mismatch after download".to_string(),
                });
            }
        }

        Ok(bundle_dir)
    }

    pub async fn sync_job_assets(&self, config: &JobConfig) -> InfraResult<(String, String)> {
        info!("📦 Syncing assets for job...");

        let cost_path = match &config.cost_matrix {
            CostMatrixSource::Predefined(filename) => {
                self.ensure_cost_matrix(filename).await?;
                filename.clone()
            }
            CostMatrixSource::Custom(content) => {
                let mut hasher = Sha256::new();
                hasher.update(content);
                let hash = hex::encode(hasher.finalize());
                let filename = format!("custom_cost_{}.json", hash);
                let path = self.root.join(&filename);
                if !path.exists() {
                    crate::fs::io::atomic_write(&path, content)?;
                }
                filename
            }
        };

        for source in &config.corpora {
            self.ensure_corpus(&source.id, source.hash.as_deref())
                .await?;
        }

        Ok((cost_path, "corpora".to_string()))
    }
}

use crate::config::HiveConfig;
use bytes::Bytes;
use keyforge_infra::{listing, AssetLoader, FsProvider, RawCostData, ServerManifest};
use keyforge_model::loader::LoaderResult;
use keyforge_model::Corpus;
use keyforge_protocol::config::{Config as AppConfig, CorpusSource};
use keyforge_protocol::constants::MAX_INPUT_FILE_SIZE;
use keyforge_protocol::geometry::KeyboardDefinition;
use keyforge_protocol::keycodes::KeycodeRegistry;
use moka::sync::Cache;
use notify::{Config, Event, RecommendedWatcher, RecursiveMode, Watcher};
use std::path::PathBuf;
use std::sync::Arc;
use std::time::Duration;
use tracing::{error, info, warn};

struct AssetCacheState {
    provider: FsProvider,

    // Parsed Objects
    costs: Cache<String, Arc<RawCostData>>,
    corpora: Cache<String, Arc<Corpus>>,
    keyboards: Cache<String, Arc<KeyboardDefinition>>,
    keycodes: Cache<String, Arc<KeycodeRegistry>>,
    hive_config: Cache<String, Arc<HiveConfig>>,
    app_config: Cache<String, Arc<AppConfig>>,

    // Raw File Cache (for Sync)
    file_cache: Cache<String, Bytes>,
    manifest: Cache<String, Arc<ServerManifest>>,

    _watcher: Option<RecommendedWatcher>,
}

#[derive(Clone)]
pub struct GlobalAssetCache {
    state: Arc<AssetCacheState>,
}

impl GlobalAssetCache {
    pub fn new(data_path: PathBuf) -> Self {
        let provider = FsProvider::new(data_path.clone());

        let costs = Cache::builder().max_capacity(100).build();
        let corpora = Cache::builder().max_capacity(50).build();
        let keyboards = Cache::builder().max_capacity(100).build();
        let keycodes = Cache::builder().max_capacity(10).build();
        let hive_config = Cache::builder().max_capacity(1).build();
        let app_config = Cache::builder().max_capacity(1).build();

        let file_cache = Cache::builder().max_capacity(1000).build();
        let manifest = Cache::builder().max_capacity(1).build();

        let costs_clone = costs.clone();
        let corpora_clone = corpora.clone();
        let keyboards_clone = keyboards.clone();
        let keycodes_clone = keycodes.clone();
        let hive_config_clone = hive_config.clone();
        let app_config_clone = app_config.clone();
        let data_path_clone = data_path.clone();

        let watcher_fn = move |res: notify::Result<Event>| match res {
            Ok(event) => {
                if event.kind.is_access() {
                    return;
                }

                for path in event.paths {
                    if let Ok(rel) = path.strip_prefix(&data_path_clone) {
                        let path_str = rel.to_string_lossy();
                        info!("♻️  File changed: {}", path_str);

                        if path_str.contains("keyboards") {
                            keyboards_clone.invalidate_all();
                        } else if path_str.contains("corpora") {
                            corpora_clone.invalidate_all();
                        } else if path_str.contains("weights") {
                            costs_clone.invalidate_all();
                        } else if path_str.contains("config") {
                            if path_str.contains("keycodes") {
                                keycodes_clone.invalidate_all();
                            } else if path_str.contains("hive.json") {
                                hive_config_clone.invalidate_all();
                            } else if path_str.contains("config.json") {
                                app_config_clone.invalidate_all();
                            }
                        }
                    }
                }
            }
            Err(e) => error!("Watcher error: {:?}", e),
        };

        let mut watcher = RecommendedWatcher::new(watcher_fn, Config::default()).ok();

        if let Some(w) = &mut watcher {
            if let Err(e) = w.watch(&data_path, RecursiveMode::Recursive) {
                error!("Failed to start file watcher: {}", e);
            } else {
                info!("👀 Hot-Reload Watcher Active on {:?}", data_path);
            }
        }

        Self {
            state: Arc::new(AssetCacheState {
                provider,
                costs,
                corpora,
                keyboards,
                keycodes,
                hive_config,
                app_config,
                file_cache,
                manifest,
                _watcher: watcher,
            }),
        }
    }

    pub fn warm_all(&self) -> Result<(), String> {
        info!("🔥 Warming Asset Cache (Full Binary Verification)...");
        let system_root = self.state.provider.root.join("system");
        if !system_root.exists() {
            return Err("System directory missing".into());
        }

        let manifest = keyforge_infra::generate_manifest(&system_root)
            .map_err(|e| format!("Failed to generate manifest: {}", e))?;

        self.state
            .manifest
            .insert("default".to_string(), Arc::new(manifest.clone()));

        // Explicit counters for accurate reporting
        let mut count_files = 0;
        let mut count_keyboards = 0;
        let mut count_corpora = 0;

        for (rel_path, _) in manifest.files {
            let full_path = system_root.join(&rel_path);
            let bytes = match std::fs::read(&full_path) {
                Ok(b) => b,
                Err(e) => return Err(format!("Read error {}: {}", rel_path, e)),
            };

            self.state
                .file_cache
                .insert(rel_path.clone(), Bytes::from(bytes));
            count_files += 1;

            if rel_path.starts_with("keyboards/") {
                let stem = std::path::Path::new(&rel_path)
                    .file_stem()
                    .and_then(|s| s.to_str())
                    .unwrap_or("")
                    .strip_suffix(".mpk")
                    .unwrap_or("")
                    .to_string();
                if !stem.is_empty() {
                    if let Err(e) = self.load_keyboard(&stem) {
                        tracing::warn!("Eager load failed for keyboard {}: {}", stem, e);
                    } else {
                        count_keyboards += 1;
                    }
                }
            } else if rel_path.starts_with("corpora/") && rel_path.ends_with("1grams.mpk.zst") {
                let path = std::path::Path::new(&rel_path);
                if let Some(parent) = path.parent() {
                    if let Ok(id_path) = parent.strip_prefix("corpora") {
                        let id = id_path.to_string_lossy().replace('\\', "/");
                        if !id.is_empty() {
                            if let Err(e) = self.load_corpus(&[CorpusSource {
                                id: id.clone(),
                                weight: 1.0,
                                hash: None,
                            }]) {
                                tracing::warn!("Eager load failed for corpus {}: {}", id, e);
                            } else {
                                count_corpora += 1;
                            }
                        }
                    }
                }
            } else if rel_path == "config/keycodes.mpk.zst" {
                if let Err(e) = self.load_keycodes("keycodes") {
                    tracing::warn!("Eager load failed for keycodes: {}", e);
                }
            }
        }

        if count_files == 0 {
            error!("❌ Asset cache warming failed: 0 assets found in system library.");
            return Err("System library is empty".into());
        }

        info!(
            "✅ Cache Warmed: {} assets (including {} keyboards, {} corpora).",
            count_files, count_keyboards, count_corpora
        );
        Ok(())
    }

    pub fn invalidate_all(&self) {
        self.state.costs.invalidate_all();
        self.state.corpora.invalidate_all();
        self.state.keyboards.invalidate_all();
        self.state.keycodes.invalidate_all();
        self.state.hive_config.invalidate_all();
        self.state.app_config.invalidate_all();
    }

    pub fn get_manifest(&self) -> Option<Arc<ServerManifest>> {
        self.state.manifest.get("default")
    }

    pub fn get_file_content(&self, path: &str) -> Option<Bytes> {
        self.state.file_cache.get(path)
    }

    pub fn list_keyboards(&self) -> Vec<String> {
        let mut keys: Vec<String> = self
            .state
            .keyboards
            .iter()
            .map(|(k, _)| k.as_ref().clone())
            .collect();
        keys.sort();
        keys
    }

    pub fn list_corpora(&self) -> Vec<String> {
        let mut ids = Vec::new();
        for (key, _) in self.state.corpora.iter() {
            if let Ok(sources) = serde_json::from_str::<Vec<CorpusSource>>(key.as_ref()) {
                if sources.len() == 1 {
                    ids.push(sources[0].id.clone());
                }
            }
        }
        ids.sort();
        ids.dedup();
        ids
    }

    pub fn list_cost_matrices(&self) -> Vec<String> {
        let mut keys: Vec<String> = self
            .state
            .costs
            .iter()
            .map(|(k, _)| k.as_ref().clone())
            .collect();
        keys.sort();
        keys
    }

    pub fn load_hive_config(&self) -> Arc<HiveConfig> {
        if let Some(cached) = self.state.hive_config.get("default") {
            return cached;
        }

        let path = self.state.provider.root.join("system/config/hive.json");
        let config = if path.exists() {
            match keyforge_infra::read_to_string_limited(&path, MAX_INPUT_FILE_SIZE) {
                Ok(content) => serde_json::from_str(&content).unwrap_or_else(|e| {
                    warn!("Failed to parse hive.json: {}, using defaults", e);
                    HiveConfig::default()
                }),
                Err(e) => {
                    warn!("Failed to read hive.json: {}, using defaults", e);
                    HiveConfig::default()
                }
            }
        } else {
            HiveConfig::default()
        };

        let arc = Arc::new(config);
        self.state
            .hive_config
            .insert("default".to_string(), arc.clone());
        arc
    }

    pub fn load_app_config(&self) -> Arc<AppConfig> {
        if let Some(cached) = self.state.app_config.get("default") {
            return cached;
        }

        let path = self.state.provider.root.join("system/config/config.json");
        let config = if path.exists() {
            match keyforge_infra::read_to_string_limited(&path, MAX_INPUT_FILE_SIZE) {
                Ok(content) => serde_json::from_str(&content).unwrap_or_else(|e| {
                    warn!("Failed to parse config.json: {}, using defaults", e);
                    AppConfig::default()
                }),
                Err(e) => {
                    warn!("Failed to read config.json: {}, using defaults", e);
                    AppConfig::default()
                }
            }
        } else {
            AppConfig::default()
        };

        let arc = Arc::new(config);
        self.state
            .app_config
            .insert("default".to_string(), arc.clone());
        arc
    }
}

impl AssetLoader for GlobalAssetCache {
    fn load_keyboard(&self, name: &str) -> LoaderResult<KeyboardDefinition> {
        if let Some(cached) = self.state.keyboards.get(name) {
            return Ok(cached.as_ref().clone());
        }
        let def = self.state.provider.load_keyboard(name)?;
        self.state
            .keyboards
            .insert(name.to_string(), Arc::new(def.clone()));
        Ok(def)
    }

    fn load_corpus(&self, sources: &[CorpusSource]) -> LoaderResult<Corpus> {
        let mut sorted_sources = sources.to_vec();
        sorted_sources.sort_by(|a, b| a.id.cmp(&b.id));
        let key = serde_json::to_string(&sorted_sources)
            .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?;

        if let Some(cached) = self.state.corpora.get(&key) {
            return Ok(cached.as_ref().clone());
        }
        let corpus = self.state.provider.load_corpus(sources)?;
        self.state.corpora.insert(key, Arc::new(corpus.clone()));
        Ok(corpus)
    }

    fn load_cost_matrix(&self, filename: &str) -> LoaderResult<RawCostData> {
        if let Some(cached) = self.state.costs.get(filename) {
            return Ok(cached.as_ref().clone());
        }
        let data = self.state.provider.load_cost_matrix(filename)?;
        self.state
            .costs
            .insert(filename.to_string(), Arc::new(data.clone()));
        Ok(data)
    }

    fn load_keycodes(&self, filename: &str) -> LoaderResult<KeycodeRegistry> {
        if let Some(cached) = self.state.keycodes.get(filename) {
            return Ok(cached.as_ref().clone());
        }
        let reg = self.state.provider.load_keycodes(filename)?;
        self.state
            .keycodes
            .insert(filename.to_string(), Arc::new(reg.clone()));
        Ok(reg)
    }
}

