// libs/keyforge-infra/src/fs/init.rs
use crate::error::{InfraError, InfraResult};
use std::fs;
use std::path::{Path, PathBuf};
use tracing::{error, info};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InitMode {
    /// Strict Mode: Validates system assets exist. Auto-creates full user environment (Workspace + Runtime).
    Validate,
    /// Setup Mode: Creates skeleton structure for CLI (System + Workspace). Skips Runtime dirs.
    Provision,
}

const REQUIRED_ASSETS: &[&str] = &[
    "config/keycodes",
    "weights/default_costmatrix",
    "corpora/text/en_std/1grams",
];

const SYSTEM_DIRS: &[&str] = &[
    "system/config",
    "system/keyboards",
    "system/corpora/text/en_std",
    "system/weights",
    "system/benchmarks",
];

// Directories needed for Logic/Analysis (CLI + Server + Agent)
const USER_WORKSPACE_DIRS: &[&str] = &[
    "user/keyboards",
    "user/corpora",
    "user/weights",
    "user/config",
];

// Directories needed only for Execution/Persistence (Server + Agent)
const USER_RUNTIME_DIRS: &[&str] = &["user/queue", "user/agent_wal", "user/temp"];

fn check_asset_exists(system_root: &Path, rel_path: &str) -> bool {
    // Check for binary (.mpk.zst) OR json (.json)
    let bin_path = system_root.join(format!("{}.mpk.zst", rel_path));
    let json_path = system_root.join(format!("{}.json", rel_path));
    bin_path.exists() || json_path.exists()
}

fn ensure_dir(root: &Path, rel_path: &str, created: &mut Vec<PathBuf>) -> InfraResult<()> {
    let p = root.join(rel_path);
    if !p.exists() {
        fs::create_dir_all(&p).map_err(InfraError::Io)?;
        info!("   Created: {:?}", p);
        created.push(p);
    }
    Ok(())
}

pub fn initialize_workspace(root: &Path, mode: InitMode) -> InfraResult<Vec<PathBuf>> {
    let mut created = Vec::new();
    let system_root = root.join("system");

    match mode {
        InitMode::Validate => {
            // 1. Guard Dog: Check System Assets
            for asset in REQUIRED_ASSETS {
                if !check_asset_exists(&system_root, asset) {
                    let msg = format!("FATAL: Required system asset missing: {}", asset);
                    error!("{}", msg); // System Log
                    eprintln!("{}", msg); // Stderr
                    return Err(InfraError::Config(msg)); // Exception
                }
            }

            // 2. Ensure User Environment (Workspace + Runtime)
            // Server/Agent need queues and WALs to function.
            for d in USER_WORKSPACE_DIRS.iter().chain(USER_RUNTIME_DIRS.iter()) {
                ensure_dir(root, d, &mut created)?;
            }
        }
        InitMode::Provision => {
            // CLI Init: Create System skeletons + User Workspace.
            // No Runtime dirs needed for offline CLI analysis.
            for d in SYSTEM_DIRS.iter().chain(USER_WORKSPACE_DIRS.iter()) {
                ensure_dir(root, d, &mut created)?;
            }
        }
    }

    Ok(created)
}

use crate::error::{InfraError, InfraResult};
use std::io::{Read, Write};
use std::path::Path;
use tempfile::NamedTempFile;

pub fn atomic_write<P: AsRef<Path>, C: AsRef<[u8]>>(path: P, content: C) -> InfraResult<()> {
    let path = path.as_ref();
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).map_err(InfraError::Io)?;
    }
    let dir = path.parent().unwrap_or_else(|| Path::new("."));
    let mut temp_file = NamedTempFile::new_in(dir).map_err(InfraError::Io)?;
    temp_file
        .write_all(content.as_ref())
        .map_err(InfraError::Io)?;
    temp_file.flush().map_err(InfraError::Io)?;
    temp_file
        .persist(path)
        .map_err(|e| InfraError::Io(e.error))?;
    Ok(())
}

pub fn read_to_string_limited<P: AsRef<Path>>(path: P, limit_bytes: u64) -> InfraResult<String> {
    let path = path.as_ref();
    let file = std::fs::File::open(path).map_err(InfraError::Io)?;
    let mut reader = file.take(limit_bytes + 1);
    let mut buffer = String::new();
    reader.read_to_string(&mut buffer).map_err(InfraError::Io)?;

    if buffer.len() as u64 > limit_bytes {
        return Err(InfraError::Io(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            format!("File exceeds size limit of {} bytes", limit_bytes),
        )));
    }
    Ok(buffer)
}

use crate::error::{InfraError, InfraResult};
use std::collections::HashSet;
use std::fs;
use std::path::Path;

/// Helper to scan a specific sub-path and add stems to a set.
/// Extension is the target suffix (e.g., "mpk.zst").
fn scan_dir(
    root: &Path,
    sub_path: &str,
    extension: &str,
    results: &mut HashSet<String>,
) -> InfraResult<()> {
    let target = root.join(sub_path);
    if !target.exists() {
        return Ok(());
    }

    let entries = fs::read_dir(&target).map_err(InfraError::Io)?;
    for entry in entries.flatten() {
        let p = entry.path();
        if p.is_symlink() || !p.is_file() {
            continue;
        }

        let filename = match p.file_name().and_then(|s| s.to_str()) {
            Some(f) => f,
            None => continue,
        };

        if filename.ends_with(extension) {
            let stem = filename
                .strip_suffix(&format!(".{}", extension))
                .unwrap_or(filename);
            // Handle compound stems like "corne.mpk"
            let final_stem = stem.strip_suffix(".mpk").unwrap_or(stem);
            results.insert(final_stem.to_string());
        }
    }
    Ok(())
}

pub fn list_keyboards(root: &Path) -> InfraResult<Vec<String>> {
    let mut names = HashSet::new();
    // System: Binary Only - Updated to new structure
    scan_dir(root, "system/keyboards/models", "mpk.zst", &mut names)?;
    // User: Support JSON for development/customization
    scan_dir(root, "user/keyboards", "json", &mut names)?;

    let mut sorted: Vec<String> = names.into_iter().collect();
    sorted.sort();
    Ok(sorted)
}

pub fn list_corpora(root: &Path) -> InfraResult<Vec<String>> {
    let mut ids = HashSet::new();

    for (scope, ext) in [("system", "mpk.zst"), ("user", "json")] {
        let base = root.join(scope).join("corpora");
        if !base.exists() {
            continue;
        }

        let walker = walkdir::WalkDir::new(&base)
            .min_depth(1)
            .max_depth(3) // Extra depth for category/id
            .follow_links(true); // Follow symlinks

        for entry in walker.into_iter().filter_map(|e| e.ok()) {
            if entry.path_is_symlink() {
                continue;
            }
            let p = entry.path();

            // Check for the anchor file (1grams) in either binary or json format
            if p.file_name().and_then(|s| s.to_str()) == Some(&format!("1grams.{}", ext)) {
                if let Some(parent) = p.parent() {
                    if let Ok(relative) = parent.strip_prefix(&base) {
                        let id = relative.to_string_lossy().replace('\\', "/");
                        if !id.is_empty() {
                            ids.insert(id);
                        }
                    }
                }
            }
        }
    }

    let mut sorted: Vec<String> = ids.into_iter().collect();
    sorted.sort();
    Ok(sorted)
}

pub fn list_cost_matrices(root: &Path) -> InfraResult<Vec<String>> {
