    Ok(KeycodeRegistry::new(defs))
}

/// Aggressively sanitizes filenames to prevent traversal or shell issues.
/// Allowlist: Alphanumeric, dot, underscore, hyphen.
/// Replaces everything else with underscore.
pub fn sanitize_filename(name: &str) -> String {
    name.chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '.' || c == '-' || c == '_' {
                c
            } else {
                '_'
            }
        })
        .collect()
}

use keyforge_adapter::parsing::{parse_key, KeyAction};
use keyforge_model::Layout;
use keyforge_protocol::keycodes::KeycodeRegistry;
use moka::sync::Cache;
use once_cell::sync::Lazy;
use std::time::Duration;
use tracing::warn;

// LRU Cache for parsed layouts
static LAYOUT_CACHE: Lazy<Cache<String, Layout>> = Lazy::new(|| {
    Cache::builder()
        .max_capacity(10_000)
        .time_to_live(Duration::from_secs(300))
        .build()
});

pub fn parse_layout_string_permissive_cached(
    s: &str,
    size: usize,
    registry: &KeycodeRegistry,
) -> Result<Layout, String> {
    let key = format!("{}:{}", size, s);

    if let Some(layout) = LAYOUT_CACHE.get(&key) {
        return Ok(layout);
    }

    let mut keys = Vec::with_capacity(size);
    let tokens: Vec<&str> = s.split_whitespace().collect();

    for token in tokens {
        if keys.len() >= size {
            break;
        }

        let action = parse_key(token);

        // Map semantic actions to physical keycodes for scoring
        let code = match action {
            KeyAction::Simple(s) => registry.get_code(&s),
            // For ModTap/LayerTap, we score the base key (tap action)
            KeyAction::ModTap { key, .. } => registry.get_code(&key),
            KeyAction::LayerTap { key, .. } => registry.get_code(&key),
            // Layer actions map to their codes if present
            KeyAction::LayerMomentary(_) => registry.get_code("MO"),
            KeyAction::LayerToggle(_) => registry.get_code("TG"),
            KeyAction::LayerOn(_) => registry.get_code("TO"),
            // Sticky mods
            KeyAction::StickyMod(m) => registry
                .get_code(&format!("OSM_{}", m))
                .or(registry.get_code("OSM")),
            KeyAction::Transparent => registry.get_code("KC_TRNS"),
            KeyAction::NoOp => registry.get_code("KC_NO"),
            KeyAction::CapsWord => registry.get_code("CAPS_WORD"),
            KeyAction::Raw(s) => registry.get_code(&s),
        };

        if let Some(c) = code {
            keys.push(c);
        } else {
            // Graceful Fallback: Log error, insert KC_NO (0).
            warn!("Unknown key token: '{}'. Swapping in KC_NO (0).", token);
            keys.push(0);
        }
    }

    // Pad with KC_NO if under-sized
    while keys.len() < size {
        keys.push(0);
    }

    let layout = Layout::new(keys);
    LAYOUT_CACHE.insert(key, layout.clone());
    Ok(layout)
}

use keyforge_infra::listing;

#[test]
fn list_cost_matrices_includes_mpk_zst_and_excludes_non_cost_weights() {
    let dir = tempfile::tempdir().expect("tempdir");
    let root = dir.path();

    // Create expected directory structure
    std::fs::create_dir_all(root.join("system/weights")).unwrap();
    std::fs::create_dir_all(root.join("system/keyboards")).unwrap();
    std::fs::create_dir_all(root.join("user/weights")).unwrap();

    // A real cost matrix can be either json or mpk.zst
    std::fs::write(root.join("system/weights/cost_matrix.mpk.zst"), b"dummy").unwrap();
    std::fs::write(root.join("user/weights/custom.json"), b"{\"entries\":[]}").unwrap();

    // These are *not* cost matrices and must be excluded (by being in a different dir)
    std::fs::write(root.join("system/keyboards/ortho_split.mpk.zst"), b"dummy").unwrap();
    std::fs::write(root.join("system/keyboards/row_stagger.mpk.zst"), b"dummy").unwrap();
    std::fs::write(root.join("system/keyboards/testing.mpk.zst"), b"dummy").unwrap();

    let list = listing::list_cost_matrices(root).unwrap();

    assert!(list.contains(&"cost_matrix".to_string()));
    assert!(list.contains(&"custom".to_string()));
    assert!(!list.contains(&"ortho_split".to_string()));
    assert!(!list.contains(&"row_stagger".to_string()));
    assert!(!list.contains(&"testing".to_string()));
}

