    #[serde(default)]
    pub constraints: Vec<KeyConstraint>,

    /// Source for the cost matrix (biomechanical profile)
    #[serde(default)]
    pub cost_matrix: CostMatrixSource,

    /// Optional seed for deterministic reproducibility
    #[serde(default)]
    pub seed: Option<u64>,
}

impl Default for Project {
    fn default() -> Self {
        Self {
            meta: ProjectMeta::default(),
            keyboard: "ortho_30".to_string(),
            corpora: vec![CorpusSource::default()],
            weights: ScoringWeights::default(),
            params: SearchParams::default(),
            constraints: Vec::new(),
            cost_matrix: CostMatrixSource::default(),
            seed: None,
        }
    }
}

use serde::{Deserialize, Serialize};
use std::io::{Seek, SeekFrom, Write};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tempfile::NamedTempFile;
use tracing::{error, warn};

// 1MB Limit for session file
const MAX_SESSION_FILE_SIZE: u64 = 1024 * 1024;

#[derive(Serialize, Deserialize, Clone, Debug, Default)]
pub struct SessionSnapshot {
    pub keyboard: String,
    pub layout_name: String,
    pub layout_string: String,
    pub corpus: String,
    pub cost_matrix: String,
    pub timestamp: u64,
}

struct AutoSaveState {
    pending: Option<SessionSnapshot>,
    last_save: Instant,
}

pub struct AutoSaveService {
    path: PathBuf,
    state: Arc<Mutex<AutoSaveState>>,
}

impl AutoSaveService {
    pub fn new(root_path: PathBuf) -> Self {
        let path = root_path.join("session.json");

        Self {
            path,
            state: Arc::new(Mutex::new(AutoSaveState {
                pending: None,
                last_save: Instant::now(),
            })),
        }
    }

    pub async fn load(&self) -> Option<SessionSnapshot> {
        if !self.path.exists() {
            return None;
        }

        if let Ok(meta) = tokio::fs::metadata(&self.path).await {
            if meta.len() > MAX_SESSION_FILE_SIZE {
                warn!("Session file too large ({} bytes), ignoring.", meta.len());
                return None;
            }
        }

        match tokio::fs::read_to_string(&self.path).await {
            Ok(content) => match serde_json::from_str(&content) {
                Ok(snap) => Some(snap),
                Err(e) => {
                    warn!("Failed to parse session.json: {}", e);
                    None
                }
            },
            Err(e) => {
                warn!("Failed to read session.json: {}", e);
                None
            }
        }
    }

    pub async fn schedule_save(&self, snapshot: SessionSnapshot) {
        let should_flush = {
            let mut state = self.state.lock().unwrap();
            state.pending = Some(snapshot);
            // Debounce: only flush if 2 seconds passed since last save
            state.last_save.elapsed() > Duration::from_secs(2)
        };

        if should_flush {
            self.flush(false).await;
        }
    }

    /// Flushes pending changes to disk.
    /// If `force` is true, ignores the debounce timer.
    pub async fn flush(&self, force: bool) {
        let snapshot_to_save = {
            let mut state = self.state.lock().unwrap();
            if state.pending.is_none() {
                return;
            }

            if !force && state.last_save.elapsed() < Duration::from_secs(2) {
                return;
            }

            state.last_save = Instant::now();
            state.pending.take() // Take ownership to save
        };

        if let Some(snap) = snapshot_to_save {
            let path = self.path.clone();

            let result = tokio::task::spawn_blocking(move || -> std::io::Result<()> {
                let json = serde_json::to_string_pretty(&snap)
                    .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;

                let dir = path.parent().unwrap_or_else(|| std::path::Path::new("."));

                // Create temp file in the same directory to attempt atomic rename
                let mut temp_file = NamedTempFile::new_in(dir)?;
                temp_file.write_all(json.as_bytes())?;
                temp_file.flush()?;

                // Atomic persist with cross-device fallback
                match temp_file.persist(&path) {
                    Ok(_) => Ok(()),
                    Err(e) => {
                        // If atomic rename fails (e.g. cross-device link), copy manually
                        let mut source = e.file;
                        source.seek(SeekFrom::Start(0))?;
                        let mut dest = std::fs::File::create(&path)?;
                        std::io::copy(&mut source, &mut dest)?;
                        // Temp file is deleted when source goes out of scope (if not persisted)
                        Ok(())
                    }
                }
            })
            .await;

            match result {
                Ok(Ok(_)) => {}
                Ok(Err(e)) => error!("Failed to save session: {}", e),
                Err(e) => error!("Join error during save: {}", e),
            }
        }
    }
}

#![allow(clippy::unnecessary_map_or)]
use keyforge_model::Layout;
use std::collections::HashMap;
use std::sync::OnceLock;

pub struct LayoutIdentity {
    pub name: String,
    pub similarity: f32, // 0.0 to 1.0
    pub distance: usize, // Hamming distance
}

pub struct Fingerprinter;

static STANDARDS: OnceLock<HashMap<String, Vec<u16>>> = OnceLock::new();

impl Default for Fingerprinter {
    fn default() -> Self {
        Self
    }
}

impl Fingerprinter {
    fn get_standards() -> &'static HashMap<String, Vec<u16>> {
        STANDARDS.get_or_init(|| {
            let mut standards = HashMap::new();
            standards.insert("Qwerty".into(), to_codes("qwertyuiopasdfghjkl;zxcvbnm,./"));
            standards.insert("Colemak".into(), to_codes("qwfpgjluy;arstdhneiozxcvbkm,./"));
            standards.insert("Dvorak".into(), to_codes("',.pyfgcrlaoeuidhtns;qjkxbmwvz"));
            standards
        })
    }

    pub fn identify(&self, layout: &Layout) -> Option<LayoutIdentity> {
        let standards = Self::get_standards();
        let mut best: Option<LayoutIdentity> = None;

        for (name, std_keys) in standards {
            let len = std_keys.len().min(layout.keys.len());
            if len == 0 {
                continue;
            }

            let mut matches = 0;
            for (i, &std_code) in std_keys.iter().enumerate().take(len) {
                if layout.keys[i] == std_code {
                    matches += 1;
                }
            }

            let similarity = matches as f32 / len as f32;
            let distance = len - matches;

            if best.as_ref().map_or(true, |b| similarity > b.similarity) {
                best = Some(LayoutIdentity {
                    name: name.clone(),
                    similarity,
                    distance,
                });
            }
        }

        if let Some(b) = best {
            if b.similarity > 0.2 {
                return Some(b);
            }
        }
        None
    }
}

fn to_codes(s: &str) -> Vec<u16> {
    s.chars().map(|c| c as u16).collect()
}

use crate::kernel::compute::{calculate_swap_delta, score_layout};
use crate::kernel::EngineContext;
use keyforge_model::{Layout, SwapSuggestion};
use keyforge_protocol::constants::SCORE_SCALE;

pub fn suggest_swaps(ctx: &EngineContext, layout: &Layout) -> Vec<SwapSuggestion> {
    let mut pos_map = vec![65535u16; 65536];
    let current_score = score_layout(ctx, &layout.keys, &mut pos_map);

    if current_score <= 0 {
        return vec![];
    }

    let mut suggestions = Vec::new();
    let len = layout.keys.len();

    for i in 0..len {
        for j in (i + 1)..len {
            if layout.keys[i] == layout.keys[j] {
                continue;
            }

            let delta = calculate_swap_delta(ctx, &layout.keys, &pos_map, i, j);

            if delta < 0 {
                // P2 FIX: Updated scaling factor
                let improvement = delta.abs() as f32 / SCORE_SCALE;
                let current_f32 = current_score as f32 / SCORE_SCALE;

                let pct = if current_f32 > f32::EPSILON {
                    (improvement / current_f32) * 100.0
                } else {
                    0.0
                };

                if pct > 0.1 && pct.is_finite() {
                    suggestions.push(SwapSuggestion {
                        index_a: i,
                        index_b: j,
                        key_a: format!("{}", i),
                        key_b: format!("{}", j),
                        score_delta: improvement,
                        improvement_pct: pct,
                    });
                }
            }
        }
    }

    suggestions.sort_by(|a, b| b.improvement_pct.total_cmp(&a.improvement_pct));
    suggestions.truncate(5);
    suggestions
}

use super::mechanics::calculate_pair_cost;
use super::EngineContext;
use keyforge_model::{Corpus, Keyboard, Rubric};
use keyforge_protocol::constants::SCORE_SCALE;
use tracing::instrument;

pub struct Compiler;

impl Compiler {
    #[instrument(skip_all)]
    pub fn compile(
        kb: &Keyboard,
        corpus: &Corpus,
        rubric: &Rubric,
        overrides: &[(usize, usize, f32)],
    ) -> EngineContext {
        let key_count = kb.count();

        let mut hands = Vec::with_capacity(key_count);
        let mut fingers = Vec::with_capacity(key_count);
        let mut rows = Vec::with_capacity(key_count);
        let mut cols = Vec::with_capacity(key_count);

        for k in &kb.keys {
            hands.push(k.hand);
            fingers.push(k.finger);
            rows.push(k.row);
            cols.push(k.col);
        }

        let mut cost_matrix = vec![0i64; key_count * key_count];

        for i in 0..key_count {
            for j in 0..key_count {
                let cost = calculate_pair_cost(kb, rubric, i, j);
                cost_matrix[i * key_count + j] = safe_float_to_int(cost);
            }
        }

        for &(i, j, cost) in overrides {
            if i < key_count && j < key_count {
                cost_matrix[i * key_count + j] = safe_float_to_int(cost);
            }
        }

        // --- Bigrams ---
        let (bigram_starts, bigram_others, bigram_freqs) = flatten_bigrams(&corpus.bigrams);
        let (bigram_rev_starts, bigram_rev_others, bigram_rev_freqs) =
            flatten_bigrams_rev(&corpus.bigrams);

        // --- Trigrams (Adaptive Pruning) ---
        let pruned_trigrams = prune_trigrams(
            corpus.trigrams.clone(),
            rubric.trigram_coverage,
            rubric.trigram_limit,
        );

        let (trigram_starts, trigram_others1, trigram_others2, trigram_freqs) =
            flatten_trigrams_start(&pruned_trigrams);

        let (trigram_mid_starts, trigram_mid_others1, trigram_mid_others2, trigram_mid_freqs) =
            flatten_trigrams_mid(&pruned_trigrams);

        let (trigram_end_starts, trigram_end_others1, trigram_end_others2, trigram_end_freqs) =
            flatten_trigrams_end(&pruned_trigrams);

        // Character frequencies from corpus
        let char_freqs = corpus.char_freqs.clone();

        EngineContext {
            key_count,
            hands,
            fingers,
            rows,
            cols,
            cost_matrix,
            char_freqs,

            bigram_starts,
            bigram_others,
            bigram_freqs,
            bigram_rev_starts,
            bigram_rev_others,
            bigram_rev_freqs,

            trigram_starts,
            trigram_others1,
            trigram_others2,
            trigram_freqs,
            trigram_mid_starts,
            trigram_mid_others1,
            trigram_mid_others2,
            trigram_mid_freqs,
            trigram_end_starts,
            trigram_end_others1,
            trigram_end_others2,
            trigram_end_freqs,

            penalty_redirect: safe_float_to_int(rubric.redirect),
            penalty_skip: 0,
            bonus_roll: safe_float_to_int(rubric.roll_bonus),
        }
    }
}

fn safe_float_to_int(val: f32) -> i64 {
    if val.is_nan() {
        return 0;
    }
    if val.is_infinite() {
        return if val.is_sign_positive() {
            i64::MAX
        } else {
            i64::MIN
        };
    }

    let scaled = val * SCORE_SCALE;

    if scaled >= i64::MAX as f32 {
        return i64::MAX;
    }
    if scaled <= i64::MIN as f32 {
        return i64::MIN;
    }

    scaled as i64
}

fn flatten_bigrams(source: &[(u16, u16, u32)]) -> (Vec<usize>, Vec<u16>, Vec<u32>) {
    let mut buckets = vec![Vec::new(); 65536];
    for &(c1, c2, freq) in source {
        buckets[c1 as usize].push((c2, freq));
    }
    flatten_buckets(buckets)
}

fn flatten_bigrams_rev(source: &[(u16, u16, u32)]) -> (Vec<usize>, Vec<u16>, Vec<u32>) {
    let mut buckets = vec![Vec::new(); 65536];
    for &(c1, c2, freq) in source {
        buckets[c2 as usize].push((c1, freq));
    }
    flatten_buckets(buckets)
}

fn prune_trigrams(
    mut source: Vec<(u16, u16, u16, u32)>,
    coverage: f32,
    limit: usize,
) -> Vec<(u16, u16, u16, u32)> {
    source.sort_unstable_by(|a, b| {
        b.3.cmp(&a.3)
            .then_with(|| a.0.cmp(&b.0))
            .then_with(|| a.1.cmp(&b.1))
            .then_with(|| a.2.cmp(&b.2))
    });

    let total_freq: u64 = source.iter().map(|x| x.3 as u64).sum();
    let target = (total_freq as f64 * coverage as f64) as u64;
    let mut acc = 0;
    let mut cutoff = source.len();

    for (i, item) in source.iter().enumerate() {
        acc += item.3 as u64;
        if acc >= target {
            cutoff = i + 1;
            break;
        }
    }

    if cutoff > limit {
        cutoff = limit;
    }

    source.truncate(cutoff);
    source
}

fn flatten_trigrams_start(
    source: &[(u16, u16, u16, u32)],
) -> (Vec<usize>, Vec<u16>, Vec<u16>, Vec<u32>) {
    let mut buckets = vec![Vec::new(); 65536];
    for &(c1, c2, c3, freq) in source {
        buckets[c1 as usize].push((c2, c3, freq));
    }
    flatten_buckets_tri(buckets)
}

fn flatten_trigrams_mid(
    source: &[(u16, u16, u16, u32)],
) -> (Vec<usize>, Vec<u16>, Vec<u16>, Vec<u32>) {
    let mut buckets = vec![Vec::new(); 65536];
    for &(c1, c2, c3, freq) in source {
        buckets[c2 as usize].push((c1, c3, freq));
    }
    flatten_buckets_tri(buckets)
}

fn flatten_trigrams_end(
    source: &[(u16, u16, u16, u32)],
) -> (Vec<usize>, Vec<u16>, Vec<u16>, Vec<u32>) {
    let mut buckets = vec![Vec::new(); 65536];
    for &(c1, c2, c3, freq) in source {
        buckets[c3 as usize].push((c1, c2, freq));
    }
    flatten_buckets_tri(buckets)
}

fn flatten_buckets(buckets: Vec<Vec<(u16, u32)>>) -> (Vec<usize>, Vec<u16>, Vec<u32>) {
    let mut starts = vec![0; 65537];
    let mut others = Vec::new();
    let mut freqs = Vec::new();
    let mut offset = 0;

    for i in 0..65536 {
        starts[i] = offset;
        for (o, f) in &buckets[i] {
            others.push(*o);
            freqs.push(*f);
        }
        offset += buckets[i].len();
    }
    starts[65536] = offset;
    (starts, others, freqs)
}

fn flatten_buckets_tri(
    buckets: Vec<Vec<(u16, u16, u32)>>,
) -> (Vec<usize>, Vec<u16>, Vec<u16>, Vec<u32>) {
    let mut starts = vec![0; 65537];
    let mut o1 = Vec::new();
    let mut o2 = Vec::new();
    let mut freqs = Vec::new();
    let mut offset = 0;

    for i in 0..65536 {
        starts[i] = offset;
        for (a, b, f) in &buckets[i] {
            o1.push(*a);
            o2.push(*b);
            freqs.push(*f);
        }
        offset += buckets[i].len();
    }
    starts[65536] = offset;
    (starts, o1, o2, freqs)
}

use super::EngineContext;
use keyforge_model::{AnalysisReport, MetricViolation};
use keyforge_protocol::constants::SCORE_SCALE;
use tracing::instrument;

/// Scores a layout.
pub fn score_layout(ctx: &EngineContext, layout: &[u16], pos_map: &mut [u16]) -> i64 {
    let mut total_score = 0i64;

    pos_map.fill(65535);

    let limit = layout.len().min(ctx.key_count);

    for (i, &code) in layout.iter().enumerate().take(limit) {
        if (code as usize) < pos_map.len() {
            pos_map[code as usize] = i as u16;
        }
    }

    // Bigrams
    for (c1, &p1) in pos_map.iter().enumerate() {
        if p1 == 65535 {
            continue;
        }
        let start = ctx.bigram_starts[c1];
        let end = ctx.bigram_starts[c1 + 1];
        for k in start..end {
            let c2 = ctx.bigram_others[k] as usize;
            let p2 = pos_map[c2];
            if p2 != 65535 {
                let idx = (p1 as usize) * ctx.key_count + (p2 as usize);
                if let Some(cost) = ctx.cost_matrix.get(idx) {
                    total_score = total_score
                        .checked_add(cost.saturating_mul(ctx.bigram_freqs[k] as i64))
                        .unwrap_or(i64::MAX);
                }
            }
        }
    }

    // Trigrams
    for (c1, &p1) in pos_map.iter().enumerate() {
        if p1 == 65535 {
            continue;
        }
        let start = ctx.trigram_starts[c1];
        let end = ctx.trigram_starts[c1 + 1];
        for k in start..end {
            let c2 = ctx.trigram_others1[k] as usize;
            let c3 = ctx.trigram_others2[k] as usize;

            let p2 = pos_map[c2];
            let p3 = pos_map[c3];

            if p2 != 65535 && p3 != 65535 {
                let cost = calculate_flow_cost(ctx, p1 as usize, p2 as usize, p3 as usize);
                if cost != 0 {
                    total_score = total_score
                        .checked_add(cost.saturating_mul(ctx.trigram_freqs[k] as i64))
                        .unwrap_or(i64::MAX);
                }
            }
        }
    }
    total_score
}

pub fn calculate_swap_delta(
    ctx: &EngineContext,
    layout: &[u16],
    pos_map: &[u16],
    idx_a: usize,
    idx_b: usize,
) -> i64 {
    if idx_a >= layout.len() || idx_b >= layout.len() {
        return 0;
    }
    if idx_a >= ctx.key_count || idx_b >= ctx.key_count {
        return 0;
    }

    let code_a = layout[idx_a] as usize;
    let code_b = layout[idx_b] as usize;
    let mut delta = 0i64;

    let get_pos = |c: usize, p_map: &[u16]| -> usize {
        if c == code_a {
            idx_a
        } else if c == code_b {
            idx_b
        } else {
            p_map[c] as usize
        }
    };

    let get_swapped_pos = |c: usize, p_map: &[u16]| -> usize {
        if c == code_a {
            idx_b
        } else if c == code_b {
            idx_a
        } else {
            p_map[c] as usize
        }
    };

    if code_a < 65536 {
        delta = delta.saturating_add(calc_key_delta(
            ctx,
            code_a,
            None,
            pos_map,
            &get_pos,
            &get_swapped_pos,
        ));
    }
    if code_b < 65536 {
        delta = delta.saturating_add(calc_key_delta(
            ctx,
            code_b,
            Some(code_a),
            pos_map,
            &get_pos,
            &get_swapped_pos,
        ));
    }
    delta
}

#[inline(never)]
fn calc_key_delta<F1, F2>(
    ctx: &EngineContext,
    c_target: usize,
    c_skip: Option<usize>,
    pos_map: &[u16],
    get_old: &F1,
    get_new: &F2,
) -> i64
where
    F1: Fn(usize, &[u16]) -> usize,
    F2: Fn(usize, &[u16]) -> usize,
{
    let mut d = 0i64;
    d = d.saturating_add(calc_bigrams_delta(ctx, c_target, c_skip, pos_map, get_old, get_new));
    d = d.saturating_add(calc_trigrams_delta(ctx, c_target, c_skip, pos_map, get_old, get_new));
    d
}


#[inline(never)]
fn calc_bigrams_delta(
    ctx: &EngineContext,
    c_target: usize,
    c_skip: Option<usize>,
    pos_map: &[u16],
    get_old: &dyn Fn(usize, &[u16]) -> usize,
    get_new: &dyn Fn(usize, &[u16]) -> usize,
) -> i64 {
    let mut d = 0i64;
    // Bigrams Start
    let start = ctx.bigram_starts[c_target];
    let end = ctx.bigram_starts[c_target + 1];
    for k in start..end {
        let c_other = ctx.bigram_others[k] as usize;
        if Some(c_other) == c_skip { continue; }
        if pos_map[c_other] != 65535 {
            let p1_old = get_old(c_target, pos_map);
            let p2_old = get_old(c_other, pos_map);
            if p1_old < ctx.key_count && p2_old < ctx.key_count {
                let cost_old = ctx.cost_matrix[p1_old * ctx.key_count + p2_old];
                let p1_new = get_new(c_target, pos_map);
                let p2_new = get_new(c_other, pos_map);
                if p1_new < ctx.key_count && p2_new < ctx.key_count {
                    let cost_new = ctx.cost_matrix[p1_new * ctx.key_count + p2_new];
                    d = d.saturating_add(cost_new.saturating_sub(cost_old).saturating_mul(ctx.bigram_freqs[k] as i64));
                }
            }
        }
    }
    // Bigrams End
    let start = ctx.bigram_rev_starts[c_target];
    let end = ctx.bigram_rev_starts[c_target + 1];
    for k in start..end {
        let c_other = ctx.bigram_rev_others[k] as usize;
        if c_other != c_target && Some(c_other) != c_skip {
            if c_other < 65536 && pos_map[c_other] != 65535 {
                let p1_old = get_old(c_other, pos_map);
                let p2_old = get_old(c_target, pos_map);
                if p1_old < ctx.key_count && p2_old < ctx.key_count {
                    let cost_old = ctx.cost_matrix[p1_old * ctx.key_count + p2_old];
                    let p1_new = get_new(c_other, pos_map);
                    let p2_new = get_new(c_target, pos_map);
                    if p1_new < ctx.key_count && p2_new < ctx.key_count {
                        let cost_new = ctx.cost_matrix[p1_new * ctx.key_count + p2_new];
                        d = d.saturating_add(cost_new.saturating_sub(cost_old).saturating_mul(ctx.bigram_rev_freqs[k] as i64));
                    }
                }
            }
        }
    }
    d
}

#[inline(never)]
fn calc_trigrams_delta(
    ctx: &EngineContext,
    c_target: usize,
    c_skip: Option<usize>,
    pos_map: &[u16],
    get_old: &dyn Fn(usize, &[u16]) -> usize,
    get_new: &dyn Fn(usize, &[u16]) -> usize,
) -> i64 {
    let mut d = 0i64;
    // Trigrams Start
    let start = ctx.trigram_starts[c_target];
    let end = ctx.trigram_starts[c_target + 1];
    for k in start..end {
        let c2 = ctx.trigram_others1[k] as usize;
        let c3 = ctx.trigram_others2[k] as usize;
        if Some(c2) == c_skip || Some(c3) == c_skip { continue; }
        if pos_map[c2] != 65535 && pos_map[c3] != 65535 {
            let p1_old = get_old(c_target, pos_map);
            let p2_old = get_old(c2, pos_map);
            let p3_old = get_old(c3, pos_map);
            let cost_old = calculate_flow_cost(ctx, p1_old, p2_old, p3_old);
            let p1_new = get_new(c_target, pos_map);
            let p2_new = get_new(c2, pos_map);
            let p3_new = get_new(c3, pos_map);
            let cost_new = calculate_flow_cost(ctx, p1_new, p2_new, p3_new);
            d = d.saturating_add(cost_new.saturating_sub(cost_old).saturating_mul(ctx.trigram_freqs[k] as i64));
        }
    }
    // Trigrams Mid
    let start = ctx.trigram_mid_starts[c_target];
    let end = ctx.trigram_mid_starts[c_target + 1];
    for k in start..end {
        let c1 = ctx.trigram_mid_others1[k] as usize;
        let c3 = ctx.trigram_mid_others2[k] as usize;
        if c1 != c_target && Some(c1) != c_skip && Some(c3) != c_skip {
            if c1 < 65536 && pos_map[c1] != 65535 && pos_map[c3] != 65535 {
                let p1_old = get_old(c1, pos_map);
                let p2_old = get_old(c_target, pos_map);
                let p3_old = get_old(c3, pos_map);
                let cost_old = calculate_flow_cost(ctx, p1_old, p2_old, p3_old);
                let p1_new = get_new(c1, pos_map);
                let p2_new = get_new(c_target, pos_map);
                let p3_new = get_new(c3, pos_map);
                let cost_new = calculate_flow_cost(ctx, p1_new, p2_new, p3_new);
                d = d.saturating_add(cost_new.saturating_sub(cost_old).saturating_mul(ctx.trigram_mid_freqs[k] as i64));
            }
        }
    }
    // Trigrams End
    let start = ctx.trigram_end_starts[c_target];
    let end = ctx.trigram_end_starts[c_target + 1];
    for k in start..end {
        let c1 = ctx.trigram_end_others1[k] as usize;
        let c2 = ctx.trigram_end_others2[k] as usize;
        if c1 != c_target && c2 != c_target && Some(c1) != c_skip && Some(c2) != c_skip {
            if c1 < 65536 && pos_map[c1] != 65535 && pos_map[c2] != 65535 {
                let p1_old = get_old(c1, pos_map);
                let p2_old = get_old(c2, pos_map);
                let p3_old = get_old(c_target, pos_map);
                let cost_old = calculate_flow_cost(ctx, p1_old, p2_old, p3_old);
                let p1_new = get_new(c1, pos_map);
                let p2_new = get_new(c2, pos_map);
                let p3_new = get_new(c_target, pos_map);
                let cost_new = calculate_flow_cost(ctx, p1_new, p2_new, p3_new);
                d = d.saturating_add(cost_new.saturating_sub(cost_old).saturating_mul(ctx.trigram_end_freqs[k] as i64));
            }
        }
    }
    d
}



#[inline(always)]
fn calculate_flow_cost(ctx: &EngineContext, p1: usize, p2: usize, p3: usize) -> i64 {
    if p1 >= ctx.key_count || p2 >= ctx.key_count || p3 >= ctx.key_count {
        return 0;
    }
    let h1 = ctx.hands[p1];
    let h2 = ctx.hands[p2];
    let h3 = ctx.hands[p3];
    if h1 != h2 || h2 != h3 {
        return 0;
    }
    let f1 = ctx.fingers[p1] as i8;
    let f2 = ctx.fingers[p2] as i8;
    let f3 = ctx.fingers[p3] as i8;
    if f1 == f3 && f1 != f2 {
        return ctx.penalty_redirect;
    }
    let dir1 = f2 - f1;
    let dir2 = f3 - f2;
    if dir1 == 0 || dir2 == 0 {
        return 0;
    }
    if dir1.signum() != dir2.signum() {
        return ctx.penalty_redirect;
    }
    if dir1 < 0 {
        return -ctx.bonus_roll;
    }
    0
}

#[instrument(skip_all)]
pub fn analyze_layout(ctx: &EngineContext, layout: &[u16]) -> AnalysisReport {
    let mut report = AnalysisReport::default();
    let mut pos_map = vec![65535u16; 65536];
    let mut heatmap = vec![0.0; ctx.key_count]; // Initialize Heatmap

    let limit = layout.len().min(ctx.key_count);
    for (i, &code) in layout.iter().enumerate().take(limit) {
        pos_map[code as usize] = i as u16;
    }

    let mut total_bigrams = 0.0;
    let mut left_hand_load = 0.0;
    let mut total_load = 0.0;

    let mut sfbs = Vec::new();
    let mut scissors = Vec::new();
    let mut redirs = Vec::new();

    // 1. Monogram Stats (Heatmap & Balance)
    for (c, &p) in pos_map.iter().enumerate() {
        if p == 65535 {
            continue;
        }
        let freq = ctx.char_freqs[c] as f32;
        if freq > 0.0 {
            total_load += freq;
            let idx = p as usize;
            if idx < ctx.key_count {
                heatmap[idx] += freq; // Populate Heatmap
                if ctx.hands[idx] == 0 {
                    left_hand_load += freq;
                }
            }
        }
    }

    // 2. Bigram Stats
    for (c1, &p1) in pos_map.iter().enumerate() {
        if p1 == 65535 {
            continue;
        }
        let start = ctx.bigram_starts[c1];
        let end = ctx.bigram_starts[c1 + 1];

        for k in start..end {
            let c2 = ctx.bigram_others[k] as usize;
            let p2 = pos_map[c2];
            if p2 != 65535 {
                let freq = ctx.bigram_freqs[k] as f32;
                total_bigrams += freq;
                let idx1 = p1 as usize;
                let idx2 = p2 as usize;
// ...

                if idx1 < ctx.key_count && idx2 < ctx.key_count {
                    // Distance
                    let cost = ctx.cost_matrix[idx1 * ctx.key_count + idx2] as f32;
                    report.distance += cost * freq;

                    // SFB
                    if ctx.fingers[idx1] == ctx.fingers[idx2] && ctx.hands[idx1] == ctx.hands[idx2]
                    {
                        report.sfb_total += freq;
                        sfbs.push(MetricViolation {
                            keys: format!("{} {}", c1 as u8 as char, c2 as u8 as char),
                            score: 1.0,
                            freq,
                        });
                    }

                    // Scissor
                    let f1 = ctx.fingers[idx1] as i8;
                    let f2 = ctx.fingers[idx2] as i8;
                    let r1 = ctx.rows[idx1];
                    let r2 = ctx.rows[idx2];
                    if ctx.hands[idx1] == ctx.hands[idx2]
                        && (f1 - f2).abs() == 1
                        && (r1 - r2).abs() >= 2
                    {
                        report.scissors += freq;
                        scissors.push(MetricViolation {
                            keys: format!("{} {}", c1 as u8 as char, c2 as u8 as char),
                            score: 1.0,
                            freq,
                        });
                    }
                }
            }
        }
    }

    // 3. Trigram Stats (Redirects/Rolls)
    for (c1, &p1) in pos_map.iter().enumerate() {
        if p1 == 65535 {
            continue;
        }
        let start = ctx.trigram_starts[c1];
        let end = ctx.trigram_starts[c1 + 1];
        for k in start..end {
            let c2 = ctx.trigram_others1[k] as usize;
            let c3 = ctx.trigram_others2[k] as usize;
            let p2 = pos_map[c2];
            let p3 = pos_map[c3];

            if p2 != 65535 && p3 != 65535 {
// ...
                let cost = calculate_flow_cost(ctx, p1 as usize, p2 as usize, p3 as usize);
                let freq = ctx.trigram_freqs[k] as f32;

                if cost == ctx.penalty_redirect {
                    report.redirects += freq;
                    redirs.push(MetricViolation {
                        keys: format!(
                            "{}{}{}",
                            c1 as u8 as char, c2 as u8 as char, c3 as u8 as char
                        ),
                        score: 1.0,
                        freq,
                    });
                } else if cost == -ctx.bonus_roll {
                    report.rolls += freq;
                }
            }
        }
    }

    // Finalize
    let sort_violations = |v: &mut Vec<MetricViolation>| {
        v.sort_by(|a, b| b.freq.partial_cmp(&a.freq).unwrap());
        v.truncate(10);
    };

    sort_violations(&mut sfbs);
    sort_violations(&mut scissors);
    sort_violations(&mut redirs);

    report.top_sfbs = sfbs;
    report.top_scissors = scissors;
    report.top_redirs = redirs;
    report.heatmap = heatmap; // Assign Heatmap

    let mut scratch = vec![65535u16; 65536];
    report.score = score_layout(ctx, layout, &mut scratch) as f32 / SCORE_SCALE;
    report.distance /= SCORE_SCALE; // Normalize distance

    if total_bigrams > 0.0 {
        report.sfb_ratio = report.sfb_total / total_bigrams;
    }
    if total_load > 0.0 {
        let left_ratio = left_hand_load / total_load;
        report.hand_balance = (left_ratio - 0.5) * -2.0; // -1 (Left) to 1 (Right)
    }
    report
}

use keyforge_model::{Keyboard, Rubric};

/// Calculates the static cost of a transition between two keys.
/// Uses squared distance to penalize long jumps more heavily and avoid sqrt cost.
pub fn calculate_pair_cost(kb: &Keyboard, rubric: &Rubric, i: usize, j: usize) -> f32 {
    if i == j {
        return 0.0;
    }

    let k1 = &kb.keys[i];
    let k2 = &kb.keys[j];

    // 1. Squared Distance (Quadratic Penalty)
    // We calculate (Distance^2 * Weight) so that negative weights act as bonuses.
    let dx = (k1.x - k2.x).abs();
    let dy = (k1.y - k2.y).abs();
    let dist_sq = (dx * dx * rubric.travel_lat) + (dy * dy * rubric.travel_vert);

    let mut cost = dist_sq;

    // If different hands, we only charge distance (no biomechanical penalty)
    if k1.hand != k2.hand {
        return cost;
    }

    // 2. Same Finger Bigram (SFB)
    if k1.finger == k2.finger {
        let col_diff = (k1.col - k2.col).abs();
        if col_diff == 1 {
            cost += rubric.sfb_lateral;
        } else {
            cost += rubric.sfb_base;
        }
        return cost;
    }

    // 3. Scissors
    let finger_diff = (k1.finger as i8 - k2.finger as i8).abs();
    let row_diff = (k1.row - k2.row).abs();

    if finger_diff == 1 && row_diff >= 2 {
        // P2 FIX: Removed hardcoded * 10.0 multiplier.
        // Now relies purely on the configured finger effort weight.
        cost += rubric.finger_effort[k1.finger as usize];
    }

    // 4. Lateral Stretch
    if row_diff == 0 && finger_diff == 1 {
        let col_dist = (k1.col - k2.col).abs();
        if col_dist > 1 {
            cost += rubric.sfb_lateral;
        }
    }

    cost
}

