use keyforge_model::{Corpus, Keyboard, Layout, Rubric};
use keyforge_protocol::constants::SCORE_SCALE;

/// A deterministic scorer that uses pure integer arithmetic.
/// This is slower than the main engine but guarantees identical results across platforms.
/// It should ONLY be used for final verification before submission or storage.
pub struct DeterministicScorer;

impl DeterministicScorer {
    pub fn score(keyboard: &Keyboard, corpus: &Corpus, rubric: &Rubric, layout: &Layout) -> f32 {
        let mut total_score: i64 = 0;

        // 1. Map Layout to Positions
        // pos_map[keycode] = physical_index
        let mut pos_map = vec![65535u16; 65536];
        for (i, &code) in layout.keys.iter().enumerate() {
            if (code as usize) < pos_map.len() {
                pos_map[code as usize] = i as u16;
            }
        }

        // 2. Convert Rubric to Fixed Point
        let fp_rubric = FixedPointRubric {
            travel_lat: to_fixed(rubric.travel_lat),
            travel_vert: to_fixed(rubric.travel_vert),
            sfb_base: to_fixed(rubric.sfb_base),
            sfb_lateral: to_fixed(rubric.sfb_lateral),
            finger_effort: [
                to_fixed(rubric.finger_effort[0]),
                to_fixed(rubric.finger_effort[1]),
                to_fixed(rubric.finger_effort[2]),
                to_fixed(rubric.finger_effort[3]),
                to_fixed(rubric.finger_effort[4]),
            ],
            redirect: to_fixed(rubric.redirect),
            roll_bonus: to_fixed(rubric.roll_bonus),
        };

        // 3. Convert Keyboard to Fixed Point
        let fp_keys: Vec<FixedPointKey> = keyboard
            .keys
            .iter()
            .map(|k| FixedPointKey {
                x: to_fixed(k.x),
                y: to_fixed(k.y),
                hand: k.hand,
                finger: k.finger,
                row: k.row,
                col: k.col,
            })
            .collect();

        // 4. Score Bigrams
        for &(c1, c2, freq) in &corpus.bigrams {
            let p1 = pos_map[c1 as usize];
            let p2 = pos_map[c2 as usize];

            if p1 != 65535 && p2 != 65535 {
                let k1 = &fp_keys[p1 as usize];
                let k2 = &fp_keys[p2 as usize];

                let cost = calculate_pair_cost_int(k1, k2, &fp_rubric);
                total_score = total_score.saturating_add(cost.saturating_mul(freq as i64));
            }
        }

        // 5. Score Trigrams
        // Note: We apply the same pruning logic as the main engine implicitly
        // by iterating the corpus provided. The corpus itself should be the pruned version if needed.
        for &(c1, c2, c3, freq) in &corpus.trigrams {
            let p1 = pos_map[c1 as usize];
            let p2 = pos_map[c2 as usize];
            let p3 = pos_map[c3 as usize];

            if p1 != 65535 && p2 != 65535 && p3 != 65535 {
                let k1 = &fp_keys[p1 as usize];
                let k2 = &fp_keys[p2 as usize];
                let k3 = &fp_keys[p3 as usize];

                let cost = calculate_flow_cost_int(k1, k2, k3, &fp_rubric);
                if cost != 0 {
                    total_score = total_score.saturating_add(cost.saturating_mul(freq as i64));
                }
            }
        }

        total_score as f32 / SCORE_SCALE
    }
}

// --- Internal Fixed Point Logic ---

fn to_fixed(val: f32) -> i64 {
    if val.is_nan() {
        return 0;
    }
    if val.is_infinite() {
        return if val.is_sign_positive() {
            i64::MAX
        } else {
            i64::MIN
        };
    }
    // Saturate cast
    let scaled = val * SCORE_SCALE;
    if scaled >= i64::MAX as f32 {
        i64::MAX
    } else if scaled <= i64::MIN as f32 {
        i64::MIN
    } else {
        scaled as i64
    }
}

struct FixedPointKey {
    x: i64,
    y: i64,
    hand: u8,
    finger: u8,
    row: i8,
    col: i8,
}

struct FixedPointRubric {
    travel_lat: i64,
    travel_vert: i64,
    sfb_base: i64,
    sfb_lateral: i64,
    finger_effort: [i64; 5],
    redirect: i64,
    roll_bonus: i64,
}

fn calculate_pair_cost_int(
    k1: &FixedPointKey,
    k2: &FixedPointKey,
    rubric: &FixedPointRubric,
) -> i64 {
    if k1.x == k2.x && k1.y == k2.y {
        return 0;
    }

    let dx = (k1.x - k2.x).abs();
    let dy = (k1.y - k2.y).abs();

    // Fix: Use linear weight application on squared distance: Weight * Dist^2
    // allowing negative weights to act as bonuses.
    // Use i128 to prevent overflow during intermediate (Scale^3) multiplication.
    let scale_val = SCORE_SCALE as i128;
    let scale_sq = scale_val * scale_val;

    let term_x = (dx as i128)
        .saturating_mul(dx as i128)
        .saturating_mul(rubric.travel_lat as i128)
        / scale_sq;
    let term_y = (dy as i128)
        .saturating_mul(dy as i128)
        .saturating_mul(rubric.travel_vert as i128)
        / scale_sq;

    let dist_cost = term_x.saturating_add(term_y);

    let mut cost = if dist_cost > i64::MAX as i128 {
        i64::MAX
    } else if dist_cost < i64::MIN as i128 {
        i64::MIN
    } else {
        dist_cost as i64
    };

    if k1.hand != k2.hand {
        return cost;
    }

    if k1.finger == k2.finger {
        let col_diff = (k1.col - k2.col).abs();
        if col_diff == 1 {
            cost = cost.saturating_add(rubric.sfb_lateral);
        } else {
            cost = cost.saturating_add(rubric.sfb_base);
        }
        return cost;
    }

    let finger_diff = (k1.finger as i8 - k2.finger as i8).abs();
    let row_diff = (k1.row - k2.row).abs();

    if finger_diff == 1 && row_diff >= 2 {
        cost = cost.saturating_add(rubric.finger_effort[k1.finger as usize]);
    }

    if row_diff == 0 && finger_diff == 1 {
        let col_dist = (k1.col - k2.col).abs();
        if col_dist > 1 {
            cost = cost.saturating_add(rubric.sfb_lateral);
        }
    }

    cost
}

fn calculate_flow_cost_int(
    k1: &FixedPointKey,
    k2: &FixedPointKey,
    k3: &FixedPointKey,
    rubric: &FixedPointRubric,
) -> i64 {
    if k1.hand != k2.hand || k2.hand != k3.hand {
        return 0;
    }

    let f1 = k1.finger as i8;
    let f2 = k2.finger as i8;
    let f3 = k3.finger as i8;

    if f1 == f3 && f1 != f2 {
        return rubric.redirect;
    }

    let dir1 = f2 - f1;
    let dir2 = f3 - f2;

    if dir1 == 0 || dir2 == 0 {
        return 0;
    }

    if dir1.signum() != dir2.signum() {
        return rubric.redirect;
    }

    if dir1 < 0 {
        return rubric.roll_bonus.saturating_neg();
    }

    0
}

use keyforge_model::{Corpus, KeyNode, Keyboard, Layout, Rubric};
use keyforge_physics::ScoringEngine;
use std::sync::Arc;

fn setup_physics_engine() -> ScoringEngine {
    let keys = vec![
        KeyNode { id: 0, label: "A".to_string(), hand: 0, finger: 1, row: 1, col: 0, x: 0.0, y: 1.0, is_home: true },
        KeyNode { id: 1, label: "B".to_string(), hand: 0, finger: 2, row: 1, col: 1, x: 1.0, y: 1.0, is_home: true },
        KeyNode { id: 2, label: "C".to_string(), hand: 0, finger: 3, row: 1, col: 2, x: 2.0, y: 1.0, is_home: true },
        KeyNode { id: 3, label: "D".to_string(), hand: 1, finger: 1, row: 1, col: 6, x: 6.0, y: 1.0, is_home: true },
        // A scissor case: (0, 4) - finger 1 vs finger 1 is SFB, but let's do finger 1 vs finger 2 with row diff
        KeyNode { id: 4, label: "E".to_string(), hand: 0, finger: 1, row: 3, col: 0, x: 0.0, y: 3.0, is_home: false },
    ];
    let keyboard = Arc::new(Keyboard::new(keys, 1));

    let mut corpus = Corpus::default();
    corpus.char_freqs[0] = 100; // 'A'
    corpus.char_freqs[1] = 50;  // 'B'

    // SFB: A and E are on finger 1, hand 0
    corpus.bigrams.push((0, 4, 10)); 

    // Scissor: A (r1, f1) and B (r1, f2) - no. 
    // Let's do B (r1, f2) and E (r3, f1). Hand 0, Fingers 2 and 1, Row diff 2.
    corpus.bigrams.push((1, 4, 5));

    // Trigram Roll: C(f=3) -> B(f=2) -> A(f=1) (Outward roll on left hand)
    corpus.trigrams.push((2, 1, 0, 20));

    // Trigram Redirect: A -> C -> B 
    corpus.trigrams.push((0, 2, 1, 15));

    let rubric = Arc::new(Rubric::default());
    ScoringEngine::new(&keyboard, &Arc::new(corpus), &rubric, &[])
}

#[test]
fn test_analyze_layout_comprehensive() {
    let engine = setup_physics_engine();
    let layout = Layout::new(vec![0, 1, 2, 3, 4]);

    let report = engine.analyze(&layout);

    // Monogram Heatmap
    assert_eq!(report.heatmap[0], 100.0);
    assert_eq!(report.heatmap[1], 50.0);

    // SFB Ratio
    // Total bigrams = 10 (SFB) + 5 (Scissor) = 15
    // SFB total = 10
    // Ratio = 10/15 = 0.666
    assert!(report.sfb_ratio > 0.6 && report.sfb_ratio < 0.7);

    // Scissor
    assert!(report.scissors > 0.0);

    // Trigram Stats
    assert!(report.rolls > 0.0);
    assert!(report.redirects > 0.0);

    // Hand Balance
    // Left load: 100 (A) + 50 (B) + 0 (C) + 0 (E) = 150
    // Right load: 0 (D) = 0
    // Total: 150
    // Left ratio = 150/150 = 1.0
    // Balance = (1.0 - 0.5) * -2.0 = -1.0
    assert_eq!(report.hand_balance, -1.0);
}

#[test]
fn test_analyze_layout_empty() {
    let engine = setup_physics_engine();
    let layout = Layout::new(vec![]);
    let report = engine.analyze(&layout);
    assert_eq!(report.score, 0.0);
}

use keyforge_physics::{ScoringEngine, EngineContext};
use keyforge_model::{Keyboard, KeyNode, Corpus, Rubric};

#[test]
fn test_analyze_layout_comprehensive() {
    let keys: Vec<_> = (0..30).map(|i| KeyNode {
        id: i, label: format!("k{}", i), hand: (i % 2) as u8, finger: (i % 5) as u8,
        row: (i / 10) as i8, col: (i % 10) as i8, x: (i % 10) as f32, y: (i / 10) as f32, is_home: false,
    }).collect();
    let kb = Keyboard::new(keys, 1);

    let mut corpus = Corpus::default();
    // SFB: 0 and 2 are same hand (0) and finger (0)
    corpus.bigrams.push((0, 2, 100)); 
    // Scissor: 0 and 12 (hand 0, finger 0 vs hand 0, finger 2, rows 0 vs 1 - not a scissor)
    // Let's make a real scissor: 0 (r0, c0, f0) and 20 (r2, c0, f0) - same finger SFB again.
    // Scissor definition: (hands same) && (fingers diff by 1) && (rows diff >= 2)
    // 0 (hand0, finger0, row0) vs 21 (hand1, finger1, row2) - diff hands.
    // 0 (hand0, finger0, row0) vs 22 (hand0, finger2, row2) - fingers diff 2.
    // 2 (hand0, finger2, row0) vs 20 (hand0, finger0, row2) - fingers diff 2.
    // 0 (hand0, finger0, row0) vs 21? (Wait, finger is i%5, hand is i%2).
    // i=0: hand0, finger0, row0
    // i=1: hand1, finger1, row0
    // i=2: hand0, finger2, row0
    // i=3: hand1, finger3, row0
    // i=4: hand0, finger4, row0
    // i=10: hand0, finger0, row1
    // i=20: hand0, finger0, row2
    // SFB: 0 and 20 (hand0, finger0, r0 vs r2)
    corpus.bigrams.push((0, 20, 100));

    // Scissor: 0 (hand0, finger0, row0) and 22 (hand0, finger2, row2) - finger diff 2.
    // We need finger diff 1.
    // Let's use i=0 (f0, r0) and i=10 (f0, r1) - same finger SFB.
    // Let's use i=0 (f0, r0) and i=2(f2, r0)?
    // How about manual keys?

    let engine = ScoringEngine::new(&kb, &corpus, &Rubric::default(), &[]);
    let layout = keyforge_model::Layout::new((0..30).collect());
    let report = engine.analyze(&layout);

    assert!(report.score >= 0.0);
    assert!(report.sfb_total > 0.0);
}

