fn keyboard_strategy() -> impl Strategy<Value = Keyboard> {
    // Generate 10 to 50 keys
    (10..50usize).prop_flat_map(|count| {
        prop::collection::vec(
            (
                0.0..20.0f32, // x
                0.0..10.0f32, // y
                0u8..2,       // hand
                0u8..5,       // finger
                0i8..4,       // row
