/// Represents a request to optimize a keyboard layout.
/// This struct contains all necessary configuration, constraints, and data references.
#[derive(Serialize, Deserialize, Clone, Debug, ToSchema)]
pub struct JobRequest {
    /// Protocol version for compatibility checks.
    #[serde(default = "default_version")]
    pub version: u32,

    /// The physical geometry and metadata of the keyboard.
    pub definition: KeyboardDefinition,

    /// Physics engine scoring parameters (penalties and weights).
    pub weights: ScoringWeights,

    /// Simulated Annealing configuration (temperature, steps).
    pub params: SearchParams,

    /// Fixed keys (e.g., Space, Shift) that the optimizer cannot move.
    #[serde(default)]
    pub pinned_keys: Vec<KeyConstraint>,

    /// List of text corpora to use for frequency analysis.
    #[serde(default = "default_corpora")]
    pub corpora: Vec<CorpusSource>,

    /// Source of the cost matrix (Reference file or Custom CSV).
    #[serde(default = "default_cost_matrix")]
    pub cost_matrix: CostMatrixSource,

    /// Optional user-specific typing data for personalized optimization.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub biometrics: Vec<BiometricSample>,

    /// Optional ID of the job that spawned this one (for evolutionary lineage).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub parent_job_id: Option<String>,

    /// Optional baseline score to beat (from parent job).
    /// Used by agents to implement "Silence Protocol" (only report improvements).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub baseline_score: Option<f32>,

    /// List of parent layout strings (for diversity injection).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub parents: Vec<String>,
}

impl Validator for JobRequest {
    fn validate(&self) -> Result<(), String> {
        self.weights.validate()?;
        self.params.validate()?;
        self.definition.geometry.validate()?;

        if self.definition.geometry.keys.len() > constants::MAX_KEYBOARD_KEYS {
            return Err(format!(
                "Geometry exceeds maximum key limit ({})",
                constants::MAX_KEYBOARD_KEYS
            ));
        }

        if self.pinned_keys.len() > constants::MAX_PINNED_KEYS_COUNT {
            return Err("Pinned keys configuration too large".to_string());
        }

        if self.biometrics.len() > 10_000 {
            return Err("Too many biometric samples (Limit: 10,000)".to_string());
        }

        // Validate cost matrix source
        match &self.cost_matrix {
            CostMatrixSource::Predefined(s) => {
                if s.trim().is_empty() {
                    return Err("Predefined cost matrix filename cannot be empty".to_string());
                }
            }
            CostMatrixSource::Custom(s) => {
                if s.trim().is_empty() {
                    return Err("Custom cost matrix content cannot be empty".to_string());
                }
                // Basic CSV check
                if !s.contains(',') {
                    return Err("Custom cost matrix does not appear to be valid CSV".to_string());
                }
            }
        }

        // Validate constraints are within bounds
        let key_count = self.definition.geometry.keys.len();
        for (i, constraint) in self.pinned_keys.iter().enumerate() {
            if constraint.index as usize >= key_count {
                return Err(format!(
                    "Constraint #{} index {} out of bounds (max {})",
                    i,
                    constraint.index,
                    key_count - 1
                ));
            }
        }

        Ok(())
    }
}

