impl FromStr for KeyConstraint {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        if s.trim().is_empty() {
            return Err("Empty constraint".to_string());
        }

        let (idx_str, key_str) = s
            .split_once(':')
            .ok_or_else(|| format!("invalid format '{}': expected INDEX:KEY", s))?;

        let index = idx_str
            .trim()
            .parse::<u16>()
            .map_err(|_| format!("invalid index '{}': must be 0-65535", idx_str))?;

        let key_clean = key_str.trim();
        if key_clean.is_empty() {
            return Err(format!("Empty key in constraint '{}'", s));
        }

        Ok(KeyConstraint {
            index,
            key: key_clean.to_string(),
        })
    }
}

impl ResultSubmission {
    pub fn validate_timestamp(&self) -> Result<(), String> {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_err(|e| e.to_string())?
            .as_secs();

        // Allow 5 minutes drift
        if self.timestamp > now + 300 {
            return Err("Timestamp is in the future".into());
        }
        if self.timestamp < now.saturating_sub(300) {
            return Err("Timestamp is too old".into());
        }
        Ok(())
    }
}

