#[wasm_bindgen]
impl KeyforgeEngine {
    #[wasm_bindgen(constructor)]
    pub fn new() -> Self {
        console_error_panic_hook::set_once();
        Self {
            loader: InMemoryLoader::default(),
            engine: None,
